window.DATA={"prio": ["Muito alta", "Alta", "Média", "Baixa", "Muito baixa"], "topicos": [{"id": 1, "disc": "Direito Constitucional", "nome": "Sistemas e Espécies de Controle de Constitucionalidade", "prio": 0}, {"id": 2, "disc": "Direito Administrativo", "nome": "Contratos e Licitações Públicas", "prio": 0}, {"id": 3, "disc": "Administração Pública", "nome": "Planejamento Governamental", "prio": 0}, {"id": 4, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Espécies Normativas e Proposições Legislativas", "prio": 0}, {"id": 5, "disc": "Técnica Legislativa e Redação Oficial", "nome": "Fundamentos da Técnica Legislativa e Lei Complementar nº 95/1998", "prio": 0}, {"id": 6, "disc": "Legislação de Rio Verde", "nome": "Regimento Interno da Câmara Municipal de Rio Verde", "prio": 0}, {"id": 7, "disc": "Direito Constitucional", "nome": "Separação de Poderes e o Funcionamento do Poder Legislativo", "prio": 1}, {"id": 8, "disc": "Direito Administrativo", "nome": "Atos e Poderes Administrativos", "prio": 1}, {"id": 9, "disc": "Administração Pública", "nome": "Governança, Transparência e Accountability", "prio": 1}, {"id": 10, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Iniciativa e Tramitação de Proposições", "prio": 1}, {"id": 11, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Deliberação, Sanção, Veto e Promulgação", "prio": 1}, {"id": 12, "disc": "Técnica Legislativa e Redação Oficial", "nome": "Elaboração, Alteração e Consolidação de Atos Normativos", "prio": 1}, {"id": 13, "disc": "Legislação de Rio Verde", "nome": "Lei Orgânica do Município de Rio Verde", "prio": 1}, {"id": 14, "disc": "Legislação de Rio Verde", "nome": "Resolução nº 33/2000 e Dispositivos Regimentais Específicos", "prio": 1}, {"id": 15, "disc": "Direito Constitucional", "nome": "Teoria Geral e Aplicação dos Direitos e Garantias Fundamentais", "prio": 2}, {"id": 16, "disc": "Direito Constitucional", "nome": "Organização Político-Administrativa e o Regime dos Municípios", "prio": 2}, {"id": 17, "disc": "Direito Administrativo", "nome": "Princípios e Organização da Administração Pública", "prio": 2}, {"id": 18, "disc": "Direito Administrativo", "nome": "Processo Administrativo e Agentes Públicos", "prio": 2}, {"id": 19, "disc": "Administração Pública", "nome": "Organização Governamental e Gestão Pública", "prio": 2}, {"id": 20, "disc": "Administração Pública", "nome": "Ciclo e Formulação de Políticas Públicas", "prio": 2}, {"id": 21, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Competências e Funções da Câmara Municipal", "prio": 2}, {"id": 22, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Sessões Legislativas, Comissões e Mesa Diretora", "prio": 2}, {"id": 23, "disc": "Técnica Legislativa e Redação Oficial", "nome": "Redação Oficial e Redação Legislativa", "prio": 2}, {"id": 24, "disc": "Legislação de Rio Verde", "nome": "Revisão da Lei Orgânica e Normas Institucionais do Município", "prio": 2}, {"id": 25, "disc": "Legislação de Rio Verde", "nome": "Estrutura Organizacional da Câmara (Lei 7.434/2023)", "prio": 2}, {"id": 26, "disc": "Direito Administrativo", "nome": "Serviços, Controle, Improbidade e Bens Públicos", "prio": 3}, {"id": 27, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Fiscalização, Controle e Funções Institucionais da Câmara", "prio": 3}, {"id": 28, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Controle de Constitucionalidade e Jurisprudência no Processo Legislativo", "prio": 3}, {"id": 29, "disc": "Legislação de Rio Verde", "nome": "Plano de Cargos e Remuneração (Lei 7.435/2023)", "prio": 3}, {"id": 30, "disc": "Processo Legislativo e Atividade Parlamentar", "nome": "Hermenêutica Jurídica e Competências Legislativas", "prio": 4}, {"id": 31, "disc": "Língua Portuguesa", "nome": "Língua Portuguesa", "prio": 0}, {"id": 32, "disc": "Matemática", "nome": "Matemática", "prio": 1}, {"id": 33, "disc": "Informática", "nome": "Informática", "prio": 0}], "temas": [{"id": "v1-01", "src": "Apostila Vol. 1", "titulo": "Proposições: espécies e devolução ao autor", "fonte": "Regimento, arts. 164, 165 e seguintes (Aula 03)", "itens": ["<b>Espécies (art. 164): 6, rol taxativo.</b> Requerimentos, Moções, Projetos de Lei, Projetos de Decreto Legislativo, Projetos de Resolução e Emendas. Não existe uma sétima criada pela praxe. Devem ser redigidas em termos claros e sintéticos.", "<b>Devolução ao autor (art. 165):</b> (a) proposição <b>manifestamente</b> anti-regimental, ilegal ou inconstitucional; (b) que cite lei, decreto, regulamento, ato, contrato ou concessão sem anexar a transcrição do dispositivo; (c) emenda sem relação direta com a proposição. O vício controvertido não se devolve: vai para as comissões.", "O Presidente fundamenta a devolução <b>por escrito</b>. O autor pode <b>recorrer ao plenário</b> (arts. 256 e 257).", "Proposições subscritas pela <b>Comissão de Finanças, Justiça e Redação</b> não podem deixar de ser recebidas por alegada ilegalidade ou inconstitucionalidade.", "<b>Autor = primeiro signatário.</b> As demais assinaturas são de apoio, implicam concordância com o mérito e <b>não podem ser retiradas</b> depois da entrega à Mesa. O autor pode fundamentar por escrito ou verbalmente.", "<b>Renovação:</b> projeto de lei de iniciativa da Câmara e requerimentos, quando rejeitados ou não sancionados, só voltam na <b>mesma sessão legislativa</b> se reapresentados por, no mínimo, a <b>maioria absoluta</b> dos Vereadores.", "Proposição do suplente entregue à Mesa quando em exercício tem tramitação normal, mesmo que o titular tenha reassumido antes da leitura."], "top": 10}, {"id": "v1-02", "src": "Apostila Vol. 1", "titulo": "Requerimentos", "fonte": "Regimento, arts. 172 a 176 (Aula 03)", "itens": ["<b>Definição:</b> proposição dirigida por qualquer Vereador ou Comissão ao Presidente, sobre matéria de competência da Câmara.", "<b>Classificação (art. 172), três critérios:</b> maneira de formulá-los (verbais ou escritos); competência para decidi-los (despacho de plano do Presidente ou deliberação do plenário); fase de formulação (por exemplo, somente durante o expediente).", "<b>Despacho de plano (art. 173):</b> retirada pelo autor, retificação de ata, verificação de presença, requisição de documento existente na Câmara, juntada ou desentranhamento de documentos, inclusão na Ordem do Dia, informações oficiais sem deliberação do plenário, voto de pesar por falecimento, convocação de sessão extraordinária ou especial, justificação de falta, volta à tramitação de proposição arquivada em fim de legislatura. <b>Alíneas f a l são necessariamente escritas</b>; a, b e c podem ser verbais.", "<b>Plenário, sem discussão (art. 175), 10 hipóteses:</b> urgência, antecipação de discussão ou votação, retirada da pauta, preferência, votação de emendas em bloco, destaque, encerramento de discussão, licença do Prefeito, prorrogação da sessão e inversão da pauta. Não admitem discussão, encaminhamento nem declaração de voto, <b>exceto o encerramento de discussão, que admite encaminhamento</b>. Só antecipação (nº 2) e preferência (nº 4) podem ser verbais.", "<b>Plenário, com discussão (art. 176), sempre escritos:</b> convocação do Prefeito, Comissão Especial ou de Inquérito, informações com concordância do plenário, luto ou pesar por autoridade ou calamidade, voto de louvor ou congratulações, encerramento excepcional da sessão. Cada Vereador tem 5 minutos.", "<b>Inserção de documentos nos anais:</b> requerimento escrito, proposto por no mínimo <b>1/3</b> dos Vereadores.", "<b>Informação:</b> versa sobre atos da Mesa ou da Câmara, do Executivo e órgãos subordinados, autarquias, concessionárias e organismos oficiais de interesse comum."], "top": 10}, {"id": "v1-03", "src": "Apostila Vol. 1", "titulo": "Moções", "fonte": "Regimento, art. 179 (Aula 03)", "itens": ["<b>Definição:</b> proposição que sugere manifestação da Câmara sobre determinado assunto: aplaudindo, hipotecando solidariedade ou apoio, apelando, protestando ou repudiando. Não cria direitos nem obrigações.", "Subscrita por, no mínimo, <b>1/3</b> dos Vereadores. Depois de lida, vai à pauta da Ordem do Dia da <b>sessão ordinária seguinte</b>, <b>independentemente de parecer</b>, em <b>discussão e votação únicas</b>.", "<b>Não admite emendas.</b> Cada Vereador tem <b>5 minutos</b> para discutir."], "top": 10}, {"id": "v1-04", "src": "Apostila Vol. 1", "titulo": "Projetos: instrumentos, iniciativa e prazos", "fonte": "Regimento, arts. 183 a 185 e seguintes (Aula 03)", "itens": ["<b>Instrumentos da função legislativa (art. 183):</b> projeto de lei, de decreto legislativo e de resolução.", "<b>Projeto de lei (art. 184):</b> regula matéria legislativa de competência da Câmara e depende de sanção do Prefeito. Iniciativa: Vereador, Comissão, Mesa e Prefeito.", "<b>Iniciativa privativa do Prefeito (art. 185):</b> orçamento e matéria financeira; criação de cargos, funções e empregos, aumento de vencimentos e vantagens dos servidores da administração centralizada; aumento de despesa ou diminuição de receita. Nesses projetos <b>não se admitem emendas</b> que aumentem direta ou indiretamente a despesa, diminuam a receita ou alterem quantitativos de cargos.", "<b>Urgência do Prefeito:</b> a Câmara deve se manifestar sobre a proposição sem demora. Aprovado o projeto do Executivo (ou rejeitado na forma regimental), o Presidente comunica ao Prefeito em <b>48 horas</b>.", "<b>Prazos de apreciação:</b> projetos subscritos por <b>1/4</b> dos membros: concluir em <b>30 dias corridos</b> da apresentação. Subscritos por <b>1/3</b>: podem pedir <b>20 dias corridos</b>, faculdade que o mesmo Vereador usa <b>uma vez por ano</b>.", "Esgotados os prazos, o projeto vai <b>imediatamente à votação</b>. Projetos com prazo de apreciação fixado em lei, independentemente de parecer das Comissões, constam <b>obrigatoriamente</b> da Ordem do Dia."], "top": 10}, {"id": "v1-05", "src": "Apostila Vol. 1", "titulo": "Decreto legislativo e resolução", "fonte": "Regimento, arts. 190 e 191 e seguintes (Aula 03)", "itens": ["<b>Projeto de decreto legislativo (art. 190):</b> matéria que excede a economia interna da Câmara, <b>sem sanção</b>, promulgado pelo Presidente. Matérias: aprovação ou rejeição das <b>contas do município</b>; licença ao Prefeito; consentimento ao Prefeito; <b>remuneração do Prefeito e do Vice-Prefeito</b>; representação à Assembleia sobre modificação territorial ou mudança do nome da sede; <b>mudança do local de funcionamento da Câmara</b>.", "<b>Projeto de resolução (art. 191):</b> matéria político-administrativa da Câmara. Matérias: economia interna; fixação e alteração do <b>Regimento</b>; <b>perda do mandato</b> de Vereador; <b>destituição</b> de membro da Mesa; licença a Vereador; constituição de comissões especiais; <b>remuneração dos Vereadores</b>; julgamento do Vereador por infração político-administrativa; qualquer matéria regimental.", "<b>Macete:</b> Prefeito e Vice: decreto legislativo. Vereadores: resolução. Contas: decreto legislativo. Perda de mandato e destituição: resolução.", "<b>Requisitos dos projetos:</b> só a enumeração da vontade legislativa; artigos numerados, claros e concisos; menção de revogação das disposições em contrário, quando for o caso; <b>assinatura do autor</b>; <b>justificação</b> com exposição circunstanciada dos motivos de mérito.", "<b>Criação de cargos na secretaria da Câmara</b> por projeto de resolução: voto favorável da <b>maioria absoluta</b> dos membros."], "top": 10}, {"id": "v1-06", "src": "Apostila Vol. 1", "titulo": "Tramitação dos projetos, discussões e redação final", "fonte": "Regimento, arts. 194 a 216 (Aula 03)", "itens": ["<b>Protocolo (art. 194):</b> <b>3 dias úteis</b> antes das sessões, condição obrigatória para apresentação no expediente seguinte. Lido, é despachado <b>de plano</b> (sem votação) às Comissões Permanentes.", "<b>Ordem dos pareceres:</b> primeiro a <b>Comissão de Finanças, Justiça e Redação</b> (aspecto legal e constitucional); por último, a comissão específica (mérito). Emendas de comissão constantes de voto em separado ou voto vencido não são consideradas. É admitida a apresentação de emendas no transcorrer das discussões.", "<b>Dois turnos:</b> nenhum projeto é definitivamente aprovado sem <b>duas discussões e votações</b>, além da redação final. <b>Exceção:</b> projetos de resolução e de decreto legislativo, com <b>uma</b> discussão e votação e a redação final. Rejeitado em qualquer fase, o projeto é arquivado. Projetos são discutidos em bloco com as emendas.", "<b>Alteração do Regimento:</b> discussão em pelo menos <b>2 sessões ordinárias</b> (ou extraordinária convocada para isso).", "<b>1ª discussão:</b> <b>5 minutos</b> por Vereador; votação em bloco; <b>emendas votadas primeiro</b>, depois o projeto. Aprovado com emendas, o processo vai à <b>Procuradoria</b>, que tem <b>3 dias</b> para redigir (art. 205). <b>2ª discussão:</b> também 5 minutos (art. 204).", "<b>Redação final (arts. 206 a 210):</b> texto definitivo com as emendas aprovadas. A Procuradoria pode corrigir incorreção ou impropriedade de linguagem <b>se não alterar a vontade legislativa</b>, com menção expressa e justificação no parecer. Havendo dúvida sobre a vontade legislativa (incoerência notória, contradição evidente, manifesto absurdo), a Comissão <b>se exime</b> de oferecer redação e propõe a <b>reabertura da discussão</b>, com emendas só sobre o aspecto reaberto. Sem emendas, a redação é aprovada e o projeto segue à sanção ou à promulgação; com emendas de redação, volta à Comissão de Finanças, Justiça e Redação.", "<b>Projetos de lei com prazo (arts. 211 a 216):</b> lidos na primeira sessão ordinária e despachados. A Comissão de Finanças, Justiça e Redação tem <b>3 dias úteis</b> para o parecer legal e constitucional. Parecer <b>contrário</b>: vai à pauta da sessão seguinte, em votação única; <b>aprovado o parecer, o projeto é arquivado</b>; rejeitado, segue normalmente. Demais comissões: <b>3 dias úteis</b>; esgotado o prazo, o projeto entra em pauta <b>com ou sem parecer</b>, vedado adiar para ouvi-las.", "Aprovado em 1ª discussão, volta na <b>sessão ordinária seguinte</b> para a 2ª. Aprovado em 2ª, vai à redação final; rejeitado, <b>arquivo</b>."], "top": 10}, {"id": "v1-07", "src": "Apostila Vol. 1", "titulo": "Retirada, arquivamento e desarquivamento", "fonte": "Regimento, art. 220 e seguintes (Aula 03)", "itens": ["<b>Retirada (art. 220):</b> por requerimento do autor, <b>enquanto a proposição não tiver sido submetida à apreciação do plenário</b>. Se a proposição foi apontada como ilegal ou inconstitucional, a retirada é deferida de plano pelo Presidente. Se a autoria for da Mesa ou de Comissão, exige a maioria de seus membros.", "<b>Arquivamento:</b> no início de cada legislatura, arquivam-se as proposições que não tenham sido aprovadas em <b>pelo menos uma discussão</b>. <b>Não se aplica às proposições do Executivo.</b>", "<b>Desarquivamento:</b> requerimento do líder da bancada. Se a autoria for da Mesa ou de comissões permanentes, requerimento subscrito pela <b>maioria de seus membros</b>. <b>Não podem ser desarquivadas</b> as proposições inquinadas de inconstitucionalidade ou ilegalidade, nem as que tenham parecer contrário de comissões de mérito."], "top": 10}, {"id": "v1-08", "src": "Apostila Vol. 1", "titulo": "Discussão e apartes", "fonte": "Regimento, arts. 225 e 228 e seguintes (Aula 03)", "itens": ["<b>Discussão:</b> fase dos debates em plenário, anterior à votação.", "<b>Ordem da palavra:</b> primeiro o <b>autor</b>, depois os <b>relatores</b> das comissões na ordem em que se pronunciaram. Em projeto da Mesa ou de Comissão, autores são os respectivos Presidentes. Em projeto do Executivo, é considerado autor o Vereador com prerrogativas de líder, como intérprete do pensamento do Prefeito.", "<b>O Presidente não interrompe o orador, salvo (art. 225):</b> (a) para dar conhecimento de requerimento de prorrogação da sessão e votá-lo; (b) para comunicação importante, urgente e inadiável; (c) para suspender ou encerrar a sessão por tumulto grave. O orador interrompido para votar prorrogação não perde a vez, se estiver presente quando chamado a continuar.", "<b>Aparte:</b> interrupção <b>consentida</b>, breve, de até <b>1 minuto</b>, para pergunta, esclarecimento ou contestação. <b>O Presidente, ou quem o substitua, não aparteia o orador.</b>", "<b>Não são permitidos apartes (art. 228):</b> à palavra do Presidente na direção dos trabalhos; paralelos ou cruzados; quando o orador encaminha votação, faz declaração de voto ou fala sobre a ata; durante o expediente.", "<b>Encerramento da discussão:</b> por inexistência de orador ou por disposição legal. Não se encerra quando houver requerimento de adiamento pendente de votação por falta de quórum."], "top": 10}, {"id": "v1-09", "src": "Apostila Vol. 1", "titulo": "Votação: regras gerais e processos", "fonte": "Regimento, art. 246 e demais regras de votação (Aula 03)", "itens": ["<b>Fase de votação:</b> começa quando o Presidente declara encerrada a discussão. Se o tempo da sessão se esgotar durante a votação, a sessão é <b>prorrogada até concluí-la</b>; exceção: falta de número, e a sessão se encerra de imediato.", "<b>Dever de votar:</b> o Vereador presente não pode se escusar, mas deve <b>abster-se</b> quando ele ou parente afim ou consanguíneo <b>até o 3º grau</b> tiver interesse manifesto na deliberação, sob pena de <b>nulidade</b> se o voto for decisivo. A presença dele conta para quórum.", "<b>Voto do Presidente:</b> só na <b>eleição da Mesa</b>, nas votações que exigem <b>2/3</b> e em caso de <b>empate</b>. Vale também para quem o substitua.", "<b>Prejudicialidade:</b> votada uma proposição, as demais sobre o mesmo assunto na mesma sessão legislativa, ainda que não anexadas, ficam prejudicadas e vão ao arquivo.", "<b>Encaminhamento da votação:</b> depois de encerrada a discussão. Preferência: líder ou vice-líder da bancada, ou Vereador indicado. Havendo emendas, <b>um só encaminhamento</b> sobre todas as peças. 2 minutos, sem apartes.", "<b>Processos de votação: simbólico e nominal.</b> A votação secreta foi suprimida pela Resolução nº 17/2003. <b>Simbólico:</b> quem concorda permanece sentado, quem discorda levanta-se, e o Presidente conta. <b>Nominal:</b> consigna o nome e o voto de cada Vereador, chamada por <b>ordem alfabética</b>; se não houver quórum ao final, o secretário faz uma <b>segunda e última chamada</b> dos que não votaram.", "<b>Verificação nominal (art. 246):</b> dúvida sobre o resultado da votação simbólica. Se o requerimento ficar prejudicado por ausência do autor ou retirada, qualquer outro Vereador pode reformulá-lo.", "<b>Declaração de voto:</b> explica por que votou assim. Feita <b>de uma só vez</b>, depois de concluída a votação de todas as peças. <b>1 minuto</b>, sem apartes."], "top": 10}, {"id": "v1-10", "src": "Apostila Vol. 1", "titulo": "Tempos de uso da palavra", "fonte": "Regimento, art. 251 (Aula 03)", "itens": ["O tempo é <b>controlado pelo secretário</b>, para conhecimento do Presidente, e começa quando a palavra é dada. O prazo de interrupção, exceto <b>aparte concedido</b>, não conta.", "<b>Art. 251:</b>", "• Retificar ou impugnar ata: <b>5 min, sem apartes</b>.", "• Veto: <b>5 min, sem apartes</b>. Projeto: <b>5 min, com apartes</b>. Parecer pela inconstitucionalidade ou ilegalidade: 5 min, com apartes. Pareceres do TCM sobre contas da Mesa e do Executivo: 5 min, com apartes. Moções, requerimentos e recursos: 5 min, com apartes.", "• Destituição da Mesa ou de membros: <b>10 min</b> por Vereador e <b>20 min</b> para o denunciado, com apartes.", "• Cassação de mandato de Vereador: <b>15 min</b> por Vereador e <b>30 min</b> para o denunciado ou seu procurador, com apartes.", "• Assuntos parlamentares: <b>10 min, sem apartes</b>.", "• Explicação do autor ou dos relatores: 5 min, com apartes.", "• Encaminhamento de votação: <b>2 min, sem apartes</b>.", "• Declaração de voto: <b>1 min, sem apartes</b>. Pela ordem: <b>1 min, sem aparte</b>.", "• Esclarecimentos ao Prefeito e auxiliares: 5 min, sem apartes.", "<b>Macete:</b> o que muda de caso a caso é o aparte. Processos mais graves têm tempos maiores."], "top": 10}, {"id": "v1-11", "src": "Apostila Vol. 1", "titulo": "Questão de ordem, recurso contra decisão do Presidente e precedentes", "fonte": "Regimento, arts. 252, 256 e 257 e seguintes (Aula 03)", "itens": ["<b>Pela ordem (art. 252)</b>, o Vereador só pode falar para: reclamar de preterição de formalidade regimental; suscitar dúvida de interpretação do Regimento ou propor método quando for omisso; como líder, comunicar à Mesa; pedir prorrogação de Comissão Especial ou comunicar sua conclusão; retificar voto ou ata; pedir <b>censura</b> do Presidente a pronunciamento <b>injurioso</b> de outro Vereador; pedir esclarecimentos ao Presidente.", "<b>Não se admitem questões de ordem</b> quando o Presidente estiver com a palavra na direção dos trabalhos, quando houver orador na tribuna ou durante qualquer votação.", "<b>Recurso ao plenário</b> contra decisão ou omissão do Presidente em questão de ordem, representação ou proposição: <b>por escrito</b>, em <b>2 dias úteis</b> improrrogáveis. <b>Até o plenário decidir, prevalece a decisão do Presidente.</b>", "O Presidente tem 2 dias úteis improrrogáveis e encaminha o recurso à Comissão de Finanças, Justiça e Redação, que tem <b>2 dias úteis</b> para parecer. O recurso entra obrigatoriamente na pauta da <b>sessão ordinária seguinte</b>. Rejeitado por <b>maioria simples</b>, mantém-se a decisão. Aprovado, o Presidente deve cumpri-lo, <b>sob pena de destituição</b>.", "<b>Precedentes regimentais:</b> o plenário decide os casos omissos. Ao final de cada sessão legislativa, a Mesa, por ato, <b>consolida</b> todos os precedentes firmados e os publica em avulso para os Vereadores."], "top": 10}, {"id": "v1-12", "src": "Apostila Vol. 1", "titulo": "Sanção, veto, promulgação e registro", "fonte": "Regimento, arts. 277 a 279 e seguintes (Aula 03)", "itens": ["<b>Envio ao Prefeito:</b> o projeto aprovado vai ao Prefeito em <b>15 dias úteis</b> da aprovação, para sanção ou veto. O período de recesso não conta como dia útil.", "<b>Veto:</b> mensagem com as razões. A Câmara tem <b>30 dias úteis</b> do recebimento do ofício; em recesso, conta-se da primeira sessão ordinária após o recesso, em que o veto é lido obrigatoriamente. <b>Entrar em recesso interrompe o prazo.</b> O veto é matéria de urgência e é lido em qualquer fase da sessão.", "<b>Comissão de Finanças, Justiça e Redação</b> (razões de constitucionalidade, legalidade, interesse público ou financeiras): prazo improrrogável de <b>5 dias</b>. Esgotado, o veto entra na pauta da primeira sessão ordinária, <b>com ou sem parecer</b>.", "<b>Votação do veto:</b> aberta, única, com uma única discussão. Cédula única com dizeres antagônicos: <b>“Aceito o Veto”</b> e <b>“Rejeito o Veto”</b>.", "<b>Veto parcial:</b> votação <b>em bloco</b> quando a matéria for correlata ou idêntica. Caso contrário, é possível votar em separado cada disposição autônoma, a pedido de, no mínimo, <b>1/3</b> dos Vereadores, com assentimento do plenário e sem discussão, encaminhamento ou declaração de voto no requerimento.", "<b>Rejeição do veto (art. 279):</b> voto de, no mínimo, a <b>maioria absoluta</b>. Rejeitado, vai ao Prefeito para sanção. Se não sancionar em <b>48 horas</b>, o <b>Presidente da Câmara</b> promulga; se não o fizer em igual prazo, o <b>Vice-Presidente</b>.", "<b>Decretos legislativos e resoluções:</b> sem sanção. O <b>Presidente promulga</b> e envia à publicação em até <b>10 dias</b> da aprovação, improrrogáveis, ressalvadas as exceções regimentais.", "<b>Registro:</b> originais de leis, decretos legislativos e resoluções em livros próprios, rubricados pelo Presidente e arquivados na secretaria. Cópia autêntica ao Prefeito, assinada pelo <b>Presidente e pelo 1º Secretário</b> (ou substitutos).", "<b>Interpelação</b> de Vereadores sobre serviços e pessoal da secretaria: à Mesa, por meio do Presidente, <b>obrigatoriamente por escrito</b>."], "top": 11}, {"id": "v1-13", "src": "Apostila Vol. 1", "titulo": "Prefeito: convocação, comparecimento, contas e responsabilidade", "fonte": "Regimento, arts. 262 a 264, 283 e 286 (Aula 03)", "itens": ["<b>Convocação do Prefeito (art. 283):</b> para prestar informações sobre matéria de sua competência administrativa. Requerimento subscrito por no mínimo <b>1/3</b> dos Vereadores, discutido e votado, sem encaminhamento nem declaração de voto, com o <b>motivo</b> e os <b>quesitos</b>. Aprovado, o Presidente oficia o Prefeito e pede que marque dia e hora. O Prefeito atende em <b>15 dias</b> improrrogáveis do recebimento do ofício.", "<b>Sessão extraordinária da convocação:</b> o Prefeito tem <b>1 hora</b>, prorrogável por igual período por deliberação do plenário, <b>sem apartes</b>. Depois, cada Vereador tem <b>2 minutos</b> para pedir esclarecimentos, e o Prefeito tem <b>5 minutos</b> para cada resposta, sem apartes. Ninguém se desvia da matéria da convocação.", "<b>Comparecimento espontâneo (art. 286):</b> o Prefeito pode comparecer, em dia e hora previamente estabelecidos, sobre qualquer matéria, quando julgar oportuno. Faz exposição inicial e responde às interpelações. Aplicam-se as regras do artigo anterior (convocação).", "<b>Contas do Prefeito:</b> julgadas pela Câmara conforme as normas legais, em cada exercício. Rejeitadas, por votação ou por decurso de prazo, são <b>imediatamente remetidas ao Ministério Público</b>.", "<b>Responsabilidade do Prefeito</b> (crimes de responsabilidade): só decretada por no mínimo <b>2/3</b> dos Vereadores. Deliberando a Câmara pela responsabilidade, o Presidente inicia as medidas judiciais cabíveis.", "<b>Sessões extraordinárias convocadas pelo Prefeito (arts. 262 a 264):</b> as <b>Comissões Permanentes</b> com mandato extinto são <b>prorrogadas</b> até o fim das sessões extraordinárias. Tramitação dos projetos de lei com prazo de <b>30 dias</b>, respeitada a fase já iniciada. Aplicam-se as disposições regimentais não colidentes. Em recesso, o Presidente providencia a pronta publicação da convocação."], "top": 27}, {"id": "v1-14", "src": "Apostila Vol. 1", "titulo": "Títulos honoríficos e sessão solene", "fonte": "Regimento, arts. 266 e 270 (Aula 03)", "itens": ["<b>Instrumento:</b> <b>projeto de decreto legislativo</b>, em discussão e votação <b>únicas</b>, com <b>2/3</b> dos membros. Para personalidade nacional ou estrangeira radicada no País, comprovadamente digna da homenagem. A exigência de radicação cai para estrangeiros mundialmente consagrados.", "<b>Vedado</b> conceder a pessoas no exercício de <b>mandato eletivo</b> ou em <b>cargos executivos por nomeação</b>.", "<b>Instrução:</b> <b>biografia circunstanciada</b> e <b>anuência por escrito</b> do homenageado (exceto estrangeiros), como condição de recebimento pela Mesa. Os signatários são <b>fiadores</b> e não podem retirar a assinatura depois de recebido o projeto.", "<b>Limites:</b> cada Vereador, <b>2 proposições por ano</b> para cada tipo de honraria, e não pode ser primeiro signatário de mais de <b>duas</b> por sessão legislativa. Discussão: <b>5 minutos</b> por Vereador.", "<b>Sessão solene</b> de entrega: a critério do Presidente da Mesa, dentro do mandato do Vereador autor. No último ano do mandato, a propositura deve ser feita até a sessão ordinária de <b>junho</b>. Falam em nome da Câmara apenas: o <b>orador oficial</b> designado pelo Presidente, o <b>autor</b> e <b>um Vereador por partido ou bloco</b>."], "top": 22}, {"id": "v1-15", "src": "Apostila Vol. 1", "titulo": "Orçamento, segurança interna e galerias", "fonte": "Regimento, arts. 294 e 295 (Aula 03)", "itens": ["<b>Orçamento:</b> o Regimento não traz rito detalhado e <b>remete à Lei Orgânica</b>. É de iniciativa privativa do Prefeito. Não cabe destaque na proposta orçamentária, nas diretrizes, no PPA e no julgamento das contas.", "<b>Segurança do edifício (art. 294):</b> compete à <b>Mesa</b>, sob a direção do Presidente, por servidores próprios ou por entidade contratada e habilitada.", "<b>Galerias (art. 295):</b> qualquer cidadão pode assistir, em silêncio e respeito. Quem perturbar com aplausos ou reprovação e não atender à advertência é compelido a sair do edifício. Se o Presidente não mantiver a ordem por advertências, <b>suspende a sessão</b>. Se forem ineficazes as providências, quem perturbar ou desacatar é <b>detido e encaminhado à autoridade competente</b>.", "<b>No plenário, durante as sessões:</b> só Vereadores, servidores em serviço e convidados."], "top": 14}, {"id": "v1-16", "src": "Apostila Vol. 1", "titulo": "Painel eletrônico, destaque, preferência e redação final (parte final)", "fonte": "Regimento, arts. 298, 299 e 303 e seguintes (Aula 03)", "itens": ["<b>Regra (art. 298):</b> as deliberações se fazem pelo <b>Sistema Eletrônico de Votação (Painel)</b>. Se não for possível, aplicam-se as regras do art. 84 e seguintes. O voto no painel é livre e soberano e <b>não pode ser modificado depois de proclamado o resultado</b>. Considera-se a matéria em votação desde o encerramento da discussão. <b>O voto é sempre público</b> (art. 299).", "<b>Nominal é a regra geral.</b> O simbólico pode ser usado a requerimento de Vereador aprovado pelo plenário ou nos casos do Regimento. Da votação simbólica cabe verificação nominal; o Presidente <b>não pode indeferir</b>, e <b>não há segunda verificação</b>. Em dúvida, o Presidente pode repetir a votação simbólica de ofício.", "<b>A votação não pode ser simbólica</b> em: eleição ou destituição da Mesa; julgamento das contas do município; perda de mandato do Vereador ou do Prefeito; apreciação de veto; urgência especial; matérias de maioria absoluta ou 2/3.", "<b>Votação iniciada:</b> só se interrompe por falta de número legal, e os votos já colhidos ficam prejudicados. O Vereador não pode abandonar o plenário durante a votação, salvo mal súbito, e seu voto já dado é considerado.", "<b>Orientação de bancada (art. 303):</b> antes da votação, o líder da bancada ou integrante indicado fala <b>uma vez, por 3 minutos</b>. A votação só abre depois dos encaminhamentos. Qualquer Vereador pode encaminhar a matéria, independentemente da liderança.", "<b>Destaque:</b> o Vereador pede ao plenário que aprecie isoladamente parte do texto. <b>Não há destaque</b> em proposta orçamentária, diretrizes orçamentárias, PPA, julgamento das contas do município e quando for impraticável.", "<b>Preferência de votação:</b> emendas <b>supressivas</b> e emendas e substitutivos <b>das comissões</b>. Duas emendas sobre o mesmo artigo ou parágrafo: a protocolada <b>primeiro</b>. Parecer pela rejeição do projeto: o plenário vota <b>primeiro o parecer</b>.", "<b>Retificação de voto:</b> até a proclamação do resultado, exceto em votação por cédulas. <b>Impugnação</b> quando participou Vereador impedido: acolhida, <b>repete-se a votação sem o voto do impedido</b>. O painel exibe os detalhes por pelo menos <b>20 segundos</b>.", "<b>Redação final:</b> discutida e votada depois da publicação no sítio da Câmara ou levada ao conhecimento do plenário. <b>Emenda à redação final</b> só para eliminar obscuridade, contradição ou impropriedade linguística. Aprovada a emenda, volta à comissão. Se a nova redação for rejeitada, o projeto volta à comissão, e considera-se aprovada se contra ela não votar a <b>maioria absoluta</b> dos membros."], "top": 14}, {"id": "v1-17", "src": "Apostila Vol. 1", "titulo": "Reforma do Regimento Interno", "fonte": "Regimento, arts. 312 a 314 (Aula 03)", "itens": ["<b>Instrumento:</b> o Regimento só pode ser alterado, reformado ou substituído por <b>Resolução</b> (art. 312).", "<b>Legitimados (art. 313):</b> no mínimo <b>1/3</b> dos membros da Câmara, ou a <b>Mesa Diretora</b>.", "<b>Vigência (art. 314):</b> na data da publicação, revogadas as disposições contrárias.", "Lembre: a discussão da reforma ocorre em pelo menos 2 sessões ordinárias."], "top": 14}, {"id": "v1-18", "src": "Apostila Vol. 1", "titulo": "Lei nº 7.434/2023: Estrutura Organizacional da Câmara", "fonte": "Leis 7.434 e 7.435/2023 (Aula 00 / demo)", "itens": ["<b>Objeto:</b> Regulamento Interno da Estrutura Organizacional da Câmara, com atribuições e subordinação das unidades. A <b>Direção Superior</b> é exercida pela <b>Mesa Diretora</b>, por meio do Presidente, auxiliado por Vereadores, diretores, procuradores, assessores e servidores. Os integrantes da Mesa estão no <b>Regimento Interno</b>.", "<b>Gestão participativa e atuação sistêmica:</b> a gestão busca transparência e controle social. As competências das unidades de gestão institucional são planejadas, coordenadas e controladas de forma <b>centralizada</b>, por <b>sistemas estruturantes</b>. As unidades que exercem funções desses sistemas se subordinam <b>tecnicamente</b> à unidade central do sistema.", "<b>Função legislativa:</b> cumprir e fazer cumprir a Constituição Federal, a Estadual e a Lei Orgânica, apreciar e aprovar leis de interesse do Município e fiscalizar a execução orçamentária, financeira e patrimonial do Executivo.", "<b>Estrutura administrativa (art. 6º), subordinada ao Presidente e à Mesa:</b> <b>Presidência</b>, <b>Diretorias</b> e <b>Coordenadorias Setoriais</b>. Os <b>Gabinetes Parlamentares não compõem</b> a estrutura: são órgãos independentes, formados pelos auxiliares, assistentes e assessores de um legislador.", "<b>Presidência (Gabinete):</b> Chefia de Gabinete (com Assessoria Jurídica da Presidência), Ouvidoria, Corregedoria Parlamentar, Procuradoria Geral (com Assessoria Jurídica), Controle Interno (Núcleo de Apoio ao Controle Interno e Núcleo de Auditoria e Exame de Contas), Assessoria de Plenário (Assessoria Executiva Parlamentar e Assessoria Executiva de Cerimonial) e Assessoria de Imprensa da Presidência.", "<b>10 Diretorias:</b> Legislativa; Parlamentar; Gestão de Pessoas; Tecnologia em Informação; Administração e Planejamento; Financeira; Comunicação Social; Assuntos Institucionais; Contratos e Convênios; Articulação Política.", "<b>Dentro das Diretorias:</b> <b>Legislativa</b>: Núcleo de Apoio Legislativo, Gerência de Expediente e Protocolo e <b>Coordenadoria Legislativa de Plenário</b> (Gerências de Apoio Legislativo, Processamento e Controle, e Redação de Atas). <b>Parlamentar</b>: Núcleo de Apoio Parlamentar e Gerência de Expediente e Protocolo. <b>Gestão de Pessoas</b>: Chefia de Pessoal e Gerência de Arquivo e Documentação. <b>TI</b>: Gerências de Suporte de Informática e de Desenvolvimento de Sistemas. <b>Financeira</b>: Gerências de Tesouraria, Contabilidade e Planejamento Orçamentário e Financeiro. <b>Comunicação Social</b>: Gerência de Imprensa e Comunicação (Assessorias de Comunicação, de Imprensa, de Mídias Digitais e de Relações Públicas) e Gerência de Gravação e Som. <b>Contratos e Convênios</b>: Gerência de Contratos e Assessoria de Convênios e Projetos.", "<b>6 Coordenadorias Setoriais:</b> Almoxarifado e Patrimônio (Núcleo de Almoxarifado); Compras e Licitações (<b>Agente de Contratação</b> e Gerência de Cotação de Preços); Manutenção e Serviços Gerais; Relações Públicas; Folha de Pagamento; Engenharia e Projetos.", "<b>Diretrizes (art. 10):</b> <b>estrutura básica de direção superior</b>, que unifica numa só autoridade comando, coordenação, controle, planejamento estratégico e articulação institucional; <b>gerência intermediária</b>, que agrupa direção intermediária, planejamento, coordenação, controle, supervisão, orientação técnica e gerência administrativa; <b>assessoramento</b>, que dá apoio direto em atribuições técnico-especializadas de consultoria, assessoramento e assistência.", "<b>Disposições finais:</b> casos omissos são resolvidos pela <b>Mesa Diretora</b>. Os cargos efetivos e em comissão e as remunerações estão no <b>Plano de Cargos e Remuneração</b> (Lei 7.435)."], "top": 25}, {"id": "v1-19", "src": "Apostila Vol. 1", "titulo": "Lei nº 7.435/2023: Plano de Cargos e Remuneração", "fonte": "Leis 7.434 e 7.435/2023 (Aula 00 / demo)", "itens": ["<b>Objeto:</b> plano de cargos e remuneração dos servidores do Quadro da Câmara. <b>Regime jurídico: Estatutário</b>. O Plano organiza os cargos <b>efetivos</b> em carreira (qualificação profissional, valorização da função pública, aperfeiçoamento do servidor) e os cargos <b>em comissão</b>, de livre nomeação e exoneração.", "<b>Cargo público:</b> conjunto de atribuições e responsabilidades, criado por lei, com denominação própria, número certo e pagamento pelo Erário Municipal. <b>Quadro de Cargos:</b> conjunto correlacionado de cargos por natureza, objetivos, legislação, atribuições etc.", "<b>Conceitos:</b> <b>Grupo</b> (categorias funcionais semelhantes quanto à natureza do serviço e ao nível de conhecimento); <b>Categoria Funcional</b> (atribuições agrupadas por espécie de atividade e especialização); <b>Classe</b> (categorias do mesmo cargo e da mesma remuneração); <b>Cargo</b> (atividade básica do quadro de pessoal); <b>Padrão</b> (posição na escala de remuneração, identificada por <b>letra e algarismo arábico</b>); <b>Nível</b> (grau de instrução formal).", "<b>3 níveis:</b> Básico (ensino fundamental), Médio (ensino médio) e Superior (curso superior ou técnico).", "<b>Quadro Permanente:</b> cargos efetivos e em comissão necessários às funções permanentes. <b>Direção</b> (posições mais elevadas), <b>Chefia</b> (posição mais elevada de uma unidade) e <b>Assessoramento</b> (auxílio por conhecimento ou qualificação). As funções comissionadas foram transformadas em <b>cargos de provimento em comissão (DAS)</b>, graduados em <b>4 níveis</b>, conforme complexidade e poder decisório, grau de responsabilidade, número de unidades e servidores subordinados e volume de processos.", "<b>Servidor efetivo em cargo em comissão:</b> pode optar pela <b>remuneração integral</b> do comissionado ou pela de origem <b>mais 80%</b> do comissionado. Quem opta pelo cargo de origem recebe a gratificação de representação.", "<b>Ingresso (art. 13):</b> no padrão inicial, por concurso público de <b>provas e títulos</b>. O tempo de serviço prestado à Câmara conta como título. <b>Desenvolvimento (§ 1º):</b> de um padrão para o seguinte em <b>3%</b>, alternando <b>merecimento</b> (avaliação de desempenho) e <b>antiguidade</b> (interstício de <b>3 anos</b>).", "<b>Capacitação:</b> a <b>Mesa Diretora</b>, com a <b>Diretoria de Gestão de Pessoas</b>, institui programa permanente de treinamento e desenvolvimento.", "<b>Mudanças de nome:</b> Secretária para <b>Assistente Administrativo</b>; Telefonista para <b>Ouvidor</b>; Vigia para <b>Operador de Videomonitoramento</b>; Agente Administrativo para <b>Supervisor Administrativo</b>. O cargo em comissão de Procurador Adjunto passa a <b>Assessor Jurídico da Procuradoria Geral</b>.", "<b>Reenquadramento (art. 17, § 3º):</b> quem exerceu atribuições de outros cargos por mais de <b>5 anos consecutivos</b> ou <b>10 intercalados</b> poderá ser reenquadrado, por <b>lei específica</b>.", "<b>Jornada:</b> <b>8 horas diárias e 40 semanais</b>; o <b>Ouvidor</b> tem <b>6 horas diárias e 30 semanais</b>.", "<b>Estágio probatório:</b> suspenso para quem ocupar cargo em comissão e durante licenças e afastamentos, <b>exceto</b> se a função for compatível ou correlata ao cargo de origem, se exerceu função comissionada de maior complexidade do cargo de origem (comprovada e justificada) ou se for cedido ao Executivo, Fundação ou Autarquia <b>com ônus para o requisitante</b>.", "<b>Gratificação de Função:</b> para servidores efetivos com encargos especiais, em percentuais sobre o vencimento base, em quadro único. Concedida por <b>ato do Presidente</b>, com <b>justificativa</b> e <b>descrição das atribuições</b>. <b>Não integra a remuneração na aposentadoria.</b> Não se aplica a quem tem cargo em comissão.", "<b>Enquadramento:</b> consolida-se com a publicação do ato e a expedição de <b>apostila</b>. O servidor pode pedir <b>revisão</b> à Diretoria de Gestão de Pessoas em <b>30 dias</b> da publicação do apostilamento. Recurso à Presidência em 30 dias da ciência; à Mesa Diretora, em última instância administrativa, 30 dias.", "<b>Despesas:</b> à conta do Orçamento-Geral do Município, nas rubricas da Câmara, obedecida a <b>LC nº 101/2000</b>. A Mesa pode baixar atos complementares. Direitos e vantagens (diárias, férias, licenças etc.) seguem a legislação pertinente."], "top": 29}, {"id": "v2-01", "src": "Apostila Vol. 2", "titulo": "Mesa Diretora: composição e eleição", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>Composição:</b> Presidente, Vice-Presidente, 1º Secretário e 2º Secretário. <b>Mandato: 2 sessões legislativas.</b>", "<b>Eleição:</b> <b>maioria simples</b>, voto <b>secreto</b>, em cédula.", "<b>Empate:</b> vence a chapa do candidato a Presidente <b>mais idoso</b>.", "A eleição para a <b>3ª e a 4ª sessões</b> é feita em sessão <b>extraordinária</b>, entre <b>1º de outubro e 30 de dezembro</b>."], "top": 22}, {"id": "v2-02", "src": "Apostila Vol. 2", "titulo": "Mesa: fim das funções, vaga e atribuições", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>Art. 7º, as funções da Mesa cessam por:</b> morte; posse da Mesa eleita no 3º período; renúncia por escrito; destituição; perda de mandato; ordem judicial.", "<b>Vaga na Mesa:</b> preenchida em <b>30 dias</b>.", "Membros da Mesa integram <b>uma</b> comissão permanente; o <b>Presidente, nenhuma</b>. (Os demais Vereadores: até 3.)", "<b>Sem quórum</b> para abrir a sessão: aguarda-se <b>15 minutos</b>. Persistindo, não se abre.", "As atribuições coletivas da Mesa estão no art. 13."], "top": 22}, {"id": "v2-03", "src": "Apostila Vol. 2", "titulo": "Presidente da Câmara", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>Vota só nos casos regimentais</b> (não vota sempre).", "<b>Promulga:</b> resoluções, decretos legislativos e leis de <b>veto rejeitado</b>.", "<b>Resenha</b> dos trabalhos: na <b>última sessão ordinária do ano</b>.", "<b>Certidões</b> requeridas: expedidas em <b>15 dias</b>.", "Para agir juridicamente em nome da Câmara fora das hipóteses regimentais, <b>consulta o Plenário</b> (art. 16, parágrafo único)."], "top": 22}, {"id": "v2-04", "src": "Apostila Vol. 2", "titulo": "1º Secretário, renúncia e destituição da Mesa", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>1º Secretário (art. 25):</b> lê os papéis do expediente, recebe e guarda proposições, redige as atas.", "<b>Renúncia (art. 27):</b> por <b>ofício</b>, <b>efetiva com a leitura em sessão</b>.", "<b>Destituição (art. 28):</b> <b>2/3</b> dos Vereadores (14 de 21) e <b>ampla defesa</b>.", "<b>Representação (art. 29):</b> recebida por <b>maioria absoluta</b> (11). <b>Comissão Processante</b> de <b>3 sorteados</b>, que se reúne em <b>48h</b>.", "<b>Prazos:</b> notificação em <b>3 dias</b>; defesa prévia em <b>10 dias</b>; parecer em <b>20 dias improrrogáveis</b>.", "<b>Votação:</b> aberta. Parecer pela <b>improcedência</b>: maioria simples. Destituição: <b>2/3</b>. Tempo: <b>20 min</b> por Vereador, <b>60 min</b> relator e acusado. Resolução promulgada em <b>48h</b>."], "top": 22}, {"id": "v2-05", "src": "Apostila Vol. 2", "titulo": "Comissões permanentes: composição e constituição", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>3 membros:</b> Presidente, Relator e Vogal.", "Cada Vereador, no máximo em <b>3 comissões</b>. Mandato até o <b>fim da sessão legislativa</b>.", "Constituídas na <b>1ª sessão ordinária da 1ª e da 3ª sessões legislativas</b>, em <b>votação aberta</b> por cédula.", "<b>ATENÇÃO, versões diferentes:</b> o material do curso (Res. 01/2026) lista <b>15 comissões</b>; o site da Câmara (consolidado até a Res. 05/2026) indica <b>16</b>. Não cravar o número sem ver a versão do texto da prova."], "top": 22}, {"id": "v2-06", "src": "Apostila Vol. 2", "titulo": "Competências das comissões e Comissão de Ética", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["Competências específicas (arts. 47 e 48) e competência comum (art. 50). A comissão que cuida de constitucionalidade, legalidade e redação analisa a admissibilidade jurídica das proposições.", "<b>Comissão de Ética:</b> denúncia subscrita por <b>1/3</b>; notificação do acusado em <b>72h</b>; defesa em <b>10 dias</b>; conclusão em <b>60 dias, prorrogáveis por igual período</b>.", "<b>Cassação:</b> <b>2/3</b>. <b>Absolvição:</b> <b>maioria absoluta</b>.", "Parecer por <b>inconstitucionalidade</b> da comissão jurídica: vai ao <b>Plenário</b>, em <b>discussão e votação únicas</b>."], "top": 22}, {"id": "v2-07", "src": "Apostila Vol. 2", "titulo": "Pareceres: forma e prazos", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>Parecer (art. 66):</b> 3 partes.", "<b>Relator:</b> 2 dias. <b>Pedido de vista:</b> 24h; suspensão total de, no máximo, <b>6 dias corridos</b>.", "<b>Voto em separado (art. 69):</b> <b>pelas conclusões</b>, <b>aditivo</b> ou <b>contrário</b>."], "top": 22}, {"id": "v2-08", "src": "Apostila Vol. 2", "titulo": "Comissões especiais e de inquérito", "fonte": "Regimento, Aula 01 (Mesa, Presidente, Comissões)", "itens": ["<b>Especial (arts. 72 a 75):</b> requerimento subscrito por <b>1/3</b> e aprovado por <b>maioria simples</b>, indicando finalidade, número de membros e prazo. Se não concluir no prazo, é <b>extinta</b>. Não trata de matéria de comissão permanente.", "<b>Inquérito (art. 76):</b> processa Prefeito e Vereadores por infrações do <b>DL 201/67</b>; denúncia por <b>1/3</b> + maioria simples; <b>5 Vereadores</b>.", "Defesa em <b>10 dias</b>, até <b>10 testemunhas</b>. Cassação por <b>2/3</b>, votação <b>nominal</b> por infração."], "top": 22}, {"id": "v2-09", "src": "Apostila Vol. 2", "titulo": "Maiorias e competências da Câmara", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["<b>Maioria absoluta:</b> mais da metade dos <b>membros</b> (11 de 21). <b>Simples:</b> maioria dos <b>presentes</b>. <b>Relativa:</b> mais votos. <b>2/3:</b> 14 de 21.", "<b>Art. 86:</b> competências da Câmara <b>com</b> sanção do Prefeito (leis) e <b>sem</b> sanção (resoluções e decretos legislativos)."], "top": 6}, {"id": "v2-10", "src": "Apostila Vol. 2", "titulo": "Vereadores: posse, deveres, faltas e licenças", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["<b>Posse:</b> com declaração de bens. Deveres no art. 88; vedações constitucionais, da Lei Orgânica e do Regimento.", "<b>Faltas justificadas</b> mediante documentos; <b>3 dias por óbito</b>.", "<b>Licenças (art. 92):</b> saúde, missão, cargo. Efetivam-se com a <b>leitura em sessão</b>. Suplente só após <b>120 dias</b>; convocado em <b>48h</b>."], "top": 6}, {"id": "v2-11", "src": "Apostila Vol. 2", "titulo": "Vagas, perda do mandato, líderes e remuneração", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["<b>Vaga (art. 105):</b> morte, renúncia ou perda do mandato. Licença não gera vaga.", "<b>Perda do mandato (art. 107):</b> 7 hipóteses. Cassação por <b>2/3</b> (arts. 110 a 112).", "<b>Líderes:</b> indicados no <b>início da sessão legislativa</b>.", "<b>Remuneração:</b> fixada por <b>resolução</b> até <b>30 dias antes das eleições</b>."], "top": 6}, {"id": "v2-12", "src": "Apostila Vol. 2", "titulo": "Sessões: regras gerais", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["<b>Espécies (art. 113):</b> solenes, ordinárias e extraordinárias (e as especiais). <b>Públicas</b>; sigilo por <b>maioria absoluta</b>.", "<b>Duração: 2h.</b> Segunda chamada em <b>15 min</b>.", "<b>Suspensão:</b> 15 min para parecer; 5 min para bancada.", "<b>Prorrogação:</b> requerimento até <b>10 min</b> antes do fim; não ultrapassa <b>24h</b>.", "<b>Ata:</b> leitura obrigatória (art. 123)."], "top": 22}, {"id": "v2-13", "src": "Apostila Vol. 2", "titulo": "Sessões ordinárias e Ordem do Dia", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["<b>Ordinárias:</b> 1ª semana útil do mês, seg a sex, <b>19h</b>. <b>Recesso:</b> janeiro e julho. Maioria absoluta para abrir e prosseguir.", "<b>Sequência:</b> Expediente, Ordem do Dia, Assuntos Parlamentares. Ordem do <b>Expediente taxativa</b> (art. 129).", "<b>Ordem do Dia:</b> vetos, redação final, 2ª discussão, 1ª discussão, moções, requerimentos e recursos. Entre as espécies: <b>PL, PR, PDL</b>.", "<b>Alteração</b>: só nas <b>5</b> hipóteses do art. 135. Urgência (136) e inversão (137)."], "top": 22}, {"id": "v2-14", "src": "Apostila Vol. 2", "titulo": "Assuntos parlamentares", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["Exigem pelo menos <b>1/3</b> dos Vereadores presentes (<b>7</b>).", "<b>15 min</b> por orador, <b>um aparte</b> da situação e <b>um</b> da oposição. Sem prorrogação.", "<b>Inscrição</b> até o fim do Expediente."], "top": 22}, {"id": "v2-15", "src": "Apostila Vol. 2", "titulo": "Sessões extraordinárias e especiais", "fonte": "Regimento, Aula 02 (Plenário, Vereadores, Sessões)", "itens": ["<b>Extraordinária:</b> convocada pela <b>Mesa</b>, por <b>1/3</b> ou pelo <b>Prefeito</b>. Antecedência de <b>3 dias</b>, salvo extrema urgência. Indica dia, hora e Ordem do Dia. <b>Maioria absoluta</b> para abrir.", "Só há <b>Ordem do Dia fechada</b>. Alterável apenas para licença, posse e retirada de proposição. Sem assuntos parlamentares. No recesso, só calamidade pública ou interesse público.", "<b>Especial:</b> solenidades. Maioria absoluta; <b>sem duração fixa</b>. Convocada pelo Presidente de ofício ou por <b>1/3</b> (deferimento de plano). Sem deliberação legislativa ordinária."], "top": 22}, {"id": "v3-01", "src": "Apostila Vol. 3", "titulo": "Município na Constituição e a Lei Orgânica", "fonte": "LOM, Aula 01 (art. 29 da CF)", "itens": ["Município é <b>ente federativo autônomo</b> (federação de 3º grau). Autonomia política: <b>auto-organização, autolegislação, autoadministração, autogoverno</b>. Soberania só da República.", "<b>LOM:</b> votada em <b>2 turnos</b>, interstício mínimo de <b>10 dias</b>, aprovada por <b>2/3</b> dos membros da Câmara (macete <b>DDD</b>), que a promulga. Não é poder constituinte derivado decorrente.", "<b>Poderes do Município (art. 5º):</b> Legislativo e Executivo, independentes e harmônicos. Não existe Judiciário municipal.", "<b>Símbolos:</b> Bandeira, Hino e Brasão. <b>Data magna:</b> 5 de agosto."], "top": 16}, {"id": "v3-02", "src": "Apostila Vol. 3", "titulo": "Art. 29 da CF: eleições, Vereadores e limites", "fonte": "LOM, Aula 01", "itens": ["<b>Prefeito e Vice:</b> mandato de 4 anos; eleição no <b>1º domingo de outubro</b> do ano anterior ao término do mandato; <b>2º turno</b> só em Municípios com <b>mais de 200 mil eleitores</b> (eleitores, não habitantes); posse em <b>1º de janeiro</b>.", "<b>Vereadores:</b> sistema proporcional; número máximo conforme a população (9 até 15 mil habitantes; 55 acima de 8 milhões). Subsídio fixado em cada legislatura <b>para a subsequente</b>, com teto em % do subsídio do Deputado Estadual (20% a 75%).", "<b>5%</b> da receita do Município: teto da despesa com remuneração dos Vereadores (art. 29, VII).", "<b>Art. 29-A:</b> despesa total do Legislativo de <b>7% a 3,5%</b> (por faixa de população) sobre a receita tributária e transferências do <b>exercício anterior</b>; folha da Câmara até <b>70%</b> da receita da Câmara; repasse até o <b>dia 20</b> de cada mês (crime de responsabilidade do Prefeito).", "<b>Iniciativa popular:</b> 5% do eleitorado. Inviolabilidade (imunidade material) por opiniões, palavras e votos, no exercício do mandato e na circunscrição do Município."], "top": 16}, {"id": "v3-03", "src": "Apostila Vol. 3", "titulo": "Competências do Município", "fonte": "LOM, Aula 01 (CF arts. 22, 23, 30; LOM arts. 7º a 11)", "itens": ["<b>Privativas (LOM art. 7º):</b> rol exemplificativo (“dentre outras”). Legislar sobre interesse local, orçamento, tributos, distritos, transporte coletivo (essencial), serviço funerário, Guarda Municipal, etc.", "<b>Educação:</b> mínimo de <b>25%</b> da receita de impostos, incluídas as transferências. <b>Contas</b> à disposição de qualquer contribuinte por <b>60 dias</b>, anualmente.", "<b>Comum</b> (art. 10): atuação administrativa compartilhada com União e Estado. Moradias populares em regime de <b>comodato</b>. Normas de cooperação: <b>lei complementar federal</b>.", "<b>Suplementar</b> (art. 11): complementa a legislação federal e estadual no que couber.", "<b>STF:</b> horário de comércio é municipal (SV 38); horário de <b>agências bancárias</b> não é; trânsito e transporte é da <b>União</b> (art. 22, XI)."], "top": 16}, {"id": "v3-04", "src": "Apostila Vol. 3", "titulo": "Vedações ao Município", "fonte": "LOM, Aula 01 (art. 12 da LOM)", "itens": ["Vedado: estabelecer cultos ou subvencioná-los (ressalvada a <b>colaboração de interesse público</b>, na forma da lei); recusar fé a documentos; distinguir brasileiros; usar bens para fins estranhos à administração.", "<b>Doação de imóveis, ônus real, isenções e remissões</b> fora do manifesto interesse público: exigem <b>expressa autorização da Câmara</b>, sob pena de nulidade.", "<b>Publicidade</b> só com caráter educativo, informativo ou de orientação social, <b>sem promoção pessoal</b>.", "<b>Alienação de bens</b> vedada nos <b>últimos 3 meses</b> do mandato do Prefeito (art. 33, XVII)."], "top": 13}, {"id": "v3-05", "src": "Apostila Vol. 3", "titulo": "Câmara: composição, períodos e sessões", "fonte": "LOM, Aula 01 (arts. 13 a 20)", "itens": ["<b>21 Vereadores</b>, sistema proporcional, mandato de 4 anos. <b>Legislatura:</b> 4 anos. <b>Sessão legislativa:</b> cada ano. Maioria absoluta = 11; 1/3 = 7; 2/3 = 14.", "<b>Períodos:</b> 2 de fevereiro a 17 de julho e 1º de agosto a 22 de dezembro. Sessões ordinárias, extraordinárias ou solenes (Regimento).", "<b>Convocação extraordinária:</b> Prefeito; Presidente (posse do Prefeito e Vice, ou urgência/interesse público relevante a requerimento da maioria); Comissão Representativa. <b>Sem remuneração</b> extra.", "<b>Deliberações (art. 16):</b> maioria de votos, presente a maioria dos membros. Abertura da sessão: art. 20. <b>Sessão pública</b>; sigilo por <b>2/3</b> (art. 19). A sessão legislativa não é interrompida sem votar a lei orçamentária (art. 17).", "<b>CUIDADO:</b> o Regimento (curso) trata o sigilo por <b>maioria absoluta</b>. Diplomas diferentes, regras diferentes."], "top": 21}, {"id": "v3-06", "src": "Apostila Vol. 3", "titulo": "Posse, Mesa e Comissão Representativa", "fonte": "LOM, Aula 01 (arts. 21 a 27)", "itens": ["<b>1º de janeiro:</b> sessão solene de posse, com qualquer número, presidida pelo Vereador <b>mais votado</b> dentre os presentes. Eleição da Mesa logo em seguida, com <b>maioria absoluta</b> (11). Sem quórum: sessões diárias até eleger.", "Vereador que não tomar posse na sessão: <b>15 dias</b>, sob pena de perda do mandato, salvo motivo justo aceito pela maioria.", "<b>Mesa:</b> Presidente, Vice, 1º e 2º Secretário, que se substituem nessa ordem; na ausência de todos, preside o <b>mais idoso</b>. Destituição: <b>2/3</b> (faltoso, omisso ou ineficiente).", "<b>Mandato da Mesa (LOM, art. 21, § 4º):</b> um ou mais anos, vedada a recondução imediata para o mesmo cargo. <b>CUIDADO:</b> o Regimento fala em duas sessões legislativas.", "<b>Comissão Representativa:</b> eleita ao fim de cada sessão legislativa, <b>voto secreto</b>, número <b>ímpar</b>, presidida pelo Presidente da Câmara; funciona no recesso; reúne-se 1 vez por semana."], "top": 22}, {"id": "v3-07", "src": "Apostila Vol. 3", "titulo": "Comissões, CPI, Secretários e Líderes", "fonte": "LOM, Aula 01 (arts. 23 a 30)", "itens": ["<b>Comissões permanentes:</b> discutem e votam projetos dispensados do Plenário, salvo recurso de <b>1/3</b>; audiências públicas; fiscalização.", "<b>Especiais:</b> criadas pelo Plenário, para estudo ou representação da Câmara.", "<b>CPI:</b> requerimento de <b>1/3</b> (7), <b>fato determinado</b> e <b>prazo certo</b>; conclusões ao Ministério Público.", "<b>Secretários:</b> convocação pessoal por <b>maioria dos membros</b>, sobre assuntos previamente estabelecidos (art. 28); pedido escrito da Mesa, <b>30 dias</b> (art. 30). Leitura conforme a SV 46: só a União define crimes de responsabilidade.", "<b>Líderes:</b> Maioria, Minoria, Blocos e representações com <b>mais de 1/10</b> (3 Vereadores); indicados em 24 horas após a instalação do 1º período legislativo anual."], "top": 22}, {"id": "v3-08", "src": "Apostila Vol. 3", "titulo": "Competências privativas da Câmara, Mesa e Presidente", "fonte": "LOM, Aula 01 (arts. 31 a 34)", "itens": ["<b>Mesa:</b> promulga a <b>LOM e suas emendas</b>; propõe projetos de cargos da Câmara; créditos suplementares com aproveitamento de consignações da Câmara.", "<b>Presidente:</b> representa a Câmara; interpreta o Regimento; promulga <b>resoluções e decretos legislativos</b>; promulga leis de sanção tácita ou veto rejeitado quando o Prefeito não o faz; solicita intervenção por <b>maioria absoluta</b>.", "<b>Contas do Prefeito:</b> a Câmara julga, com parecer do TCM em até <b>60 dias</b>; o parecer só deixa de prevalecer por <b>2/3</b> (14); rejeitadas, vão ao Ministério Público. Contas não apresentadas em 60 dias após a reabertura: tomada por <b>comissão especial</b>.", "<b>Autorizar o Prefeito a ausentar-se</b> por <b>mais de 15 dias</b>. <b>Cidadão honorário:</b> 2/3. <b>CPI:</b> 1/3."], "top": 21}, {"id": "v3-09", "src": "Apostila Vol. 3", "titulo": "Remuneração e limites", "fonte": "LOM, Aula 01 (art. 35 e art. 29-A da CF)", "itens": ["Fixada <b>até 30 dias antes da eleição</b>, para a legislatura subsequente; se não fixada, prorrogam-se as anteriores.", "<b>13º salário:</b> parcela única em dezembro, ou 2 parcelas: <b>40%</b> no aniversário e <b>60%</b> em dezembro; férias com 1/3 (STF, Tema 484).", "<b>Verba de representação</b> do Presidente: até 50% da remuneração, limitada ao que perceber o Prefeito (a CF veda parcelas adicionais ao subsídio, art. 39, § 4º).", "Quatro limites distintos: teto individual (% do Deputado Estadual), <b>5%</b> (Vereadores), <b>7% a 3,5%</b> (despesa total do Legislativo) e <b>70%</b> (folha da Câmara)."], "top": 13}, {"id": "v3-10", "src": "Apostila Vol. 3", "titulo": "Vereadores: inviolabilidade, incompatibilidades, perda e licenças", "fonte": "LOM, Aula 01 (arts. 36 a 40)", "itens": ["<b>Inviolabilidade:</b> opiniões, palavras e votos no exercício do mandato e na circunscrição do Município. Imunidade material; sem imunidade formal.", "<b>Incompatibilidades:</b> desde a <b>diplomação</b> (contratos com o Município, salvo cláusulas uniformes; cargo remunerado nas entidades) e desde a <b>posse</b> (empresa favorecida, patrocinar causa, mais de um cargo eletivo).", "<b>Perda do mandato (art. 38):</b> infração às proibições, decoro, faltas a <b>1/3 das ordinárias</b> ou <b>5 extraordinárias</b>, direitos políticos, Justiça Eleitoral, condenação criminal transitada. Cassação (DL 201/67): <b>2/3</b> e votação nominal.", "<b>Licença:</b> doença; interesse particular, <b>sem remuneração</b>, de <b>30 a 120 dias</b> por sessão legislativa; missão. Secretário Municipal: licença <b>automática</b>.", "<b>Suplente:</b> convocado em vaga, investidura (art. 39, § 1º) ou licença <b>superior a 120 dias</b>; posse em <b>5 dias</b> (Regimento: 48h). Vaga sem suplente: eleição se faltarem <b>mais de 15 meses</b>."], "top": 13}, {"id": "v3-11", "src": "Apostila Vol. 3", "titulo": "Processo legislativo: espécies, emenda, iniciativa", "fonte": "LOM, Aula 01 (arts. 41 a 46)", "itens": ["<b>Espécies:</b> emenda à LOM, leis complementares, ordinárias, delegadas, decretos legislativos e resoluções. Sem medida provisória.", "<b>Emenda à LOM:</b> proposta de <b>1/3</b> (7) ou do Prefeito; <b>2 turnos</b>, <b>10 dias</b>, <b>2/3</b> (14); promulgada pela <b>Mesa</b>; vedada em estado de sítio ou intervenção; matéria rejeitada não volta na mesma sessão legislativa.", "<b>Iniciativa (art. 43):</b> qualquer Vereador, Prefeito e eleitorado (<b>5%</b> dos eleitores).", "<b>Lei complementar (art. 44):</b> <b>maioria absoluta</b> dos membros (11). Código Tributário, de Obras, Plano de Desenvolvimento Urbano, Código de Posturas, regime jurídico único, Guarda Municipal, criação de cargos.", "<b>Iniciativa exclusiva do Prefeito (art. 45):</b> cargos e remuneração, servidores, secretarias e órgãos, orçamento. <b>Da Mesa (art. 46):</b> créditos da Câmara e serviços, cargos e remuneração da Câmara."], "top": 10}, {"id": "v3-12", "src": "Apostila Vol. 3", "titulo": "Urgência, sanção, veto, delegação e projeto rejeitado", "fonte": "LOM, Aula 01 (arts. 47 a 51, conferidos no texto da Prefeitura)", "itens": ["<b>AVISO:</b> o PDF do curso no Drive termina no art. 47. Os arts. 47 a 51 foram conferidos no PDF da LOM no site da Prefeitura (versão de 2019). Confirme com o texto vigente.", "<b>Urgência</b> (projetos do Prefeito): Câmara se manifesta em <b>45 dias</b>.", "<b>Sanção e veto:</b> o Prefeito veta em <b>15 dias úteis</b>; silêncio = <b>sanção</b>; veto parcial só de artigo, parágrafo, inciso ou alínea. Câmara aprecia o veto em <b>30 dias</b>; só cai por <b>maioria absoluta</b>, em votação <b>secreta</b>.", "Rejeitado o veto, o projeto volta ao Prefeito; não promulgando, o <b>Presidente da Câmara</b> promulga em <b>48h</b>, e depois o <b>Vice-Presidente</b>.", "<b>Leis delegadas:</b> por decreto legislativo; não podem ser delegados atos privativos da Câmara, matéria de lei complementar, PPA e orçamento.", "<b>Projeto de lei rejeitado:</b> só volta na mesma sessão legislativa por proposta da <b>maioria absoluta</b>. (Emenda à LOM rejeitada: não volta.)"], "top": 11}, {"id": "v3-13", "src": "Apostila Vol. 3", "titulo": "Fiscalização das contas e controle interno", "fonte": "LOM, Aula 02 (arts. 52 a 54)", "itens": ["<b>Controle externo:</b> Câmara, com auxílio do <b>TCM</b> (órgão estadual). Controle interno: sistema do Executivo (art. 53).", "<b>Contas de governo</b> do Prefeito: parecer do TC e julgamento da Câmara; <b>2/3</b> derrubam o parecer. <b>Contas de gestão:</b> julgadas pelo TC (ADPF 982).", "<b>Controle interno:</b> eficácia ao controle externo, programas e orçamento, resultados, contratos.", "Contas à disposição do contribuinte por <b>60 dias</b>. Recursos de União e Estado: prestados na forma da legislação federal ou estadual, e incluídos na prestação anual."], "top": 27}, {"id": "v3-14", "src": "Apostila Vol. 3", "titulo": "Prefeito e Vice-Prefeito: eleição, posse e vacância", "fonte": "LOM, Aula 02 (arts. 55 a 63)", "itens": ["Idade mínima de <b>21 anos</b>. Eleição simultânea; vence o mais votado (empate: o mais idoso). Posse em <b>1º de janeiro</b>; não assumindo em <b>10 dias</b>, o cargo é declarado vago. Reeleição para <b>um</b> período subsequente.", "<b>Substituição</b> (impedimento): Vice. <b>Sucessão</b> (vaga): Vice. Impedidos ambos: <b>Presidente</b>, depois <b>Vice-Presidente da Câmara</b>.", "<b>Vaga sem Vice:</b> nos 3 primeiros anos, eleição em <b>90 dias</b>; no último ano, o Presidente da Câmara completa o período.", "<b>Ausência:</b> licença da Câmara para mais de <b>15 dias</b>. <b>Declaração de bens:</b> na posse e ao fim do mandato."], "top": 13}, {"id": "v3-15", "src": "Apostila Vol. 3", "titulo": "Atribuições do Prefeito, responsabilidade e auxiliares", "fonte": "LOM, Aula 02 (arts. 64 a 79)", "itens": ["<b>Prazos:</b> contas e balanços até <b>15 de abril</b>; informações à Câmara em <b>15 dias</b>; duodécimo até o <b>dia 20</b>; relatório de execução orçamentária em <b>30 dias</b> após cada bimestre.", "<b>Delegação por decreto</b> (art. 66): provimento de cargos, serviços e obras, organização dos serviços internos.", "<b>Crimes de responsabilidade:</b> TJ. <b>Infrações político-administrativas:</b> Câmara (2/3, 90 dias; DL 201/67). Definição pela União (SV 46).", "<b>Secretários:</b> brasileiro, direitos políticos, maior de 18 anos; relatório semestral; solidários nos atos que praticarem. <b>Subprefeito:</b> nomeado em <b>60 dias</b> da posse, competência limitada ao distrito."], "top": 13}, {"id": "v3-16", "src": "Apostila Vol. 3", "titulo": "Administração Pública, servidores e Guarda Municipal", "fonte": "LOM, Aula 02 (arts. 80 a 86)", "itens": ["Princípios (art. 80): legalidade, impessoalidade, moralidade e publicidade; a CF acrescenta <b>eficiência</b>.", "<b>Concurso:</b> validade de até <b>2 anos</b>, prorrogável 1 vez. <b>Contratação temporária:</b> até <b>180 dias</b>, vedada a recontratação. <b>Estabilidade:</b> 3 anos e avaliação especial.", "<b>Servidor com mandato (art. 81):</b> federal/estadual, afasta-se; Prefeito, afasta-se e opta; Vereador com horários compatíveis, recebe as duas.", "<b>Administração indireta (art. 86):</b> autarquia, empresa pública, sociedade de economia mista e fundação pública.", "<b>Guarda Municipal:</b> força auxiliar, uniformizada, armada se a lei dispuser, função preventiva; lei complementar; concurso."], "top": 18}, {"id": "v3-17", "src": "Apostila Vol. 3", "titulo": "Tributação municipal", "fonte": "LOM, Aula 02 (arts. 115 a 121)", "itens": ["<b>Impostos municipais:</b> IPTU, ITBI (onerosa, inter vivos) e ISS. <b>IBS:</b> competência compartilhada (Estados, DF, Municípios); ISS e ICMS reduzidos a partir de <b>2029</b> e extintos em <b>2033</b>.", "<b>Taxas:</b> poder de polícia ou serviço <b>específico e divisível</b>. <b>Contribuição de melhoria:</b> valorização por obra pública; limite individual é o acréscimo de valor do imóvel.", "<b>Limitações:</b> legalidade, isonomia, irretroatividade, anterioridade (anual e nonagesimal, com exceções), vedação de confisco; <b>imunidades</b> (recíproca, templos, partidos, entidades, livros e papel)."], "top": 13}, {"id": "v3-18", "src": "Apostila Vol. 3", "titulo": "Planejamento e orçamento", "fonte": "LOM, Aula 02 (arts. 130 a 135)", "itens": ["<b>PPA, LDO e LOA</b>, de iniciativa do Executivo. Relatório resumido: <b>30 dias</b> após cada bimestre. Divulgação de tributos arrecadados: até o fim do mês subsequente.", "<b>Comissão de Orçamento e Finanças</b> aprecia PPA, LOA e créditos adicionais. Emendas: compatíveis com o PPA, indicando recursos de anulação (exceto pessoal, encargos e dívida), ou correção de erros ou omissões.", "<b>Emendas individuais:</b> <b>1,2%</b> da RCL prevista (metade para saúde); execução obrigatória sobre a RCL do exercício anterior. Impedimento técnico: justificativa em <b>120 dias</b>; remanejamento, em etapas de 30 dias.", "<b>LOA:</b> orçamento fiscal, de investimento e da seguridade. Sem proposta do Executivo no prazo, a Câmara elabora a lei de meios com base na lei em vigor."], "top": 3}], "questoes": [{"id": "c1-01", "src": "Caderno 1", "num": 1, "top": 13, "tema": null, "stem": "Nos termos da Lei Orgânica do Município de Rio Verde, são poderes do Município, independentes e harmônicos entre si:", "opts": ["o Legislativo, o Executivo e o Judiciário.", "o Executivo, o Legislativo e o Tribunal de Contas dos Municípios.", "a Câmara Municipal, a Prefeitura e o Ministério Público.", "o Legislativo e o Executivo."], "ci": 3, "why": "LOM, art. 5º. O Município não tem Poder Judiciário. Pegadinha: transportar a tripartição federal para o âmbito municipal.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-02", "src": "Caderno 1", "num": 2, "top": 13, "tema": null, "stem": "Nos termos da LOM, à Câmara Municipal, com sanção do Prefeito, ressalvada a sua competência privativa, cabe legislar sobre todas as matérias de competência municipal e especialmente sobre:", "opts": ["concessão de título de cidadão honorário.", "eleição da Mesa e elaboração do Regimento Interno.", "lei de diretrizes orçamentárias, plano plurianual e orçamento anual.", "autorização para o Prefeito ausentar-se do Município por mais de 15 dias."], "ci": 2, "why": "LOM, art. 33, III. O art. 33 traz o que se faz por lei, com sanção. As demais alternativas estão no art. 34 (competência privativa da Câmara, sem sanção). Regra: lei = com sanção; privativa = decreto legislativo ou resolução.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-03", "src": "Caderno 1", "num": 3, "top": 13, "tema": null, "stem": "O processo legislativo municipal compreende, segundo a LOM, a elaboração de:", "opts": ["emenda à Lei Orgânica, leis complementares, leis ordinárias, medidas provisórias, decretos legislativos e resoluções.", "emenda à Lei Orgânica, leis ordinárias, medidas provisórias, leis delegadas e resoluções.", "emenda à Lei Orgânica, leis complementares, leis ordinárias, leis delegadas, decretos legislativos e resoluções.", "leis complementares, leis ordinárias, leis delegadas, decretos do Prefeito e portarias."], "ci": 2, "why": "LOM, art. 41. Não há medida provisória na lista do Município. Decreto e portaria do Prefeito são atos administrativos, não espécies do processo legislativo.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-04", "src": "Caderno 1", "num": 4, "top": 13, "tema": null, "stem": "Sobre a emenda à Lei Orgânica, é correto afirmar:", "opts": ["pode ser proposta por 1/3 dos membros da Câmara ou pelo Prefeito, é votada em dois turnos com interstício mínimo de 10 dias, exige 2/3 dos membros e é promulgada pela Mesa.", "pode ser proposta por maioria absoluta dos vereadores, exige 3/5 em dois turnos e é promulgada pelo Prefeito.", "exige maioria absoluta em turno único e é promulgada pelo Presidente da Câmara.", "pode ser aprovada mesmo na vigência de intervenção no Município, desde que por 2/3."], "ci": 0, "why": "LOM, art. 42. 3/5 é o quórum da emenda à Constituição Federal. Quem promulga é a Mesa. É vedada na vigência de estado de sítio ou de intervenção.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-05", "src": "Caderno 1", "num": 5, "top": 13, "tema": null, "stem": "Segundo a LOM, é de iniciativa exclusiva da Mesa da Câmara o projeto de lei que disponha sobre:", "opts": ["criação de cargos na administração direta e autárquica do Município.", "matéria orçamentária do Município.", "estruturação das secretarias e dos órgãos da Administração Pública.", "organização dos serviços administrativos da Câmara e criação, transformação ou extinção de seus cargos, com fixação da remuneração."], "ci": 3, "why": "LOM, art. 46, II. As demais são de iniciativa exclusiva do Prefeito (art. 45). Tema próximo das Leis 7.434 e 7.435/2023 (estrutura e cargos da Câmara).", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-06", "src": "Caderno 1", "num": 6, "top": 13, "tema": null, "stem": "O Prefeito solicitou urgência para a apreciação de projeto de sua iniciativa. De acordo com a LOM:", "opts": ["a Câmara deve se manifestar em até 30 dias; esgotado o prazo, o projeto é considerado aprovado.", "o prazo de 45 dias corre normalmente durante o recesso e também para projetos de lei complementar.", "a Câmara deve se manifestar em até 45 dias; esgotado o prazo sem deliberação, a proposição é incluída na ordem do dia, sobrestadas as demais, até a votação.", "esgotado o prazo de 45 dias, o projeto é arquivado automaticamente."], "ci": 2, "why": "LOM, art. 47. Não existe aprovação nem arquivamento automáticos: a consequência é o sobrestamento da pauta. O prazo não corre no recesso nem vale para lei complementar (§ 3º).", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-07", "src": "Caderno 1", "num": 7, "top": 13, "tema": null, "stem": "Sobre o veto do Prefeito a projeto de lei, segundo a LOM:", "opts": ["o prazo é de 15 dias corridos; o veto parcial pode alcançar palavra ou expressão; o silêncio importa veto.", "o prazo é de 30 dias úteis; o veto parcial pode alcançar apenas palavras; o silêncio importa sanção.", "o prazo é de 15 dias úteis, contados do recebimento; o veto parcial abrange apenas texto integral de artigo, parágrafo, inciso ou alínea; o silêncio importa sanção.", "o prazo é de 15 dias úteis; o veto pode ser tácito quando o Prefeito silenciar."], "ci": 2, "why": "LOM, art. 48, §§ 1º a 3º. Pegadinhas clássicas: dias úteis x corridos, veto de palavra isolada (vedado) e “silêncio = veto” (o silêncio é sanção tácita).", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-08", "src": "Caderno 1", "num": 8, "top": 13, "tema": null, "stem": "Rejeitado o veto, o projeto é enviado ao Prefeito para promulgação. Se a lei não for promulgada em 48 horas pelo Prefeito (sanção tácita ou veto rejeitado), segundo a LOM:", "opts": ["a Mesa Diretora a promulga, colegiadamente, no prazo de 15 dias.", "o Vice-Prefeito a promulga.", "o Presidente da Câmara só a promulga após nova votação em Plenário.", "o Presidente da Câmara a promulga e, se não o fizer em igual prazo, caberá ao Vice-Presidente."], "ci": 3, "why": "LOM, art. 48, § 7º (espelha o art. 66, § 7º, da CF). Ordem: Prefeito, depois Presidente da Câmara, depois Vice-Presidente.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-09", "src": "Caderno 1", "num": 9, "top": 13, "tema": null, "stem": "Quanto às leis delegadas, a LOM de Rio Verde estabelece que:", "opts": ["são elaboradas pelo Prefeito, que solicita a delegação à Câmara; a delegação se faz por decreto legislativo, e não podem ser objeto dela atos de competência privativa da Câmara, matéria de lei complementar, planos plurianuais e orçamento.", "são elaboradas pela Câmara por delegação do Prefeito, mediante decreto do Executivo.", "a delegação se faz por lei ordinária e pode alcançar matéria de lei complementar.", "a delegação se faz por resolução e pode alcançar o orçamento anual."], "ci": 0, "why": "LOM, art. 49. Na CF a delegação é por resolução do Congresso (art. 68, § 2º); na LOM de Rio Verde é por decreto legislativo. Em prova local, vale o texto da LOM.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-10", "src": "Caderno 1", "num": 10, "top": 13, "tema": null, "stem": "Segundo a LOM, perderá o mandato o Vereador que deixar de comparecer, em cada sessão legislativa:", "opts": ["à metade das sessões ordinárias da Câmara.", "à terça parte das sessões ordinárias, salvo licença ou missão autorizada, ou a 5 sessões extraordinárias regularmente convocadas.", "a um quarto das sessões ordinárias ou a 3 sessões extraordinárias.", "a um terço das sessões ordinárias e extraordinárias, indistintamente."], "ci": 1, "why": "LOM, art. 38, III. Atenção: o Regimento (art. 107, IV) trata de outra hipótese, a falta a 3 sessões extraordinárias convocadas pelo Prefeito para matéria urgente. Leia a pergunta: “segundo a LOM” ou “segundo o Regimento”?", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-11", "src": "Caderno 1", "num": 11, "top": 13, "tema": null, "stem": "Sobre o julgamento das contas do Prefeito, segundo a LOM:", "opts": ["a Câmara delibera sobre o parecer do Tribunal de Contas dos Municípios em até 60 dias do recebimento, e o parecer só deixa de prevalecer por decisão de 2/3 dos vereadores.", "o parecer do Tribunal de Contas deixa de prevalecer por maioria absoluta dos vereadores.", "o parecer do Tribunal de Contas é vinculante, cabendo à Câmara apenas homologá-lo.", "a Câmara julga as contas sem necessidade de parecer prévio do Tribunal de Contas."], "ci": 0, "why": "LOM, arts. 34, VIII e 52, § 2º (e CF, art. 31, § 2º). O quórum de 2/3 é o que derruba o parecer prévio. Quem julga é a Câmara; o Tribunal apenas auxilia.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-12", "src": "Caderno 1", "num": 12, "top": 13, "tema": null, "stem": "Os prazos para atender a pedidos de informação da Câmara, segundo a LOM, são:", "opts": ["15 dias para os Secretários Municipais e 30 dias para o Prefeito.", "30 dias tanto para o Prefeito quanto para os Secretários.", "15 dias para ambos, sem possibilidade de prorrogação.", "30 dias para os Secretários Municipais, com a recusa ou o não atendimento configurando crime de responsabilidade; 15 dias para o Prefeito, salvo prorrogação por complexidade da matéria."], "ci": 3, "why": "LOM, art. 30 (Secretários: 30 dias, crime de responsabilidade) e art. 65, XIV (Prefeito: 15 dias, prorrogável a pedido). A banca gosta de trocar os números entre os agentes.", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-13", "src": "Caderno 1", "num": 13, "top": 13, "tema": null, "stem": "De acordo com a LOM, o Executivo manterá sistema de controle interno a fim de:", "opts": ["julgar as contas do Prefeito e aplicar sanções aos ordenadores de despesa.", "criar condições para a eficácia do controle externo e a regularidade da receita e da despesa, acompanhar a execução de programas e do orçamento, avaliar resultados e verificar a execução dos contratos.", "fiscalizar os atos da Câmara Municipal e do Tribunal de Contas.", "emitir parecer prévio sobre as contas anuais, em substituição ao Tribunal de Contas."], "ci": 1, "why": "LOM, art. 53, I a IV. Controle interno é do próprio Executivo e auxilia o controle externo. Quem julga as contas do Prefeito é a Câmara (art. 34, VIII).", "study": "LOM (PDF), Aulas 01–02"}, {"id": "c1-14", "src": "Caderno 1", "num": 14, "top": 6, "tema": null, "stem": "No Regimento Interno da Câmara de Rio Verde, a Mesa:", "opts": ["é eleita para um ano, por maioria absoluta, e o empate se resolve por novo turno.", "é eleita para duas sessões legislativas, composta por Presidente, Vice-Presidente e 1º e 2º Secretários; a eleição é por maioria simples e, em caso de empate, vence a chapa cujo candidato a Presidente seja o mais idoso.", "é eleita para quatro anos, composta por Presidente, Vice-Presidente e três Secretários.", "é eleita para duas sessões legislativas por 2/3 dos membros, e o empate é decidido pelo mais votado nas eleições."], "ci": 1, "why": "Regimento, arts. 5º, 11 e 11, § 1º. Pegadinhas: duração (2 anos, não 1 nem 4), quórum (maioria simples) e critério de desempate (idade).", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-15", "src": "Caderno 1", "num": 15, "top": 6, "tema": null, "stem": "Os membros da Mesa podem ser destituídos, isoladamente ou em conjunto, quando faltosos, omissos ou ineficientes, mediante resolução aprovada por:", "opts": ["maioria simples dos vereadores presentes.", "maioria absoluta dos membros da Câmara.", "no mínimo 2/3 dos membros da Câmara, assegurada ampla defesa.", "3/5 dos membros da Câmara."], "ci": 2, "why": "Regimento, arts. 28 e 29 (e LOM, art. 22, § 3º). A representação inicial é subscrita pela maioria absoluta, mas a destituição exige 2/3. Não confunda as duas etapas.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-16", "src": "Caderno 1", "num": 16, "top": 6, "tema": null, "stem": "Segundo o Regimento consolidado até a Resolução nº 05/2026, as Comissões Permanentes são:", "opts": ["em número de 16, compostas cada uma por 3 vereadores: Presidente, Relator e Vogal.", "em número de 7, compostas por 5 vereadores cada.", "em número de 15, compostas por 3 vereadores cada.", "em número de 16, compostas por 5 vereadores cada."], "ci": 0, "why": "Regimento, art. 38 e § 1º. O número já mudou várias vezes (7, 14, 15 e hoje 16). Se o seu material trouxer outro número, ele está desatualizado.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-17", "src": "Caderno 1", "num": 17, "top": 6, "tema": null, "stem": "Quanto aos prazos de tramitação nas Comissões Permanentes, em regra:", "opts": ["o prazo para parecer é de 5 dias, prorrogável por mais 5, e a vista pode ser concedida antes do relatório.", "o prazo para parecer é de 2 dias improrrogáveis e não há pedido de vista.", "o prazo para parecer é de 2 dias, prorrogável por mais 1 dia pelo Presidente da Câmara, com requerimento fundamentado; o relator tem 2 dias improrrogáveis; a vista é de até 24 horas e só após o projeto estar relatado.", "o prazo para parecer é de 15 dias, e a vista é de 48 horas, prorrogável."], "ci": 2, "why": "Regimento, art. 56 e §§ 1º a 4º. Pegadinha: a vista só é concedida depois de o projeto estar relatado, e é comum e improrrogável.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-18", "src": "Caderno 1", "num": 18, "top": 6, "tema": null, "stem": "Quando o parecer da Comissão de Constituição, Justiça e Redação conclui pela inconstitucionalidade ou ilegalidade de um projeto:", "opts": ["o projeto é arquivado automaticamente, sem votação.", "o parecer é submetido ao Plenário em discussão e votação única; se aprovado, a proposição é arquivada; se rejeitado, segue às demais Comissões.", "o Presidente da Câmara decide sozinho se o projeto prossegue.", "o projeto segue obrigatoriamente ao Plenário para votação do mérito."], "ci": 1, "why": "Regimento, arts. 61 e 71. A Comissão de Constituição e Justiça opina primeiro (aspectos legal e constitucional). Quem arquiva é o Plenário, ao aprovar o parecer.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-19", "src": "Caderno 1", "num": 19, "top": 6, "tema": null, "stem": "Sobre as Comissões Especiais, segundo o Regimento:", "opts": ["são constituídas por requerimento de qualquer vereador, aprovado por 2/3.", "têm prazo indeterminado e não se extinguem pelo fim do prazo.", "podem tratar de assunto de competência específica de Comissão Permanente.", "são constituídas por requerimento subscrito por no mínimo 1/3 dos membros, aprovado por maioria simples; o requerimento deve indicar finalidade, número de membros e prazo; não cabem para assunto de competência de Comissão Permanente."], "ci": 3, "why": "Regimento, arts. 73, 74 e 75, §§ 5º e 6º. Sem concluir no prazo, a Comissão Especial se extingue automaticamente, salvo prorrogação aprovada em tempo hábil.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-20", "src": "Caderno 1", "num": 20, "top": 6, "tema": null, "stem": "O Plenário da Câmara tem 21 vereadores. Segundo o Regimento, para aprovar a alteração do Regimento Interno (maioria absoluta) e para a cassação do mandato de vereador (2/3), são necessários, no mínimo, respectivamente:", "opts": ["10 e 14 votos.", "11 e 13 votos.", "11 e 14 votos.", "10 e 15 votos."], "ci": 2, "why": "Regimento, arts. 83 e 84. Maioria absoluta = primeiro número inteiro acima da metade dos componentes (21/2 = 10,5, logo 11). 2/3 de 21 = 14. Pegadinha: maioria absoluta é dos membros, não dos presentes.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-21", "src": "Caderno 1", "num": 21, "top": 6, "tema": null, "stem": "Exigem voto mínimo de 2/3 dos membros da Câmara, segundo o Regimento:", "opts": ["aprovação do Regimento Interno e do Código Tributário.", "alienação de bens imóveis, cassação do mandato de vereador e destituição da Mesa.", "rejeição de veto e concessão de serviços públicos.", "criação de cargos no quadro da secretaria da Câmara."], "ci": 1, "why": "Regimento, art. 84. Exigem maioria absoluta: Regimento, Código de Obras, Estatuto dos Servidores, Código Tributário, criação de cargos da Câmara, concessão de serviços, Plano Diretor e rejeição de veto (inciso I).", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-22", "src": "Caderno 1", "num": 22, "top": 6, "tema": null, "stem": "Sobre as sessões ordinárias da Câmara, segundo o Regimento:", "opts": ["compõem-se de Expediente, Ordem do Dia e Assuntos Parlamentares; na Ordem do Dia, os vetos vêm em primeiro lugar; não há sessões ordinárias em janeiro e julho.", "compõem-se apenas de Ordem do Dia e Assuntos Parlamentares; os projetos em primeira discussão vêm antes dos vetos.", "realizam-se também em janeiro e julho, por serem meses de recesso parcial.", "os Assuntos Parlamentares vêm antes da Ordem do Dia e podem prorrogar a sessão."], "ci": 0, "why": "Regimento, arts. 126, 127, 134 e 146. A ordem da pauta é: vetos, redação final, segunda discussão, primeira discussão, depois moções, requerimentos e recursos. As sessões ordinárias não são prorrogadas para assuntos parlamentares.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-23", "src": "Caderno 1", "num": 23, "top": 6, "tema": null, "stem": "Sobre as sessões extraordinárias, segundo o Regimento:", "opts": ["só podem ser convocadas pelo Prefeito, com antecedência de 24 horas.", "podem tratar de qualquer matéria e incluem assuntos parlamentares.", "podem ser convocadas pela Mesa, por 1/3 dos membros ou pelo Prefeito; exigem antecedência mínima de 3 dias, salvo extrema urgência; tratam só da matéria da convocação e não têm assuntos parlamentares.", "são abertas com qualquer número de vereadores presentes."], "ci": 2, "why": "Regimento, arts. 147 a 155. Abertura exige maioria absoluta dos membros (art. 152). Na LOM, a convocação por requerimento em caso de urgência fala em maioria dos membros (art. 15, § 3º, III): atenção à fonte citada.", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-24", "src": "Caderno 1", "num": 24, "top": 6, "tema": null, "stem": "No processo de cassação do mandato de vereador, segundo o Regimento:", "opts": ["a denúncia só pode ser feita pelo Ministério Público; o vereador é afastado totalmente do mandato desde o recebimento.", "a cassação exige maioria simples dos presentes, com votação secreta.", "a denúncia é recebida pelo Presidente isoladamente e o afastamento é automático.", "a denúncia pode ser feita por qualquer eleitor; recebida por maioria absoluta, o Presidente afasta o vereador apenas quanto à matéria objeto da denúncia, até o julgamento; a cassação exige 2/3 dos membros, com votações abertas."], "ci": 3, "why": "Regimento, arts. 107 a 111 (art. 111, parágrafo único, alterado pela Res. 10/2001, votações abertas). Se o denunciante for vereador, fica impedido de votar e de integrar a Comissão Processante (art. 109, § 1º).", "study": "Regimento Interno (Res. 33/2000), Aulas 01–03"}, {"id": "c1-25", "src": "Caderno 1", "num": 25, "top": 11, "tema": null, "stem": "Um vereador apresenta projeto de lei que cria cargo em comissão na estrutura de uma secretaria municipal, e o Prefeito o sanciona. Segundo a jurisprudência do STF e o princípio da simetria:", "opts": ["a lei é válida, pois a sanção do Prefeito convalida o vício de iniciativa.", "a lei é inconstitucional por vício de iniciativa, matéria reservada ao Chefe do Executivo, e a sanção não convalida o vício.", "a lei é válida se aprovada por 2/3 dos vereadores.", "a lei só seria inconstitucional se houvesse aumento de despesa."], "ci": 1, "why": "CF, art. 61, § 1º, II (aplicado por simetria aos Municípios) e LOM, art. 45. A Súmula 5 do STF (sanção sana o vício) foi superada. Pegadinha: tratar o vício de iniciativa como sanável.", "study": "Dir. Constitucional, Aula 09 (Processo Legislativo)"}, {"id": "c1-26", "src": "Caderno 1", "num": 26, "top": 10, "tema": null, "stem": "Segundo a tese do STF (Tema 917), a lei de iniciativa parlamentar que cria despesa para a Administração, mas não trata de sua estrutura, da atribuição de seus órgãos nem do regime jurídico dos servidores:", "opts": ["é sempre inconstitucional, porque somente o Chefe do Executivo pode criar despesas.", "é inconstitucional por tratar de matéria orçamentária.", "só é válida se tiver aprovação prévia do Prefeito.", "não usurpa a competência privativa do Chefe do Executivo, pois a reserva de iniciativa é taxativa e não alcança toda lei que gere despesa."], "ci": 3, "why": "STF, RE 878.911 (Tema 917). A reserva de iniciativa é exceção e deve ser interpretada de forma restrita. Cuidado com a regra simplista “criou despesa = vício”.", "study": "Dir. Constitucional, Aula 09 (Processo Legislativo)"}, {"id": "c1-27", "src": "Caderno 1", "num": 27, "top": 10, "tema": null, "stem": "A iniciativa popular de projetos de lei de interesse específico do Município exige a manifestação de, pelo menos:", "opts": ["1% do eleitorado.", "1% do eleitorado, distribuído por pelo menos 5 bairros.", "10% do eleitorado.", "5% do eleitorado."], "ci": 3, "why": "CF, art. 29, XIII, e LOM, art. 43. O 1% (em 5 Estados) é a iniciativa popular federal. Pegadinha: trocar os percentuais.", "study": "Dir. Constitucional, Aula 09 (Processo Legislativo)"}, {"id": "c1-28", "src": "Caderno 1", "num": 28, "top": 11, "tema": null, "stem": "Sobre o veto no processo legislativo, é correto afirmar:", "opts": ["o veto pode ser tácito, quando o Chefe do Executivo deixa transcorrer o prazo.", "o veto parcial pode incidir sobre palavra ou expressão isolada do dispositivo.", "o veto é sempre expresso e fundamentado em inconstitucionalidade (veto jurídico) ou contrariedade ao interesse público (veto político); o silêncio do Chefe do Executivo importa sanção tácita.", "a sanção expressa convalida eventual vício de iniciativa do projeto."], "ci": 2, "why": "CF, art. 66, §§ 1º a 3º e LOM, art. 48. Veto jurídico = inconstitucionalidade; político = interesse público. Não existe veto tácito, nem veto de palavra solta.", "study": "Dir. Constitucional, Aula 09 (Processo Legislativo)"}, {"id": "c1-29", "src": "Caderno 1", "num": 29, "top": 10, "tema": null, "stem": "O instrumento adequado para a Câmara Municipal conceder título de cidadão honorário, segundo a LOM e o Regimento, é:", "opts": ["lei ordinária, sancionada pelo Prefeito.", "resolução, aprovada por maioria simples.", "lei complementar, aprovada por maioria absoluta.", "decreto legislativo, aprovado por 2/3 dos membros e promulgado pelo Presidente da Câmara."], "ci": 3, "why": "LOM, arts. 34, XX e 50; Regimento, art. 84, II, “d”. Resolução trata de assuntos internos da Câmara; decreto legislativo, dos demais casos de competência privativa com efeitos externos.", "study": "Dir. Constitucional, Aula 09 (Processo Legislativo)"}, {"id": "c1-30", "src": "Caderno 1", "num": 30, "top": 10, "tema": null, "stem": "Projeto de lei rejeitado pela Câmara Municipal:", "opts": ["não pode ser reapresentado em nenhuma hipótese.", "pode ser reapresentado na mesma sessão legislativa por qualquer vereador.", "pode ser reapresentado na mesma sessão legislativa mediante proposta de 1/3 dos vereadores.", "somente poderá constituir objeto de novo projeto, na mesma sessão legislativa, mediante proposta da maioria absoluta dos membros da Câmara."], "ci": 3, "why": "CF, art. 67 e LOM, art. 51. O que se restringe é a reapresentação na mesma sessão legislativa; na seguinte, pode ser reapresentado normalmente.", "study": "Dir. Constitucional, Aula 09 (Processo Legislativo)"}, {"id": "c1-31", "src": "Caderno 1", "num": 31, "top": 1, "tema": null, "stem": "Lei municipal que contraria a Constituição Federal pode ser questionada no STF, em controle concentrado, por meio de:", "opts": ["ação direta de inconstitucionalidade (ADI).", "arguição de descumprimento de preceito fundamental (ADPF).", "ação declaratória de constitucionalidade (ADC).", "ação direta de inconstitucionalidade por omissão (ADO)."], "ci": 1, "why": "A ADI do STF alcança lei ou ato normativo federal ou estadual. Contra lei municipal em face da CF cabe ADPF (Lei 9.882/99).", "study": "Dir. Constitucional, Aula 13 + Dir. Legislativo, Aula 03"}, {"id": "c1-32", "src": "Caderno 1", "num": 32, "top": 1, "tema": null, "stem": "A representação de inconstitucionalidade de lei municipal julgada pelo Tribunal de Justiça tem como parâmetro:", "opts": ["a Constituição Federal, diretamente.", "a Lei Orgânica do Município.", "qualquer tratado internacional.", "a Constituição do Estado."], "ci": 3, "why": "CF, art. 125, § 2º. O TJ faz controle de leis municipais em face da Constituição Estadual. Note a LOM, art. 32, VIII: o Presidente da Câmara representa sobre inconstitucionalidade por decisão da Câmara.", "study": "Dir. Constitucional, Aula 13 + Dir. Legislativo, Aula 03"}, {"id": "c1-33", "src": "Caderno 1", "num": 33, "top": 1, "tema": null, "stem": "Não possui legitimidade para propor ação direta de inconstitucionalidade perante o STF:", "opts": ["a Mesa de Assembleia Legislativa.", "o Governador de Estado.", "a Mesa da Câmara Municipal.", "o Conselho Federal da OAB."], "ci": 2, "why": "CF, art. 103. Mesa de Câmara Municipal não consta do rol. Legitimados: Presidente da República, Mesas do Senado, da Câmara e de Assembleia, Governadores, PGR, OAB, partido com representação no Congresso e confederação sindical ou entidade de classe nacional.", "study": "Dir. Constitucional, Aula 13 + Dir. Legislativo, Aula 03"}, {"id": "c1-34", "src": "Caderno 1", "num": 34, "top": 1, "tema": null, "stem": "No controle difuso, a declaração de inconstitucionalidade de lei por tribunal:", "opts": ["exige voto da maioria absoluta dos membros do tribunal ou do órgão especial (cláusula de reserva de plenário), salvo se já houver pronunciamento do plenário ou do STF sobre a questão.", "pode ser feita por qualquer órgão fracionário, por maioria simples.", "exige sempre decisão de 2/3 dos membros do tribunal.", "depende de prévia manifestação do Senado Federal."], "ci": 0, "why": "CF, art. 97, Súmula Vinculante 10 e CPC, art. 949, parágrafo único. O Senado só suspende a execução da lei (art. 52, X) depois da decisão definitiva do STF.", "study": "Dir. Constitucional, Aula 13 + Dir. Legislativo, Aula 03"}, {"id": "c1-35", "src": "Caderno 1", "num": 35, "top": 1, "tema": null, "stem": "Constitui exemplo de controle preventivo de constitucionalidade:", "opts": ["o parecer da comissão de constituição e justiça do Legislativo e o veto jurídico do Chefe do Executivo.", "a ação direta de inconstitucionalidade julgada pelo STF.", "a arguição de descumprimento de preceito fundamental.", "a suspensão da execução da lei pelo Senado Federal."], "ci": 0, "why": "Preventivo ocorre antes de a lei existir (CCJ, veto jurídico e, excepcionalmente, mandado de segurança de parlamentar). Repressivo ocorre depois (ADI, ADPF, controle difuso). Sustar ato do Executivo que exorbita (LOM, art. 34, X) é controle político repressivo.", "study": "Dir. Constitucional, Aula 13 + Dir. Legislativo, Aula 03"}, {"id": "c1-36", "src": "Caderno 1", "num": 36, "top": 2, "tema": null, "stem": "São modalidades de licitação previstas na Lei nº 14.133/2021:", "opts": ["concorrência, tomada de preços, convite, concurso e leilão.", "pregão, concorrência, concurso, leilão e diálogo competitivo.", "pregão, convite, concorrência, leilão e RDC.", "concorrência, pregão, convite, concurso e leilão."], "ci": 1, "why": "Lei 14.133/2021, art. 28. Tomada de preços e convite não existem mais na lei nova. O diálogo competitivo é novidade.", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-37", "src": "Caderno 1", "num": 37, "top": 2, "tema": null, "stem": "Segundo a Lei 14.133/2021, o pregão é a modalidade obrigatória para a contratação de:", "opts": ["bens e serviços comuns, exceto serviços técnicos especializados de natureza predominantemente intelectual e obras e serviços de engenharia (salvo os serviços comuns de engenharia).", "obras e serviços técnicos especializados de natureza predominantemente intelectual.", "alienação de bens móveis inservíveis.", "trabalho técnico, científico ou artístico, com prêmio ou remuneração."], "ci": 0, "why": "Lei 14.133/2021, arts. 6º, XLI e 29. Alternativa C é leilão; D é concurso. Critério de julgamento do pregão: menor preço ou maior desconto.", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-38", "src": "Caderno 1", "num": 38, "top": 2, "tema": null, "stem": "Segundo a Lei 14.133/2021, em regra, as fases da licitação seguem a ordem:", "opts": ["preparatória, divulgação do edital, habilitação, apresentação de propostas, julgamento, recursal e homologação.", "divulgação do edital, julgamento, habilitação, adjudicação e contratação.", "preparatória, habilitação, divulgação do edital, julgamento, recursal e homologação.", "preparatória, divulgação do edital, apresentação de propostas e lances, julgamento, habilitação, recursal e homologação."], "ci": 3, "why": "Lei 14.133/2021, art. 17. A habilitação pode anteceder as propostas, mas só por ato motivado, com explicitação dos benefícios (art. 17, § 1º). Pegadinha: tratar a exceção como regra.", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-39", "src": "Caderno 1", "num": 39, "top": 2, "tema": null, "stem": "É hipótese de inexigibilidade de licitação, segundo a Lei 14.133/2021:", "opts": ["contratação em caso de emergência ou calamidade pública.", "contratação de compras de pequeno valor, dentro do limite legal.", "contratação após licitação deserta, quando não surgirem interessados.", "contratação de serviços técnicos especializados de natureza predominantemente intelectual com profissionais ou empresas de notória especialização (vedada para publicidade e divulgação)."], "ci": 3, "why": "Lei 14.133/2021, art. 74, III. Inexigibilidade = inviabilidade de competição. Emergência, pequeno valor e licitação deserta são casos de dispensa (art. 75).", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-40", "src": "Caderno 1", "num": 40, "top": 2, "tema": null, "stem": "Na dispensa de licitação por emergência ou calamidade pública (art. 75, VIII da Lei 14.133/2021), os contratos:", "opts": ["podem ser prorrogados por até 5 anos.", "têm prazo de 180 dias, renovável por igual período.", "podem ter prazo máximo de 1 ano, vedadas a prorrogação e a recontratação de empresa já contratada com base nesse inciso.", "não têm prazo máximo, enquanto durar a emergência."], "ci": 2, "why": "Lei 14.133/2021, art. 75, VIII. Atenção aos dois impedimentos: prorrogação e recontratação.", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-41", "src": "Caderno 1", "num": 41, "top": 2, "tema": null, "stem": "Salvo disposição em contrário, os prazos previstos na Lei nº 14.133/2021 são contados:", "opts": ["em dias corridos, incluído o dia do começo.", "em dias úteis, excluído o dia do começo e incluído o do vencimento.", "em dias úteis, incluído o dia do começo e excluído o do vencimento.", "em horas, a partir da publicação do edital."], "ci": 1, "why": "Lei 14.133/2021, art. 183. Conhecer essa regra evita erro em questões sobre impugnação (3 dias úteis antes da abertura) e recursos (3 dias úteis).", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-42", "src": "Caderno 1", "num": 42, "top": 2, "tema": null, "stem": "Nas compras, obras e serviços, o contratado é obrigado a aceitar, nas mesmas condições, acréscimos ou supressões unilaterais de até:", "opts": ["50% do valor inicial, em qualquer caso.", "10% do valor inicial atualizado do contrato.", "25% do valor inicial atualizado do contrato (50% para acréscimos em reforma de edifício ou de equipamento).", "sem limite, desde que haja interesse público."], "ci": 2, "why": "Lei 14.133/2021, art. 125. Pegadinha: o limite de 50% vale só para acréscimos em reforma de edifício ou equipamento.", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-43", "src": "Caderno 1", "num": 43, "top": 2, "tema": null, "stem": "As sanções previstas na Lei 14.133/2021 para o contratado que comete infração são:", "opts": ["advertência, multa (de 1% a 10%), suspensão do direito de licitar (até 2 anos) e inidoneidade (de 2 a 5 anos).", "advertência, multa (de 0,5% a 30% do valor do contrato), impedimento de licitar e contratar (até 3 anos) e declaração de inidoneidade (de 3 a 6 anos).", "advertência, multa (de 5% a 50%), impedimento (até 5 anos) e inidoneidade (de 5 a 10 anos).", "apenas advertência e multa, vedadas as demais sanções."], "ci": 1, "why": "Lei 14.133/2021, art. 156. Memorize os intervalos: multa 0,5% a 30%; impedimento até 3 anos; inidoneidade 3 a 6 anos.", "study": "Dir. Administrativo, Aulas 08–10 (Lei 14.133/2021)"}, {"id": "c1-44", "src": "Caderno 1", "num": 44, "top": 17, "tema": null, "stem": "Os princípios expressos no caput do art. 37 da Constituição Federal são:", "opts": ["legalidade, razoabilidade, moralidade, publicidade e eficiência.", "legalidade, supremacia do interesse público, moralidade, publicidade e eficiência.", "legalidade, impessoalidade, moralidade, publicidade e eficiência.", "legalidade, impessoalidade, moralidade, finalidade e publicidade."], "ci": 2, "why": "CF, art. 37, caput (eficiência incluída pela EC 19/98). Cuidado: a LOM, art. 80, cita apenas legalidade, impessoalidade, moralidade e publicidade. Razoabilidade e supremacia do interesse público são implícitos.", "study": "Dir. Administrativo, Aula demo"}, {"id": "c1-45", "src": "Caderno 1", "num": 45, "top": 8, "tema": null, "stem": "São elementos (requisitos) do ato administrativo:", "opts": ["competência, finalidade, forma, motivo e objeto.", "presunção de legitimidade, imperatividade, autoexecutoriedade e tipicidade.", "competência, vontade, forma, objeto e causa.", "sujeito, finalidade, motivo, tipicidade e imperatividade."], "ci": 0, "why": "Lei 4.717/65, art. 2º. Alternativa B lista atributos, não elementos. Pegadinha clássica: misturar os dois grupos.", "study": "Dir. Administrativo, Aula 03"}, {"id": "c1-46", "src": "Caderno 1", "num": 46, "top": 8, "tema": null, "stem": "Sobre os vícios do ato administrativo, é correto afirmar que:", "opts": ["todos os vícios são convalidáveis pela própria Administração.", "o desvio de finalidade pode ser convalidado se não houver prejuízo.", "nenhum vício é convalidável; todo ato viciado deve ser anulado.", "o vício de competência (não exclusiva) e o de forma (não essencial) são, em regra, convalidáveis; o desvio de finalidade não pode ser convalidado."], "ci": 3, "why": "Lei 9.784/99, art. 55. Convalidam-se defeitos sanáveis (competência e forma). Finalidade, motivo e objeto viciados não se convalidam.", "study": "Dir. Administrativo, Aula 04"}, {"id": "c1-47", "src": "Caderno 1", "num": 47, "top": 8, "tema": null, "stem": "A revogação do ato administrativo:", "opts": ["decorre de conveniência e oportunidade, é feita pela própria Administração e, em regra, produz efeitos ex nunc.", "decorre de ilegalidade, pode ser feita pelo Judiciário e produz efeitos ex tunc.", "pode ser feita pelo Judiciário por motivos de mérito.", "alcança atos vinculados e atos que já exauriram seus efeitos."], "ci": 0, "why": "Súmula 473 do STF. Revogação = mérito, Administração, ex nunc. Anulação = legalidade, Administração ou Judiciário, ex tunc. Atos vinculados não se revogam.", "study": "Dir. Administrativo, Aula 04"}, {"id": "c1-48", "src": "Caderno 1", "num": 48, "top": 8, "tema": null, "stem": "A licença, como espécie de ato administrativo, é ato:", "opts": ["vinculado e definitivo: preenchidos os requisitos legais, o particular tem direito a ela.", "discricionário e precário, revogável a qualquer tempo sem indenização.", "discricionário e definitivo, sujeito à conveniência da Administração.", "vinculado e precário, revogável por mudança de política."], "ci": 0, "why": "Licença = vinculado e definitivo. Autorização = discricionário e precário. Pegadinha: trocar os dois conceitos.", "study": "Dir. Administrativo, Aula 04"}, {"id": "c1-49", "src": "Caderno 1", "num": 49, "top": 8, "tema": null, "stem": "O poder de polícia administrativa caracteriza-se, em regra, pelos atributos de:", "opts": ["vinculação, tipicidade e imperatividade absolutas.", "somente discricionariedade, sem coercibilidade.", "discricionariedade, autoexecutoriedade e coercibilidade.", "delegabilidade integral a particulares."], "ci": 2, "why": "CTN, art. 78, e doutrina. A autoexecutoriedade exige previsão legal ou urgência; a delegação a particulares é restrita. Atenção às palavras absolutas (“sempre”, “somente”).", "study": "Dir. Administrativo, Aula 02"}, {"id": "c1-50", "src": "Caderno 1", "num": 50, "top": 8, "tema": null, "stem": "O decreto regulamentar expedido pelo Prefeito:", "opts": ["pode inovar originariamente, criando obrigações não previstas em lei.", "destina-se à fiel execução da lei e não pode exorbitar do poder regulamentar, sob pena de sustação pela Câmara.", "pode revogar lei municipal incompatível com o decreto.", "só pode ser expedido com aprovação prévia da Câmara."], "ci": 1, "why": "CF, art. 49, V e LOM, art. 34, X. O decreto regulamentar não cria direito novo nem revoga lei.", "study": "Dir. Administrativo, Aula 02"}, {"id": "c1-51", "src": "Caderno 1", "num": 51, "top": 17, "tema": null, "stem": "Segundo a CF (art. 37, XIX), no tocante à Administração Indireta:", "opts": ["a autarquia é criada por lei específica; a empresa pública, a sociedade de economia mista e a fundação têm sua instituição autorizada por lei específica.", "todas as entidades são criadas por decreto do Chefe do Executivo.", "a empresa pública é criada por lei, e a autarquia, por autorização legislativa.", "somente a sociedade de economia mista depende de lei."], "ci": 0, "why": "Autarquia: criada por lei. Empresas estatais e fundações: lei autoriza, e a personalidade surge com o registro. A LOM, art. 80, XIX, simplifica dizendo “criadas por lei”; na dúvida, siga a CF.", "study": "Dir. Administrativo, Aula 05"}, {"id": "c1-52", "src": "Caderno 1", "num": 52, "top": 18, "tema": null, "stem": "O servidor nomeado para cargo de provimento efetivo em virtude de concurso público adquire estabilidade, segundo a CF:", "opts": ["após 2 anos de efetivo exercício.", "após 3 anos de efetivo exercício e avaliação especial de desempenho.", "após 5 anos de efetivo exercício.", "imediatamente após a posse."], "ci": 1, "why": "CF, art. 41 (EC 19/98). A LOM, art. 84, ainda traz 2 anos: texto anterior à EC 19. Em questão sobre a Constituição, vale 3 anos.", "study": "Dir. Administrativo, Aula 06"}, {"id": "c1-53", "src": "Caderno 1", "num": 53, "top": 18, "tema": null, "stem": "Quando um agente público, nessa qualidade, causa dano a terceiro, segundo o STF (Tema 940):", "opts": ["a ação deve ser proposta contra o Estado (ou a prestadora de serviço público), assegurado o direito de regresso contra o agente nos casos de dolo ou culpa.", "a ação deve ser proposta diretamente contra o agente, e o Estado responde subsidiariamente.", "o Estado nunca responde, pois a responsabilidade é pessoal do agente.", "o Estado só responde se comprovada a culpa do agente e do órgão."], "ci": 0, "why": "CF, art. 37, § 6º, e RE 1.027.633. É a chamada dupla garantia: a vítima aciona o Estado, que depois cobra do agente em ação de regresso.", "study": "Dir. Administrativo, Aula 07"}, {"id": "c1-54", "src": "Caderno 1", "num": 54, "top": 26, "tema": null, "stem": "Após a Lei nº 14.230/2021, a configuração do ato de improbidade administrativa que causa dano ao erário (art. 10) exige:", "opts": ["apenas conduta culposa, ainda que sem dano comprovado.", "ação ou omissão dolosa que enseje perda patrimonial efetiva e comprovada.", "responsabilidade objetiva do agente.", "culpa grave, dispensado o dano efetivo."], "ci": 1, "why": "Lei 8.429/92, art. 10, com a redação da Lei 14.230/2021. A modalidade culposa foi extinta. A prescrição passou a ser de 8 anos (art. 23).", "study": "Dir. Administrativo, Aula 14"}, {"id": "c1-55", "src": "Caderno 1", "num": 55, "top": 26, "tema": null, "stem": "Quanto aos bens públicos dominicais, é correto afirmar que:", "opts": ["são inalienáveis em qualquer hipótese.", "podem ser alienados, observadas as exigências da lei.", "são de uso comum do povo.", "podem ser adquiridos por usucapião."], "ci": 1, "why": "Código Civil, arts. 99, III e 101. Imóveis municipais: avaliação, autorização legislativa e licitação (LOM, art. 101; Lei 14.133, art. 76). Bens públicos não são usucapíveis.", "study": "Dir. Administrativo, Aula 15"}, {"id": "c1-56", "src": "Caderno 1", "num": 56, "top": 3, "tema": null, "stem": "A Lei de Diretrizes Orçamentárias (LDO), segundo a CF (art. 165, § 2º):", "opts": ["estabelece diretrizes, objetivos e metas para os próximos quatro anos.", "compreende as metas e prioridades da administração, incluindo as despesas de capital do exercício seguinte, orienta a elaboração da LOA e dispõe sobre alterações na legislação tributária.", "fixa a despesa e estima a receita para o exercício financeiro.", "tem vigência de dois anos e substitui o plano plurianual."], "ci": 1, "why": "A alternativa B descreve o PPA; a C, a LOA. Pegadinha: trocar a função de cada peça do ciclo orçamentário.", "study": "Adm. Pública, Aula 07"}, {"id": "c1-57", "src": "Caderno 1", "num": 57, "top": 3, "tema": null, "stem": "O plano plurianual (PPA) tem vigência de:", "opts": ["quatro anos, do início do segundo ano do mandato ao final do primeiro ano do mandato seguinte.", "quatro anos, coincidindo exatamente com o mandato.", "um ano, o mesmo do exercício financeiro.", "dois anos, renováveis."], "ci": 0, "why": "CF, art. 165, § 1º e ADCT, art. 35, § 2º, I. A vigência atravessa a mudança de governo para dar continuidade aos programas de duração continuada.", "study": "Adm. Pública, Aula 07"}, {"id": "c1-58", "src": "Caderno 1", "num": 58, "top": 19, "tema": null, "stem": "Os créditos adicionais destinados a despesas imprevisíveis e urgentes, como as decorrentes de calamidade pública, são os:", "opts": ["extraordinários.", "suplementares.", "especiais.", "ordinários."], "ci": 0, "why": "CF, art. 167, § 3º. Suplementares reforçam dotação existente; especiais atendem despesas sem dotação específica; extraordinários, as imprevisíveis e urgentes (LOM, art. 140, § 3º).", "study": "Adm. Pública, Aula 07"}, {"id": "c1-59", "src": "Caderno 1", "num": 59, "top": 9, "tema": null, "stem": "A accountability, na Administração Pública, refere-se a:", "opts": ["exclusivamente o controle interno exercido pelo Executivo.", "sinônimo de eficiência na aplicação de recursos.", "controle realizado apenas pelo Poder Judiciário.", "prestar contas e responder pelos atos, abrangendo controles vertical (eleitoral), horizontal (entre instituições) e social."], "ci": 3, "why": "Accountability = responsabilização + prestação de contas + possibilidade de sanção. Não se limita a um único tipo de controle.", "study": "Adm. Pública, Aula 02"}, {"id": "c1-60", "src": "Caderno 1", "num": 60, "top": 19, "tema": null, "stem": "Em contraste com o modelo burocrático weberiano, a Nova Gestão Pública (NGP) enfatiza:", "opts": ["resultados e desempenho, orientação ao cidadão, flexibilização e descentralização.", "rigidez hierárquica e controle prévio dos procedimentos.", "formalismo como garantia da impessoalidade.", "centralização das decisões e padronização absoluta."], "ci": 0, "why": "O modelo burocrático prioriza processos, hierarquia e legalidade estrita; a NGP, resultados e gestão por desempenho. Atenção: os dois coexistem na prática.", "study": "Adm. Pública, Aulas demo e 01"}, {"id": "c1-61", "src": "Caderno 1", "num": 61, "top": 20, "tema": null, "stem": "No ciclo de políticas públicas, a etapa em que a decisão é transformada em ações concretas, com mobilização de recursos e agentes, é a:", "opts": ["formulação de alternativas.", "tomada de decisão.", "implementação.", "avaliação."], "ci": 2, "why": "Ciclo (Secchi): identificação do problema, formação da agenda, formulação, tomada de decisão, implementação, avaliação e extinção.", "study": "Adm. Pública, Aulas 04–06"}, {"id": "c1-62", "src": "Caderno 1", "num": 62, "top": 5, "tema": null, "stem": "Segundo a Lei Complementar nº 95/1998, a respeito do objeto e do âmbito de aplicação da lei:", "opts": ["uma mesma lei deve tratar de todos os assuntos correlatos, para evitar dispersão normativa.", "o mesmo assunto deve ser disciplinado por várias leis, para maior especificidade.", "excetuadas as codificações, cada lei tratará de um único objeto, sem matéria estranha a ele ou não vinculada por afinidade, pertinência ou conexão.", "o objeto e o âmbito de aplicação devem constar apenas da ementa."], "ci": 2, "why": "LC 95/1998, art. 7º. O primeiro artigo indica o objeto e o âmbito de aplicação. O mesmo assunto não pode ser tratado por mais de uma lei, salvo lei que complemente a básica por remissão expressa.", "study": "LC 95/1998 (leitura da lei)"}, {"id": "c1-63", "src": "Caderno 1", "num": 63, "top": 5, "tema": null, "stem": "Segundo a LC 95/1998, a numeração e a identificação das unidades da lei seguem a forma:", "opts": ["Art. 9 e Art. 10º; incisos em algarismos arábicos; alíneas em letras maiúsculas.", "Art. 9º e Art. 10º; “§ único” quando houver só um parágrafo; incisos em letras minúsculas.", "Art. 9º e Art. 10; alíneas em algarismos romanos; itens em letras minúsculas.", "Art. 9º e Art. 10; parágrafo único por extenso quando houver só um; incisos em algarismos romanos; alíneas em letras minúsculas; itens em algarismos arábicos."], "ci": 3, "why": "LC 95/1998, art. 10. Ordinal até o 9º e cardinal a partir do 10. Quando há só um parágrafo, escreve-se “Parágrafo único”, por extenso.", "study": "LC 95/1998 (leitura da lei)"}, {"id": "c1-64", "src": "Caderno 1", "num": 64, "top": 5, "tema": null, "stem": "Para acrescentar um novo artigo entre os arts. 5º e 6º de uma lei em vigor, a LC 95/1998 determina que se:", "opts": ["numere o novo dispositivo como Art. 5º-A, sem renumerar os demais, pois a renumeração é vedada.", "renumerem todos os artigos seguintes, para manter a sequência.", "numere como Art. 5º-bis, usando expressão em latim.", "renumerem apenas os artigos seguintes que forem recomendáveis."], "ci": 0, "why": "LC 95/1998, art. 12, III, “b”: é vedada, mesmo quando recomendável, a renumeração; usa-se o número anterior seguido de letra maiúscula. Também é vedado reaproveitar o número de dispositivo revogado ou vetado.", "study": "LC 95/1998 (leitura da lei)"}, {"id": "c1-65", "src": "Caderno 1", "num": 65, "top": 5, "tema": null, "stem": "Segundo o Manual de Redação da Presidência da República (3ª edição), os fechos das comunicações oficiais são:", "opts": ["“Atenciosamente,” somente para autoridades inferiores e “Cordialmente,” para as demais.", "“Respeitosamente,” para autoridades superiores e “Atenciosamente,” para autoridades de mesma hierarquia ou inferiores.", "“Respeitosamente,” para todos, sem distinção.", "“Sem mais para o momento,” em qualquer comunicação."], "ci": 1, "why": "Manual de Redação, 3ª ed., seção sobre fechos. O Manual unificou os fechos em dois. O pronome “Vossa Excelência” serve também para Prefeitos e Vereadores.", "study": "Redação Oficial, Aula única"}, {"id": "c1-66", "src": "Caderno 1", "num": 66, "top": 16, "tema": null, "stem": "Constitui crime de responsabilidade do Prefeito, segundo o art. 29-A da CF:", "opts": ["não enviar o repasse do duodécimo à Câmara até o dia 20 de cada mês.", "efetuar o repasse do duodécimo até o dia 20 de cada mês.", "enviar o duodécimo na proporção fixada na lei orçamentária.", "enviar o duodécimo respeitando os limites do art. 29-A."], "ci": 0, "why": "CF, art. 29-A, § 2º (e LOM, arts. 65, XVII e 141). Também é crime repassar valor que supere os limites ou enviá-lo a menor que a proporção da lei orçamentária.", "study": "Dir. Constitucional, Aula 07 (Municípios)"}, {"id": "c1-67", "src": "Caderno 1", "num": 67, "top": 16, "tema": null, "stem": "O subsídio dos Vereadores é fixado:", "opts": ["por lei de iniciativa do Prefeito, na mesma legislatura.", "pela própria Câmara Municipal, em cada legislatura para a subsequente, observados os limites constitucionais.", "por decreto do Prefeito, a cada ano.", "pelo Tribunal de Contas dos Municípios."], "ci": 1, "why": "CF, art. 29, VI e LOM, art. 35 (até 30 dias antes da eleição). Regimento, art. 102: se não aprovado nesse prazo, prevalece a resolução vigente.", "study": "Dir. Constitucional, Aula 07 (Municípios)"}, {"id": "c1-68", "src": "Caderno 1", "num": 68, "top": 16, "tema": null, "stem": "Quanto à competência legislativa dos Municípios, é correto afirmar que cabe a eles:", "opts": ["legislar sobre direito civil e processual.", "editar normas gerais de licitação e contratação.", "legislar sobre assuntos de interesse local e suplementar a legislação federal e a estadual no que couber.", "legislar sobre direito penal local."], "ci": 2, "why": "CF, art. 30, I e II. Normas gerais de licitação são da União (art. 22, XXVII); o Município suplementa. Direito civil, processual e penal são privativos da União.", "study": "Dir. Legislativo, Aula 02"}, {"id": "c1-69", "src": "Caderno 1", "num": 69, "top": 16, "tema": null, "stem": "Sobre as prerrogativas dos Vereadores, é correto afirmar que:", "opts": ["gozam de imunidade material e formal idênticas às dos Deputados Federais.", "são invioláveis por opiniões, palavras e votos no exercício do mandato e na circunscrição do Município, mas não têm imunidade formal (prisão e processo).", "são invioláveis por suas palavras em qualquer lugar do território nacional.", "não gozam de nenhuma inviolabilidade."], "ci": 1, "why": "CF, art. 29, VIII e LOM, art. 36. A inviolabilidade é só material, limitada ao exercício do mandato e à circunscrição do Município. Pegadinha: estender o regime dos parlamentares federais.", "study": "Dir. Constitucional, Aula 07"}, {"id": "c1-70", "src": "Caderno 1", "num": 70, "top": 31, "tema": null, "stem": "Assinale a alternativa correta quanto ao emprego do pronome relativo:", "opts": ["O vereador cujo projeto foi aprovado discursou na sessão.", "O vereador cujo o projeto foi aprovado discursou na sessão.", "O vereador que o projeto dele foi aprovado discursou na sessão.", "O vereador do qual o projeto dele foi aprovado discursou na sessão."], "ci": 0, "why": "“Cujo” indica posse, concorda com o termo possuído e dispensa o artigo. As alternativas C e D repetem a ideia de posse (pleonasmo).", "study": "Português, Aula 02"}, {"id": "c1-71", "src": "Caderno 1", "num": 71, "top": 31, "tema": null, "stem": "Assinale a frase correta quanto ao emprego dos pronomes pessoais:", "opts": ["A Mesa deu o documento para mim assinar.", "Entre eu e o colega não há divergência.", "Não há nada contra eu fazer.", "O relator trouxe os pareceres para eu analisar."], "ci": 3, "why": "Depois de preposição, usa-se mim; mas se o pronome é sujeito de um verbo no infinitivo, usa-se eu (“para eu analisar”). “Entre” pede mim: “entre mim e o colega”.", "study": "Português, Aula 02"}, {"id": "c1-72", "src": "Caderno 1", "num": 72, "top": 31, "tema": null, "stem": "Assinale a alternativa em que a concordância verbal está de acordo com a norma-padrão:", "opts": ["Haviam muitos projetos na pauta.", "Fazem dois anos que a lei foi publicada.", "Houve dúvidas sobre a redação do artigo.", "Existe vários vereadores novos na Câmara."], "ci": 2, "why": "“Haver” no sentido de existir e “fazer” indicando tempo são impessoais (ficam no singular). “Existir” concorda com o sujeito: “existem vários vereadores”.", "study": "Português, Aula 07"}, {"id": "c1-73", "src": "Caderno 1", "num": 73, "top": 31, "tema": null, "stem": "Assinale a alternativa correta quanto à regência e ao uso da crase:", "opts": ["O vereador assistiu a sessão inteira.", "O Prefeito obedeceu as normas da lei.", "Os servidores aspiram à promoção na carreira.", "Prefiro mais a negociação do que o conflito."], "ci": 2, "why": "“Aspirar” (almejar) pede preposição a: “à promoção”. “Assistir” (ver) também: “assistiu à sessão”. “Obedecer” pede a: “às normas”. “Preferir” dispensa “mais” e “do que”: “prefiro a negociação ao conflito”.", "study": "Português, Aula 08"}, {"id": "c1-74", "src": "Caderno 1", "num": 74, "top": 31, "tema": null, "stem": "Assinale a alternativa em que a regência do pronome relativo está correta:", "opts": ["Os documentos que necessito estão sobre a mesa.", "O cargo que aspiro exige concurso público.", "Os documentos de que necessito estão sobre a mesa.", "A lei que me referi foi revogada."], "ci": 2, "why": "Se o verbo exige preposição, ela vem antes do relativo: “necessitar de” (de que), “aspirar a” (a que), “referir-se a” (a que).", "study": "Português, Aula 08"}, {"id": "c1-75", "src": "Caderno 1", "num": 75, "top": 31, "tema": null, "stem": "Assinale a alternativa em que a vírgula está empregada corretamente:", "opts": ["O projeto, que foi vetado pelo Prefeito, voltou à Câmara.", "O relator da comissão, apresentou o parecer.", "Os vereadores, aprovaram o projeto por unanimidade.", "Quando o veto foi rejeitado o projeto foi promulgado."], "ci": 0, "why": "Nunca se separa sujeito de verbo com vírgula isolada (B e C). Na D, falta a vírgula após a oração adverbial antecipada. Na A, a oração explicativa vem entre vírgulas.", "study": "Português, Aula 06"}, {"id": "c1-76", "src": "Caderno 1", "num": 76, "top": 31, "tema": null, "stem": "No período “A proposta é inovadora; contudo, ainda carece de estudos de impacto”, a conjunção estabelece relação de:", "opts": ["conclusão, equivalendo a “portanto”.", "causa, equivalendo a “porque”.", "oposição (adversidade), equivalendo a “porém” ou “todavia”.", "adição, equivalendo a “além disso”."], "ci": 2, "why": "“Contudo”, “porém”, “todavia”, “entretanto” e “no entanto” são adversativas. Concessão (embora, ainda que) é diferente: introduz oração subordinada.", "study": "Português, Aula 05"}, {"id": "c1-77", "src": "Caderno 1", "num": 77, "top": 31, "tema": null, "stem": "Complete a frase com a forma verbal correta: “Se os vereadores ____ o parecer, o projeto seguirá ao Plenário.”", "opts": ["mantiverem", "mantêm", "mantiveram", "mantenham"], "ci": 0, "why": "“Se” + ideia de condição futura pede futuro do subjuntivo: “mantiverem” (de manter, derivado de ter: tiver, mantiver).", "study": "Português, Aula 04"}, {"id": "c1-78", "src": "Caderno 1", "num": 78, "top": 31, "tema": null, "stem": "Leia o texto: “A divulgação de pautas e votações pelas câmaras municipais não é favor ao cidadão: é obrigação decorrente do princípio da publicidade. Quando o acesso a essas informações exige conhecimento técnico, porém, a transparência é apenas formal. Disponibilizar dados sem torná-los compreensíveis cumpre a lei, mas não necessariamente cumpre sua finalidade.” Depreende-se do texto que:", "opts": ["a publicação de dados incompreensíveis descumpre a lei.", "divulgar informações é obrigação legal, mas a transparência efetiva requer que elas sejam compreensíveis.", "a transparência se esgota na divulgação de pautas e votações.", "o cidadão deve ter conhecimento técnico para acompanhar as votações."], "ci": 1, "why": "A alternativa B contraria o texto (ele diz que cumpre a lei). C reduz a ideia central. D inverte a crítica do autor. Pegadinha: extrapolar ou afirmar o contrário do que está dito.", "study": "Português, Aula 11"}, {"id": "c1-79", "src": "Caderno 1", "num": 79, "top": 32, "tema": null, "stem": "Um tributo sofreu um aumento de 20% e, em seguida, um novo aumento de 10%. O aumento acumulado foi de:", "opts": ["30%", "31%", "32%", "33%"], "ci": 2, "why": "Aumentos sucessivos se multiplicam: 1,20 × 1,10 = 1,32, ou seja, 32%. Pegadinha: somar os percentuais (30%).", "study": "Matemática, Aula 04"}, {"id": "c1-80", "src": "Caderno 1", "num": 80, "top": 32, "tema": null, "stem": "Quatro servidores analisam 200 processos em 5 dias, trabalhando no mesmo ritmo. Quantos servidores serão necessários para analisar 480 processos em 6 dias?", "opts": ["6", "8", "10", "12"], "ci": 1, "why": "Cada servidor analisa 200 ÷ (4 × 5) = 10 processos por dia. Para 480 processos em 6 dias: 480 ÷ (6 × 10) = 8 servidores. Regra de três composta: grandezas diretamente proporcionais.", "study": "Matemática, Aula 03"}, {"id": "c1-81", "src": "Caderno 1", "num": 81, "top": 32, "tema": null, "stem": "Um capital de R$ 2.000,00 é aplicado por 2 meses à taxa de 10% ao mês. A diferença entre os juros obtidos no regime composto e no regime simples é de:", "opts": ["R$ 10,00", "R$ 20,00", "R$ 21,00", "R$ 40,00"], "ci": 1, "why": "Composto: 2.000 × 1,21 = 2.420, juros de R$ 420. Simples: 2.000 × 0,10 × 2 = R$ 400. Diferença: R$ 20,00.", "study": "Matemática, Aulas 05–06"}, {"id": "c1-82", "src": "Caderno 1", "num": 82, "top": 32, "tema": null, "stem": "Uma verba de R$ 7.200,00 será dividida entre três setores, em partes diretamente proporcionais a 2, 3 e 4. O setor que receber a maior parte receberá:", "opts": ["R$ 2.400,00", "R$ 2.800,00", "R$ 3.200,00", "R$ 3.600,00"], "ci": 2, "why": "Soma das partes: 2 + 3 + 4 = 9. Cada parte vale 7.200 ÷ 9 = R$ 800. A maior (4 partes) recebe 4 × 800 = R$ 3.200,00.", "study": "Matemática, Aula 02"}, {"id": "c1-83", "src": "Caderno 1", "num": 83, "top": 33, "tema": null, "stem": "Na planilha eletrônica, a fórmula =CONT.SE(B2:B11;\"&gt;100\") retorna:", "opts": ["a soma dos valores do intervalo B2:B11 maiores que 100.", "a quantidade de células do intervalo B2:B11 com valor maior que 100.", "a média dos valores maiores que 100.", "a quantidade de células não vazias do intervalo."], "ci": 1, "why": "CONT.SE conta células que atendem a um critério. A soma condicional é SOMASE; a contagem de não vazias é CONT.VALORES.", "study": "Informática, Aula 05"}, {"id": "c1-84", "src": "Caderno 1", "num": 84, "top": 33, "tema": null, "stem": "Na célula C2 foi digitada a fórmula =B2*$E$1. Ao copiar C2 para C3, a fórmula resultante será:", "opts": ["=B3*E2", "=B2*$E$1", "=C3*$E$2", "=B3*$E$1"], "ci": 3, "why": "O sinal $ trava a referência (absoluta): $E$1 não muda ao copiar. B2 é relativa e passa a B3.", "study": "Informática, Aula 05"}, {"id": "c1-85", "src": "Caderno 1", "num": 85, "top": 33, "tema": null, "stem": "Em uma mensagem de correio eletrônico, os destinatários inseridos no campo CCO (cópia oculta):", "opts": ["são visíveis para todos os demais destinatários.", "não recebem a mensagem, apenas o registro dela.", "só podem responder ao remetente, e nunca a todos.", "recebem a mensagem sem que os demais destinatários vejam seus endereços."], "ci": 3, "why": "CC = cópia visível; CCO = cópia oculta, útil para preservar a privacidade. Quem está em CCO recebe normalmente.", "study": "Informática, Aula 02"}, {"id": "c1-86", "src": "Caderno 1", "num": 86, "top": 33, "tema": null, "stem": "O tipo de malware que criptografa os arquivos do usuário e exige pagamento para devolver o acesso é o:", "opts": ["spyware.", "ransomware.", "adware.", "keylogger."], "ci": 1, "why": "Ransomware “sequestra” dados mediante resgate. Spyware espia; adware exibe propaganda; keylogger registra teclas digitadas. Melhor defesa: backup atualizado e offline.", "study": "Informática, Aula 04"}, {"id": "v1-q001", "src": "Apostila Vol. 1", "num": 1, "top": 10, "tema": "v1-01", "stem": "Segundo o Regimento Interno, as espécies de proposição são:", "opts": ["requerimentos, indicações, moções, projetos de lei, projetos de decreto legislativo e emendas.", "requerimentos, moções, projetos de lei, projetos de resolução, pareceres e emendas, em rol exemplificativo.", "requerimentos, moções, projetos de lei, projetos de decreto legislativo, projetos de resolução, emendas e recursos.", "requerimentos, moções, projetos de lei, projetos de decreto legislativo, projetos de resolução e emendas."], "ci": 3, "why": "Art. 164. São seis espécies e o rol é taxativo: não existe uma sétima criada pela praxe. Pegadinha: acrescentar “indicações”, “pareceres” ou “recursos”, que são coisas do dia a dia, mas não estão no rol.", "study": "Regimento Interno, Aula 03 (art. 164)"}, {"id": "v1-q002", "src": "Apostila Vol. 1", "num": 2, "top": 10, "tema": "v1-01", "stem": "Sobre a devolução de proposições ao autor, nos termos do art. 165 do Regimento, é correto afirmar:", "opts": ["a proposição ilegal ou inconstitucional é sempre devolvida, mesmo que a ilegalidade seja controvertida.", "as proposições subscritas pela Comissão de Finanças, Justiça e Redação podem ser devolvidas por alegada ilegalidade.", "da devolução não cabe recurso, pois o juízo de admissibilidade é privativo do Presidente.", "a emenda que não guarde direta relação com a proposição a que se refere deve ser devolvida, e o Presidente fundamenta a devolução por escrito."], "ci": 3, "why": "Art. 165 e §§ 1º e 2º. O filtro alcança só o que for “manifestamente” anti-regimental, ilegal ou inconstitucional; o que é controvertido vai para as comissões. Proposição subscrita pela Comissão de Finanças, Justiça e Redação não pode deixar de ser recebida por alegada ilegalidade. Cabe recurso ao plenário (arts. 256 e 257).", "study": "Regimento Interno, Aula 03 (arts. 165 e 256-257)"}, {"id": "v1-q003", "src": "Apostila Vol. 1", "num": 3, "top": 10, "tema": "v1-01", "stem": "Quanto à autoria e à subscrição de proposições, o Regimento estabelece que:", "opts": ["consideram-se autores todos os signatários, em igualdade de condições.", "as assinaturas de apoio podem ser retiradas até o início da votação.", "considera-se autor o primeiro signatário, e as assinaturas de apoio não podem ser retiradas depois da entrega da proposição à Mesa.", "o autor é obrigado a fundamentar a proposição por escrito, sendo vedada a justificativa verbal."], "ci": 2, "why": "Autor é o primeiro signatário; as demais assinaturas são de apoio e implicam concordância com o mérito. O autor pode fundamentar por escrito ou verbalmente. Pegadinha: “pode retirar até a votação” e “só por escrito”.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q004", "src": "Apostila Vol. 1", "num": 4, "top": 10, "tema": "v1-01", "stem": "Um projeto de lei de iniciativa da Câmara foi rejeitado. De acordo com o Regimento, ele:", "opts": ["pode ser renovado a qualquer tempo, por qualquer Vereador.", "só pode ser renovado na mesma sessão legislativa se reapresentado por 2/3 dos Vereadores.", "nunca pode ser reapresentado, na mesma legislatura.", "só pode ser renovado na mesma sessão legislativa se reapresentado, no mínimo, pela maioria absoluta dos Vereadores."], "ci": 3, "why": "A regra vale para projetos de lei de iniciativa da Câmara e para requerimentos rejeitados ou não sancionados. Quórum para reapresentar: maioria absoluta, não 2/3.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q005", "src": "Apostila Vol. 1", "num": 5, "top": 10, "tema": "v1-02", "stem": "O art. 172 do Regimento classifica os requerimentos segundo os seguintes critérios:", "opts": ["autor, matéria e prazo de tramitação.", "maneira de formulá-los, quórum de aprovação e comissão competente.", "maneira de formulá-los, competência para decidi-los e fase de formulação.", "competência para decidi-los, número de signatários e fase de formulação."], "ci": 2, "why": "Art. 172: I, quanto à maneira de formulá-los (verbais ou escritos); II, quanto à competência para decidi-los (despacho de plano do Presidente ou deliberação do plenário); III, quanto à fase de formulação (somente durante o expediente, por exemplo).", "study": "Regimento Interno, Aula 03 (art. 172)"}, {"id": "v1-q006", "src": "Apostila Vol. 1", "num": 6, "top": 10, "tema": "v1-02", "stem": "Será despachado de plano pelo Presidente, sem votação do plenário, o requerimento que solicitar:", "opts": ["prorrogação da sessão.", "licença do Prefeito.", "encerramento de discussão de proposição.", "retificação de ata."], "ci": 3, "why": "Art. 173, b. As outras três estão no art. 175, ou seja, dependem de deliberação do plenário. Despacho de plano é para atos de condução simples: retirada pelo autor, verificação de presença, juntada de documentos, justificação de falta, entre outros.", "study": "Regimento Interno, Aula 03 (arts. 173 e 175)"}, {"id": "v1-q007", "src": "Apostila Vol. 1", "num": 7, "top": 10, "tema": "v1-02", "stem": "Entre os requerimentos sujeitos a despacho de plano, o Regimento exige que seja necessariamente escrito o que solicitar:", "opts": ["justificação de falta do Vereador às sessões plenárias.", "retirada, pelo autor, de requerimento verbal ou escrito.", "retificação de ata.", "verificação de presença."], "ci": 0, "why": "Art. 173, parágrafo único: são necessariamente escritos os das alíneas f a l (juntada ou desentranhamento, inclusão na Ordem do Dia, informações oficiais, voto de pesar, convocação de sessão extraordinária ou especial, justificação de falta e volta à tramitação de proposição arquivada). As alíneas a, b e c podem ser verbais.", "study": "Regimento Interno, Aula 03 (art. 173, parágrafo único)"}, {"id": "v1-q008", "src": "Apostila Vol. 1", "num": 8, "top": 10, "tema": "v1-02", "stem": "Dependem de deliberação do plenário, mas não admitem discussão, os requerimentos que solicitem:", "opts": ["convocação do Prefeito, constituição de Comissão de Inquérito e voto de louvor.", "inclusão de projeto na pauta em regime de urgência, prorrogação da sessão e inversão da pauta.", "convocação do Prefeito, prorrogação da sessão e inversão da pauta.", "constituição de Comissão Especial, urgência e destaque."], "ci": 1, "why": "Art. 175 (sem discussão): urgência, antecipação de discussão ou votação, retirada da pauta, preferência, emendas em bloco, destaque, encerramento de discussão, licença do Prefeito, prorrogação da sessão e inversão da pauta. Art. 176 (podem ser discutidos): convocação do Prefeito, Comissão Especial ou de Inquérito, informações com concordância do plenário, luto, voto de louvor e encerramento excepcional da sessão.", "study": "Regimento Interno, Aula 03 (arts. 175 e 176)"}, {"id": "v1-q009", "src": "Apostila Vol. 1", "num": 9, "top": 10, "tema": "v1-02", "stem": "Dos requerimentos do art. 175, que não admitem discussão, encaminhamento de votação nem declaração de voto, o único que comporta encaminhamento de votação é o de:", "opts": ["encerramento de discussão de proposição.", "inclusão de projeto em regime de urgência.", "prorrogação da sessão.", "licença do Prefeito."], "ci": 0, "why": "Art. 175, § 1º: a exceção é o requerimento do nº 7, encerramento de discussão. Os demais não admitem nenhuma das três coisas.", "study": "Regimento Interno, Aula 03 (art. 175, § 1º)"}, {"id": "v1-q010", "src": "Apostila Vol. 1", "num": 10, "top": 10, "tema": "v1-02", "stem": "Dos requerimentos que dependem de deliberação do plenário, sem discussão, podem ser verbais:", "opts": ["os de urgência e os de inversão da pauta.", "os de destaque e os de licença do Prefeito.", "os de antecipação de discussão ou votação e os de preferência para votação.", "todos, desde que o plenário concorde em votar de imediato."], "ci": 2, "why": "Art. 175, § 2º: somente os números 2 (antecipação) e 4 (preferência) podem ser verbais; os demais são necessariamente escritos.", "study": "Regimento Interno, Aula 03 (art. 175, § 2º)"}, {"id": "v1-q011", "src": "Apostila Vol. 1", "num": 11, "top": 10, "tema": "v1-02", "stem": "É necessariamente escrito, depende de deliberação do plenário e pode ser discutido o requerimento que solicitar:", "opts": ["constituição de Comissão Especial ou de Comissão de Inquérito.", "destaque para votação em separado de emendas.", "inversão da pauta.", "prorrogação da sessão."], "ci": 0, "why": "Art. 176, 2. Os outros três estão no art. 175 e não podem ser discutidos. Quando o requerimento comporta discussão, cada Vereador dispõe de 5 minutos.", "study": "Regimento Interno, Aula 03 (art. 176)"}, {"id": "v1-q012", "src": "Apostila Vol. 1", "num": 12, "top": 10, "tema": "v1-02", "stem": "O requerimento que solicitar a inserção de documentos nos anais da Câmara deverá:", "opts": ["ser verbal e aprovado por maioria simples.", "ser escrito e proposto pela Mesa, com aprovação de 2/3.", "ser escrito e proposto por, no mínimo, 1/3 dos Vereadores.", "ser despachado de plano pelo Presidente."], "ci": 2, "why": "Art. 176, parte final. Outra vez o quórum de subscrição de 1/3, o mesmo da moção e da convocação do Prefeito.", "study": "Regimento Interno, Aula 03 (art. 176)"}, {"id": "v1-q013", "src": "Apostila Vol. 1", "num": 13, "top": 10, "tema": "v1-03", "stem": "A moção, segundo o Regimento, é a proposição em que é sugerida a manifestação da Câmara sobre determinado assunto. Quanto ao seu rito:", "opts": ["é subscrita por qualquer Vereador, depende de parecer da Comissão de Finanças, Justiça e Redação e admite emendas.", "é subscrita por 1/3 dos Vereadores, depende de parecer e é votada em dois turnos.", "é subscrita pela maioria absoluta, vai à Ordem do Dia na própria sessão e admite emendas de redação.", "é subscrita por no mínimo 1/3 dos Vereadores, vai à Ordem do Dia da sessão ordinária seguinte independentemente de parecer, com discussão e votação únicas, e não admite emendas."], "ci": 3, "why": "Art. 179. Moção expressa aplauso, solidariedade ou apoio, apelo, protesto ou repúdio; não cria direitos nem obrigações. Cada Vereador tem 5 minutos para discutir.", "study": "Regimento Interno, Aula 03 (art. 179)"}, {"id": "v1-q014", "src": "Apostila Vol. 1", "num": 14, "top": 10, "tema": "v1-04", "stem": "Segundo o art. 183 do Regimento, a Câmara exerce a sua função legislativa por meio de:", "opts": ["projetos de lei, requerimentos e moções.", "projetos de lei, projetos de lei complementar e emendas.", "projetos de lei, projetos de decreto legislativo e projetos de resolução.", "projetos de lei, projetos de decreto legislativo e medidas provisórias."], "ci": 2, "why": "Art. 183. Requerimentos e moções são proposições, mas não são instrumentos da função legislativa. Também não há medida provisória no âmbito municipal.", "study": "Regimento Interno, Aula 03 (art. 183)"}, {"id": "v1-q015", "src": "Apostila Vol. 1", "num": 15, "top": 10, "tema": "v1-04", "stem": "Compete privativamente ao Prefeito a iniciativa de projeto de lei sobre:", "opts": ["fixação da remuneração dos Vereadores.", "aumento de vencimentos e outras vantagens dos servidores da administração centralizada.", "mudança do local de funcionamento da Câmara.", "alteração do Regimento Interno."], "ci": 1, "why": "Art. 185. A remuneração dos Vereadores e o Regimento são matéria de resolução; a mudança do local da Câmara, de decreto legislativo. Nenhuma depende de iniciativa do Prefeito.", "study": "Regimento Interno, Aula 03 (art. 185)"}, {"id": "v1-q016", "src": "Apostila Vol. 1", "num": 16, "top": 10, "tema": "v1-04", "stem": "Aos projetos de iniciativa privativa do Prefeito enumerados no art. 185 (orçamento, matéria financeira, cargos, aumento de despesas), o Regimento:", "opts": ["admite quaisquer emendas, desde que aprovadas por maioria absoluta.", "não admite emendas que aumentem direta ou indiretamente a despesa proposta ou diminuam a receita.", "admite emendas que alterem os quantitativos de cargos, desde que mantida a despesa.", "admite emendas apenas das comissões, ainda que aumentem a despesa."], "ci": 1, "why": "Art. 185, parágrafo único. Também não se admitem emendas que alterem a criação de cargos e funções quanto a quantitativos ou que resultem em aumento de despesa.", "study": "Regimento Interno, Aula 03 (art. 185, parágrafo único)"}, {"id": "v1-q017", "src": "Apostila Vol. 1", "num": 17, "top": 10, "tema": "v1-04", "stem": "Aprovado o projeto de autoria do Executivo, ou rejeitado na forma regimental, o Presidente da Câmara fará a devida comunicação ao Prefeito no prazo de:", "opts": ["48 horas.", "24 horas.", "5 dias úteis.", "15 dias úteis."], "ci": 0, "why": "Prazo de 48 horas. Não confunda com os 15 dias úteis, que são o prazo do Prefeito para sancionar ou vetar.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q018", "src": "Apostila Vol. 1", "num": 18, "top": 10, "tema": "v1-04", "stem": "Sobre os prazos de apreciação de projetos de lei subscritos por parcelas dos membros da Câmara, o Regimento dispõe:", "opts": ["projetos subscritos por 1/3 devem ser concluídos em 30 dias úteis; os subscritos por 1/4, em 20 dias úteis.", "projetos subscritos por 1/4 devem ter a apreciação concluída em 30 dias corridos; os subscritos por 1/3 podem pedir 20 dias corridos, faculdade que o mesmo Vereador só usa uma vez por ano.", "projetos subscritos por 1/4 devem ser concluídos em 45 dias corridos, sem limite de uso da faculdade.", "projetos subscritos por 1/3 devem ser concluídos em 20 dias, sem limite de uso, e os subscritos por 1/4 não têm prazo."], "ci": 1, "why": "Atenção a duas armadilhas: os prazos são em dias corridos, contados da apresentação, e a faculdade dos 20 dias é limitada a uma vez por ano para o mesmo Vereador. Esgotado o prazo, o projeto é colocado imediatamente em votação.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q019", "src": "Apostila Vol. 1", "num": 19, "top": 10, "tema": "v1-04", "stem": "Os projetos de lei com prazo de apreciação estabelecido em lei, independentemente de parecer das Comissões:", "opts": ["devem constar obrigatoriamente da Ordem do Dia.", "só entram na Ordem do Dia se houver parecer favorável.", "são arquivados se as Comissões não opinarem no prazo.", "dependem de requerimento de urgência aprovado pelo plenário para serem votados."], "ci": 0, "why": "Quem não pode travar o processo é a demora da comissão. O mesmo raciocínio aparece no art. 213, parágrafo único.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q020", "src": "Apostila Vol. 1", "num": 20, "top": 10, "tema": "v1-05", "stem": "O projeto de decreto legislativo, segundo o art. 190 do Regimento:", "opts": ["destina-se a matéria que exceda os limites da economia interna da Câmara, não é sujeito a sanção e é promulgado pelo Presidente da Câmara.", "destina-se a matéria político-administrativa interna da Câmara e é promulgado pelo Prefeito.", "é sujeito a sanção ou veto do Prefeito, como o projeto de lei.", "regula somente a concessão de títulos honoríficos."], "ci": 0, "why": "Art. 190. Decreto legislativo tem efeito externo e dispensa sanção. Os títulos honoríficos são apenas um dos exemplos.", "study": "Regimento Interno, Aula 03 (art. 190)"}, {"id": "v1-q021", "src": "Apostila Vol. 1", "num": 21, "top": 10, "tema": "v1-05", "stem": "Constitui matéria de projeto de decreto legislativo:", "opts": ["destituição de membro da Mesa.", "fixação da remuneração dos Vereadores.", "mudança do local de funcionamento da Câmara.", "constituição de comissões especiais."], "ci": 2, "why": "Art. 190, parágrafo único, f. As outras três são de projeto de resolução (art. 191, d, g e f). Decreto legislativo trata de contas do município, licença e consentimento ao Prefeito, remuneração do Prefeito e do Vice-Prefeito, representação à Assembleia sobre modificação territorial e mudança do local da Câmara.", "study": "Regimento Interno, Aula 03 (arts. 190 e 191)"}, {"id": "v1-q022", "src": "Apostila Vol. 1", "num": 22, "top": 10, "tema": "v1-05", "stem": "Constitui matéria de projeto de resolução:", "opts": ["aprovação ou rejeição das contas do município.", "fixação da remuneração do Prefeito e do Vice-Prefeito.", "perda do mandato de Vereador.", "consentimento ao Prefeito nos casos previstos em lei."], "ci": 2, "why": "Art. 191, c. Pegadinha clássica: remuneração dos Vereadores é resolução (art. 191, g), mas a do Prefeito e do Vice-Prefeito é decreto legislativo (art. 190, d). Contas do município: decreto legislativo.", "study": "Regimento Interno, Aula 03 (arts. 190 e 191)"}, {"id": "v1-q023", "src": "Apostila Vol. 1", "num": 23, "top": 10, "tema": "v1-05", "stem": "Os projetos devem atender a requisitos. Entre eles, o Regimento exige:", "opts": ["parecer prévio da Procuradoria anexado ao texto.", "assinatura de, no mínimo, 1/3 dos Vereadores.", "justificação, com a exposição circunstanciada dos motivos de mérito que fundamentam a medida proposta.", "redação em artigos de qualquer extensão, dispensada a numeração."], "ci": 2, "why": "Requisitos: apenas a enumeração da vontade legislativa; artigos numerados, claros e concisos; menção da revogação das disposições em contrário, quando for o caso; assinatura do autor; justificação.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q024", "src": "Apostila Vol. 1", "num": 24, "top": 10, "tema": "v1-05", "stem": "O projeto de resolução que objetive a criação de cargos na secretaria da Câmara depende do voto favorável de:", "opts": ["maioria absoluta dos membros da Câmara.", "2/3 dos membros da Câmara.", "maioria simples dos presentes.", "1/3 dos membros da Câmara."], "ci": 0, "why": "Quórum de maioria absoluta. Fique atento: 2/3 aparece em outros casos (títulos honoríficos, responsabilidade do Prefeito, destituição da Mesa).", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q025", "src": "Apostila Vol. 1", "num": 25, "top": 10, "tema": "v1-06", "stem": "Nos termos do art. 194, os projetos devem ser protocolados:", "opts": ["48 horas antes da sessão, para leitura na Ordem do Dia.", "15 dias úteis antes da sessão, para publicação prévia.", "3 dias úteis antes das sessões, condição obrigatória para apresentação no expediente seguinte, quando serão lidos e despachados de plano às Comissões Permanentes.", "a qualquer momento, sendo lidos na própria sessão em que forem protocolados."], "ci": 2, "why": "Art. 194. Se o prazo não for cumprido, o projeto não é lido na sessão pretendida e fica para a oportunidade seguinte. “De plano” significa sem votação.", "study": "Regimento Interno, Aula 03 (art. 194)"}, {"id": "v1-q026", "src": "Apostila Vol. 1", "num": 26, "top": 10, "tema": "v1-06", "stem": "Quanto à ordem de apreciação dos projetos pelas Comissões, o art. 194, § 1º, determina que são apreciados:", "opts": ["em primeiro lugar pela Comissão específica e em último pela Comissão de Finanças, Justiça e Redação.", "em primeiro lugar pela Comissão de Finanças, Justiça e Redação, quanto ao aspecto legal e constitucional, e em último pela Comissão específica, quando for o caso.", "somente pela Comissão específica, dispensado o exame de legalidade.", "simultaneamente por todas as Comissões, sem ordem."], "ci": 1, "why": "O filtro de legalidade e constitucionalidade vem antes do mérito. As emendas constantes de voto em separado ou voto vencido não são consideradas (§ 2º), e é admitida a apresentação de emendas no transcorrer das discussões (§ 3º).", "study": "Regimento Interno, Aula 03 (art. 194)"}, {"id": "v1-q027", "src": "Apostila Vol. 1", "num": 27, "top": 10, "tema": "v1-06", "stem": "Nenhum projeto será dado por definitivamente aprovado antes de passar por duas discussões e votações, além da redação final. A exceção é:", "opts": ["projetos de decreto legislativo e de lei complementar, que têm uma discussão e votação.", "projetos de resolução, que dispensam a redação final.", "projetos de lei de iniciativa do Prefeito, que têm discussão única.", "projetos de resolução e de decreto legislativo, que têm uma discussão e votação, além da redação final."], "ci": 3, "why": "Regra geral: dois turnos. Resolução e decreto legislativo: um turno, mas com redação final. Os projetos rejeitados em qualquer fase são arquivados.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q028", "src": "Apostila Vol. 1", "num": 28, "top": 10, "tema": "v1-06", "stem": "Nenhuma alteração, reforma ou substituição do Regimento Interno será dada por definitivamente aprovada sem que seja discutida:", "opts": ["pelo menos em 2 sessões ordinárias, ou em extraordinária convocada para tal fim.", "em sessão única, por 2/3 dos membros.", "em 3 sessões ordinárias consecutivas.", "em duas sessões extraordinárias convocadas pelo Prefeito."], "ci": 0, "why": "Discussão em pelo menos duas sessões ordinárias (ou extraordinária convocada para isso). Veja também os arts. 312 e 313, sobre iniciativa.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q029", "src": "Apostila Vol. 1", "num": 29, "top": 10, "tema": "v1-06", "stem": "Na primeira discussão de um projeto, segundo o Regimento:", "opts": ["cada Vereador dispõe de 5 minutos, a votação é em bloco e as emendas são votadas antes do projeto.", "cada Vereador dispõe de 10 minutos, e o projeto é votado artigo por artigo.", "cada Vereador dispõe de 5 minutos, e o projeto é votado antes das emendas.", "cada Vereador dispõe de 3 minutos, e a votação é sempre nominal."], "ci": 0, "why": "Arts. 200 a 202. Primeiro as emendas, depois o projeto já com as alterações aprovadas. A segunda discussão também é de 5 minutos por Vereador (art. 204).", "study": "Regimento Interno, Aula 03 (arts. 200-204)"}, {"id": "v1-q030", "src": "Apostila Vol. 1", "num": 30, "top": 10, "tema": "v1-06", "stem": "Se o projeto for aprovado com emendas, o processo é encaminhado à Procuradoria da Câmara, que terá, para redigi-lo conforme o aprovado, o prazo de:", "opts": ["24 horas.", "15 dias úteis.", "3 dias.", "30 dias."], "ci": 2, "why": "Art. 205. Atenção para não misturar com os 3 dias úteis das Comissões para parecer em projetos com prazo (arts. 211 a 213).", "study": "Regimento Interno, Aula 03 (art. 205)"}, {"id": "v1-q031", "src": "Apostila Vol. 1", "num": 31, "top": 10, "tema": "v1-06", "stem": "Sobre a redação final, é correto afirmar:", "opts": ["se houver dúvida quanto à vontade legislativa por incoerência notória, contradição evidente ou manifesto absurdo, a Comissão se exime de oferecer redação final e propõe a reabertura da discussão.", "a Procuradoria pode alterar o sentido da matéria aprovada, desde que o justifique em parecer.", "a redação final nunca pode corrigir erro de linguagem.", "emendas à redação final são livres, podendo tratar de qualquer aspecto do projeto."], "ci": 0, "why": "Art. 207. A correção de incorreção ou impropriedade de linguagem é permitida desde que não altere a vontade legislativa, com menção expressa e justificação no parecer (art. 206, parágrafo único). Reaberta a discussão, só cabem emendas estritamente relativas ao aspecto reaberto (art. 209).", "study": "Regimento Interno, Aula 03 (arts. 206-209)"}, {"id": "v1-q032", "src": "Apostila Vol. 1", "num": 32, "top": 10, "tema": "v1-06", "stem": "Não havendo emendas à redação final proposta:", "opts": ["considera-se aprovada a redação final, e a matéria é remetida à sanção do Prefeito ou à promulgação do Presidente.", "a redação final é obrigatoriamente submetida a nova votação em plenário.", "o projeto retorna à Comissão para novo parecer.", "o projeto é arquivado."], "ci": 0, "why": "Art. 208. Havendo emendas de redação, o projeto volta à Comissão de Finanças, Justiça e Redação para parecer (§ 1º).", "study": "Regimento Interno, Aula 03 (art. 208)"}, {"id": "v1-q033", "src": "Apostila Vol. 1", "num": 33, "top": 10, "tema": "v1-06", "stem": "Projeto de lei com prazo de apreciação recebeu parecer contrário da Comissão de Finanças, Justiça e Redação quanto ao aspecto legal ou constitucional. De acordo com o art. 212:", "opts": ["será arquivado automaticamente, sem votação.", "seguirá para as demais Comissões, independentemente de votação do parecer.", "será incluído em pauta da sessão seguinte, para discussão e votação únicas do parecer; aprovado o parecer, o projeto é arquivado; rejeitado, segue a tramitação normal.", "será votado em dois turnos, junto com o mérito."], "ci": 2, "why": "Quem vota é o plenário, e o que ele vota é o parecer. Aprovar o parecer contrário significa concordar que o projeto é ilegal ou inconstitucional, então ele é arquivado.", "study": "Regimento Interno, Aula 03 (art. 212)"}, {"id": "v1-q034", "src": "Apostila Vol. 1", "num": 34, "top": 10, "tema": "v1-06", "stem": "A Comissão de Finanças, Justiça e Redação dispõe, para emitir parecer sobre o aspecto legal ou constitucional de projeto com prazo de apreciação, de:", "opts": ["2 dias, prorrogáveis por mais 1.", "5 dias improrrogáveis.", "15 dias úteis.", "3 dias úteis, contados do recebimento do projeto."], "ci": 3, "why": "Art. 211, § 2º, e art. 213. Esgotado o prazo, o projeto é incluído em pauta para primeira discussão, com ou sem parecer, sendo vedado adiar a discussão ou a votação para ouvir as Comissões (art. 213, parágrafo único).", "study": "Regimento Interno, Aula 03 (arts. 211-213)"}, {"id": "v1-q035", "src": "Apostila Vol. 1", "num": 35, "top": 10, "tema": "v1-06", "stem": "Aprovado em primeira discussão, o projeto de lei com prazo de apreciação:", "opts": ["é remetido imediatamente à sanção do Prefeito.", "depende de requerimento do autor para ser votado novamente.", "é votado em segunda discussão na mesma sessão.", "volta, na sessão ordinária seguinte, à segunda votação; aprovado em segunda discussão, segue para a redação final, e, se rejeitado, vai ao arquivo."], "ci": 3, "why": "Arts. 215 e 216. O rito dos dois turnos é preservado, e a rejeição em qualquer fase manda o projeto para o arquivo.", "study": "Regimento Interno, Aula 03 (arts. 215-216)"}, {"id": "v1-q036", "src": "Apostila Vol. 1", "num": 36, "top": 10, "tema": "v1-07", "stem": "A retirada de proposições, segundo o art. 220, dá-se por requerimento do autor:", "opts": ["a qualquer tempo, mesmo durante a votação.", "somente após a aprovação em primeira discussão.", "somente se aprovada pela maioria absoluta.", "desde que a proposição não tenha sido submetida à apreciação do plenário."], "ci": 3, "why": "Depois que o plenário começa a deliberar, a matéria passa a ser interesse da Casa. Se a autoria for da Mesa ou de Comissão, a retirada obedece à regra da maioria de seus membros.", "study": "Regimento Interno, Aula 03 (art. 220)"}, {"id": "v1-q037", "src": "Apostila Vol. 1", "num": 37, "top": 10, "tema": "v1-07", "stem": "No início de cada legislatura são arquivados os projetos que, até o encerramento da legislatura anterior, não tenham sido aprovados em pelo menos uma discussão. Esse arquivamento:", "opts": ["aplica-se inclusive aos projetos do Executivo.", "não se aplica às proposições de iniciativa do Executivo.", "alcança apenas os projetos de iniciativa dos Vereadores com parecer contrário.", "alcança apenas os projetos de resolução."], "ci": 1, "why": "As proposições do Executivo escapam do arquivamento. A volta à tramitação exige requerimento do líder da bancada, ou da maioria dos membros, se a autoria for da Mesa ou de Comissão permanente.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q038", "src": "Apostila Vol. 1", "num": 38, "top": 10, "tema": "v1-07", "stem": "Não podem ser desarquivadas as proposições:", "opts": ["de autoria da Mesa.", "inquinadas de inconstitucionalidade ou ilegalidade e as que tenham parecer contrário de comissões de mérito.", "apresentadas por Vereadores que não foram reeleitos.", "que tenham recebido emendas."], "ci": 1, "why": "Duas travas ao desarquivamento: vício de legalidade ou constitucionalidade, e parecer contrário de comissão de mérito.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q039", "src": "Apostila Vol. 1", "num": 39, "top": 10, "tema": "v1-08", "stem": "Na discussão de um projeto, a ordem de uso da palavra do Regimento é:", "opts": ["primeiro os relatores, depois o autor.", "primeiro o autor, depois os relatores das comissões na ordem em que se pronunciaram; em projeto da Mesa ou de Comissão, os autores são os respectivos Presidentes.", "primeiro o líder da maioria, depois o autor.", "primeiro o Presidente da Câmara, depois o autor e os relatores."], "ci": 1, "why": "Em projeto do Executivo, considera-se autor, para este fim, o Vereador que goza de prerrogativas de líder, como intérprete do pensamento do Prefeito junto à Câmara.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q040", "src": "Apostila Vol. 1", "num": 40, "top": 10, "tema": "v1-08", "stem": "O Presidente não interromperá o orador que estiver discutindo qualquer matéria, salvo:", "opts": ["para dar a palavra a outro Vereador que a tenha solicitado.", "para aparte do Presidente de comissão.", "porque o tempo regimental do orador chegou à metade.", "para dar conhecimento ao plenário de requerimento de prorrogação da sessão e colocá-lo em votação."], "ci": 3, "why": "Art. 225: três exceções (prorrogação da sessão, comunicação importante, urgente e inadiável, e tumulto grave). O orador interrompido pela votação da prorrogação não perde a vez, se estiver presente quando chamado a continuar.", "study": "Regimento Interno, Aula 03 (art. 225)"}, {"id": "v1-q041", "src": "Apostila Vol. 1", "num": 41, "top": 10, "tema": "v1-08", "stem": "Sobre os apartes, é correto afirmar:", "opts": ["dependem de autorização do Presidente, e não têm limite de duração.", "podem ser feitos durante o expediente, desde que com o consentimento do orador.", "são permitidos mesmo quando o orador está encaminhando votação.", "são consentidos, não podem passar de 1 minuto, e é vedado ao Presidente, ou a quem o substitua na presidência, apartear o orador."], "ci": 3, "why": "Art. 228. Não são permitidos apartes: à palavra do Presidente na direção dos trabalhos, paralelos ou cruzados, quando o orador encaminha votação, faz declaração de voto ou fala sobre a ata, e durante o expediente.", "study": "Regimento Interno, Aula 03 (art. 228)"}, {"id": "v1-q042", "src": "Apostila Vol. 1", "num": 42, "top": 10, "tema": "v1-08", "stem": "Segundo o Regimento, o encerramento da discussão dá-se:", "opts": ["por decisão do Presidente, quando julgar a matéria esclarecida.", "por inexistência de orador ou por disposição legal.", "apenas por requerimento aprovado pelo plenário.", "pelo término do tempo da sessão, em qualquer hipótese."], "ci": 1, "why": "A discussão não será encerrada quando houver requerimento de adiamento pendente de votação por falta de quórum. Já o requerimento de encerramento (art. 175, nº 7) é outro caminho, que depende de deliberação do plenário.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q043", "src": "Apostila Vol. 1", "num": 43, "top": 10, "tema": "v1-09", "stem": "Se, no curso da votação de uma matéria, esgotar-se o tempo destinado à sessão:", "opts": ["a sessão é encerrada, e a votação continua na sessão seguinte.", "a sessão só é prorrogada se houver requerimento aprovado pelo plenário.", "a votação é suspensa por até 24 horas.", "a sessão é prorrogada até que a votação seja concluída por inteiro, salvo falta de número para deliberar, caso em que é encerrada imediatamente."], "ci": 3, "why": "Considera-se a matéria em fase de votação a partir do momento em que o Presidente declara encerrada a discussão (art. 298, § 2º).", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q044", "src": "Apostila Vol. 1", "num": 44, "top": 10, "tema": "v1-09", "stem": "O Vereador presente à sessão não pode escusar-se de votar. Segundo o Regimento, deve abster-se quando:", "opts": ["for do partido do autor da proposição.", "for parente apenas em primeiro grau do autor.", "ele próprio, ou parente afim ou consanguíneo até o terceiro grau, tiver interesse manifesto na deliberação, sob pena de nulidade da votação quando seu voto for decisivo.", "discordar do mérito da matéria."], "ci": 2, "why": "O Vereador que se considerar impedido comunica o fato ao Presidente, e sua presença é computada para efeito de quórum. Parentesco até o terceiro grau inclusive, afim ou consanguíneo.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q045", "src": "Apostila Vol. 1", "num": 45, "top": 10, "tema": "v1-09", "stem": "O Presidente da Câmara só tem voto:", "opts": ["em todas as votações, como qualquer Vereador.", "somente em caso de empate.", "na eleição da Mesa, nas votações em que a matéria exigir quórum de dois terços e quando ocorrer empate.", "na eleição da Mesa e nas votações de maioria absoluta."], "ci": 2, "why": "Essas mesmas normas se aplicam ao Vereador que substituir o Presidente na direção dos trabalhos. Não confunda com a maioria absoluta: nela o Presidente não vota, a não ser que haja empate.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q046", "src": "Apostila Vol. 1", "num": 46, "top": 10, "tema": "v1-09", "stem": "Votada uma proposição, as demais que tratem do mesmo assunto na mesma sessão legislativa, ainda que não anexadas a ela:", "opts": ["seguem a tramitação normal.", "são consideradas prejudicadas e remetidas ao arquivo.", "são votadas em conjunto na sessão seguinte.", "são devolvidas aos autores."], "ci": 1, "why": "É a chamada prejudicialidade. Não se confunde com a devolução ao autor do art. 165, que trata de proposições com vício de admissibilidade.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q047", "src": "Apostila Vol. 1", "num": 47, "top": 10, "tema": "v1-09", "stem": "Sobre o encaminhamento de votação, o Regimento estabelece que:", "opts": ["cada emenda tem seu encaminhamento próprio, por qualquer Vereador.", "somente o autor do projeto pode encaminhar a votação.", "o encaminhamento ocorre antes do encerramento da discussão.", "terão preferência o líder ou vice-líder de cada bancada ou Vereador indicado pela liderança, e, havendo emendas, haverá apenas um encaminhamento sobre todas as peças do projeto."], "ci": 3, "why": "O encaminhamento só cabe depois de o Presidente declarar encerrada a discussão. Tempo: 2 minutos, sem apartes (art. 251, e).", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q048", "src": "Apostila Vol. 1", "num": 48, "top": 10, "tema": "v1-09", "stem": "Os dois processos de votação previstos no Regimento são o simbólico e o nominal. Quanto a eles:", "opts": ["no simbólico, há consignação do nome de cada Vereador; no nominal, apenas a contagem global.", "no simbólico, os que concordam permanecem sentados e os contrários se levantam; no nominal há consignação do nome e do voto de cada Vereador. A votação secreta foi suprimida pela Resolução nº 17/2003.", "o voto secreto é permitido para a apreciação de vetos.", "a votação nominal é feita por chamada em ordem de inscrição."], "ci": 1, "why": "Palavras-chave: simbólico = sentar e levantar; nominal = chamada e nome. A votação nominal é feita por chamada em ordem alfabética, e, se não houver quórum ao fim da chamada, o secretário faz uma segunda e última chamada dos que ainda não votaram.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q049", "src": "Apostila Vol. 1", "num": 49, "top": 10, "tema": "v1-09", "stem": "Se algum Vereador tiver dúvida quanto ao resultado da votação simbólica proclamada, poderá requerer:", "opts": ["nova votação simbólica, que o Presidente pode indeferir.", "verificação nominal de votação; se o requerimento ficar prejudicado pela ausência do autor ou por pedido de retirada, qualquer outro Vereador pode reformulá-lo.", "anulação da sessão, perante a Mesa.", "votação secreta."], "ci": 1, "why": "Art. 246. Pelas regras do painel eletrônico, o Presidente não pode indeferir o requerimento de verificação e não se admite segunda verificação; em caso de dúvida, pode repetir de ofício a votação simbólica.", "study": "Regimento Interno, Aula 03 (art. 246)"}, {"id": "v1-q050", "src": "Apostila Vol. 1", "num": 50, "top": 10, "tema": "v1-09", "stem": "Quanto à declaração de voto, o Regimento determina que:", "opts": ["pode ser feita antes da votação, com 5 minutos e apartes.", "é feita a cada emenda votada, com 2 minutos.", "é obrigatória para todo Vereador que vote contra.", "é feita de uma só vez, depois de concluída por inteiro a votação de todas as peças do projeto, com 1 minuto para cada Vereador, vedados apartes."], "ci": 3, "why": "A declaração de voto serve para registrar as razões depois de a decisão estar tomada, e não para retomar o debate. Ela consta da ata.", "study": "Regimento Interno, Aula 03 (art. 251, f)"}, {"id": "v1-q051", "src": "Apostila Vol. 1", "num": 51, "top": 10, "tema": "v1-10", "stem": "Quanto ao controle do tempo de uso da palavra, o Regimento determina que:", "opts": ["o tempo é controlado pelo secretário, para conhecimento do Presidente, e começa a fluir quando for dada a palavra; interrupções, exceto aparte concedido, não são computadas.", "o tempo é controlado pelo próprio orador.", "o tempo é controlado pelo Presidente, sem auxílio, e inclui as interrupções.", "o tempo só começa a correr depois do primeiro aparte."], "ci": 0, "why": "A interrupção por aparte consome o tempo do orador; qualquer outra interrupção, não.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q052", "src": "Apostila Vol. 1", "num": 52, "top": 10, "tema": "v1-10", "stem": "Na discussão de veto, cada Vereador dispõe de:", "opts": ["5 minutos, com apartes.", "5 minutos, sem apartes.", "10 minutos, sem apartes.", "2 minutos, sem apartes."], "ci": 1, "why": "Art. 251, b, 1. Pegadinha: na discussão de projeto (b, 2), também são 5 minutos, mas com apartes. O que muda é o aparte.", "study": "Regimento Interno, Aula 03 (art. 251)"}, {"id": "v1-q053", "src": "Apostila Vol. 1", "num": 53, "top": 10, "tema": "v1-10", "stem": "Nos processos de destituição da Mesa ou de membros da Mesa e de cassação de mandato de Vereador, o tempo para discussão é, respectivamente:", "opts": ["5 e 10 minutos, para ambos os processos.", "15 minutos para cada Vereador e 30 para o denunciado, na destituição; 10 e 20 na cassação.", "10 minutos para cada Vereador e 20 para o denunciado, na destituição; 15 minutos para cada Vereador e 30 para o denunciado ou seu procurador, na cassação.", "10 minutos para todos os envolvidos, nos dois processos."], "ci": 2, "why": "Art. 251, b, 5 e 6. Nos dois casos há apartes. Macete: o processo de maior gravidade (cassação) tem os maiores tempos.", "study": "Regimento Interno, Aula 03 (art. 251)"}, {"id": "v1-q054", "src": "Apostila Vol. 1", "num": 54, "top": 10, "tema": "v1-10", "stem": "Nos assuntos parlamentares, para encaminhamento de votação e para a palavra pela ordem, os tempos do Regimento são, respectivamente:", "opts": ["5 minutos, 2 minutos e 1 minuto, todos com apartes.", "10 minutos, 2 minutos e 1 minuto, todos sem apartes.", "10 minutos, 5 minutos e 2 minutos, sem apartes.", "5 minutos, 1 minuto e 1 minuto, todos sem apartes."], "ci": 1, "why": "Art. 251, c, e e g. Para solicitar esclarecimentos ao Prefeito e a auxiliares: 5 minutos, sem apartes (h). Para pedir retificação ou impugnar a ata: 5 minutos, sem apartes (a).", "study": "Regimento Interno, Aula 03 (art. 251)"}, {"id": "v1-q055", "src": "Apostila Vol. 1", "num": 55, "top": 10, "tema": "v1-11", "stem": "Pela ordem, o Vereador só poderá falar para:", "opts": ["discutir o mérito da proposição em pauta.", "pedir licença para ausentar-se da sessão por mais de 15 dias.", "solicitar a censura do Presidente a qualquer pronunciamento de outro Vereador que contenha expressão, frase ou conceito que considerar injurioso.", "apresentar projeto de lei durante a Ordem do Dia."], "ci": 2, "why": "Art. 252: sete hipóteses taxativas (reclamar contra preterição de formalidade, suscitar dúvida de interpretação, comunicação de líder à Mesa, prorrogação de Comissão Especial, retificação de voto ou ata, censura, esclarecimentos do Presidente).", "study": "Regimento Interno, Aula 03 (art. 252)"}, {"id": "v1-q056", "src": "Apostila Vol. 1", "num": 56, "top": 10, "tema": "v1-11", "stem": "Não se admitirão questões de ordem:", "opts": ["durante o expediente.", "quando houver aparte em curso.", "quando houver orador na tribuna, quando o Presidente estiver com a palavra na direção dos trabalhos ou quando se estiver procedendo a qualquer votação.", "durante o intervalo regimental."], "ci": 2, "why": "Art. 252, parágrafo único. Além disso: a questão de ordem de censura só será publicada se o Presidente não promover a censura solicitada.", "study": "Regimento Interno, Aula 03 (art. 252, parágrafo único)"}, {"id": "v1-q057", "src": "Apostila Vol. 1", "num": 57, "top": 10, "tema": "v1-11", "stem": "Da decisão ou omissão do Presidente em questão de ordem, representação ou proposição de Vereador, cabe recurso ao plenário. Esse recurso:", "opts": ["pode ser verbal, a qualquer tempo, e suspende a decisão.", "deve ser escrito e proposto no prazo improrrogável de 2 dias úteis; até a deliberação do plenário, prevalece a decisão do Presidente.", "deve ser proposto no prazo de 15 dias úteis, com efeito suspensivo.", "é julgado pelo próprio Presidente."], "ci": 1, "why": "Parecer da Comissão de Finanças, Justiça e Redação em 2 dias úteis improrrogáveis, e inclusão obrigatória na Ordem do Dia da sessão ordinária seguinte. Rejeitado por maioria simples, a decisão é mantida. Aprovado, o Presidente deve cumprir, sob pena de destituição.", "study": "Regimento Interno, Aula 03 (arts. 256-257)"}, {"id": "v1-q058", "src": "Apostila Vol. 1", "num": 58, "top": 10, "tema": "v1-11", "stem": "Ao final de cada sessão legislativa, a Mesa fará, por meio de ato, a:", "opts": ["revisão geral do Regimento Interno.", "consolidação de todos os precedentes regimentais firmados, publicando-os em avulso para distribuição aos Vereadores.", "revogação dos precedentes que não tenham sido reiterados.", "consolidação das leis aprovadas, para publicação no diário oficial."], "ci": 1, "why": "Os precedentes resolvem os casos omissos decididos pelo plenário e orientam situações semelhantes.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q059", "src": "Apostila Vol. 1", "num": 59, "top": 11, "tema": "v1-12", "stem": "O projeto aprovado pela Câmara será enviado ao Prefeito, para sanção ou veto, no prazo de:", "opts": ["15 dias úteis, contados da data de sua aprovação; o período de recesso não é reconhecido como dia útil.", "48 horas da aprovação.", "30 dias corridos da aprovação.", "10 dias da aprovação, improrrogáveis."], "ci": 0, "why": "Não confunda os 15 dias úteis (envio ao Prefeito) com os 10 dias para promulgação e publicação de decretos legislativos e resoluções e com as 48 horas de promulgação da lei.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q060", "src": "Apostila Vol. 1", "num": 60, "top": 11, "tema": "v1-12", "stem": "Para deliberar sobre o veto, a Câmara disporá de:", "opts": ["30 dias úteis, contados do recebimento do ofício; em recesso, conta-se da primeira sessão ordinária após o recesso, e a entrada em recesso interrompe o prazo.", "15 dias corridos, contados da publicação.", "30 dias corridos, que correm durante o recesso.", "45 dias úteis, prorrogáveis por igual período."], "ci": 0, "why": "O veto, considerado matéria de urgência, é lido em qualquer fase da sessão, tão logo chegue à Câmara. Na volta do recesso, deve ser obrigatoriamente lido na primeira sessão ordinária.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q061", "src": "Apostila Vol. 1", "num": 61, "top": 11, "tema": "v1-12", "stem": "O veto cujas razões versem sobre constitucionalidade, legalidade, interesse público ou aspecto financeiro será despachado à Comissão de Finanças, Justiça e Redação, que terá:", "opts": ["prazo de 3 dias úteis, prorrogáveis por mais 3.", "prazo improrrogável de 5 dias para parecer; esgotado, o veto é incluído na pauta da primeira sessão ordinária, com ou sem parecer.", "prazo de 15 dias úteis, findo o qual o veto é considerado mantido.", "prazo de 2 dias úteis, findo o qual o veto é arquivado."], "ci": 1, "why": "Incluído em Ordem do Dia, o veto é submetido à votação aberta, única, com uma única discussão.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q062", "src": "Apostila Vol. 1", "num": 62, "top": 11, "tema": "v1-12", "stem": "No veto parcial, a votação:", "opts": ["é necessariamente em bloco quando se tratar de matéria correlata ou idêntica; caso contrário, é possível votar em separado cada disposição autônoma, a requerimento de no mínimo 1/3 dos Vereadores, com assentimento do plenário, sem discussão, encaminhamento nem declaração de voto no requerimento.", "é sempre artigo por artigo.", "é sempre em bloco, vedada a votação em separado.", "pode ser em separado por requerimento de qualquer Vereador, com discussão."], "ci": 0, "why": "Arts. 277 e seguintes. O quórum de 1/3 é para pedir a votação em separado. Já o quórum para rejeitar o veto é outro: maioria absoluta.", "study": "Regimento Interno, Aula 03 (art. 277)"}, {"id": "v1-q063", "src": "Apostila Vol. 1", "num": 63, "top": 11, "tema": "v1-12", "stem": "A votação do veto faz-se mediante:", "opts": ["voto secreto, com cédula de dizeres antagônicos.", "voto simbólico, por sentados e levantados.", "voto aberto, por chamada nominal em ordem de inscrição, sem cédula.", "voto aberto, com uma única cédula de dizeres antagônicos: “Aceito o Veto” e “Rejeito o Veto”."], "ci": 3, "why": "Art. 278. A votação secreta foi suprimida do Regimento (Res. 17/2003). Observe que o voto é aberto, mas a cédula existe: não são incompatíveis.", "study": "Regimento Interno, Aula 03 (art. 278)"}, {"id": "v1-q064", "src": "Apostila Vol. 1", "num": 64, "top": 11, "tema": "v1-12", "stem": "Para a rejeição do veto é necessário o voto de, no mínimo:", "opts": ["a maioria simples dos presentes.", "a maioria absoluta dos Vereadores.", "2/3 dos Vereadores.", "3/5 dos Vereadores."], "ci": 1, "why": "Art. 279. É a mesma exigência do art. 66, § 4º, da CF (maioria absoluta). Rejeitado o veto, o projeto vai ao Prefeito para sanção.", "study": "Regimento Interno, Aula 03 (art. 279)"}, {"id": "v1-q065", "src": "Apostila Vol. 1", "num": 65, "top": 11, "tema": "v1-12", "stem": "Rejeitado o veto, o projeto é enviado ao Prefeito para sanção. Se a lei não for sancionada em 48 horas pelo Prefeito:", "opts": ["a Mesa Diretora a promulga em 15 dias.", "o Presidente da Câmara a promulga; se este não o fizer em igual prazo, caberá ao Vice-Presidente.", "o Vice-Prefeito a promulga.", "o projeto volta ao plenário para nova votação."], "ci": 1, "why": "Art. 279, § 2º. A ordem é: Prefeito, Presidente da Câmara, Vice-Presidente.", "study": "Regimento Interno, Aula 03 (art. 279, § 2º)"}, {"id": "v1-q066", "src": "Apostila Vol. 1", "num": 66, "top": 11, "tema": "v1-12", "stem": "Os decretos legislativos e as resoluções serão promulgados pelo Presidente e enviados à publicação dentro do prazo máximo e improrrogável de:", "opts": ["48 horas, contadas da aprovação.", "15 dias úteis, contados da aprovação.", "30 dias, contados da redação final.", "10 dias, contados da data de sua aprovação em plenário, ressalvadas as exceções regimentais."], "ci": 3, "why": "Decretos legislativos e resoluções não passam por sanção do Prefeito; por isso, quem promulga é o Presidente da Câmara.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q067", "src": "Apostila Vol. 1", "num": 67, "top": 11, "tema": "v1-12", "stem": "Quanto ao registro dos originais de leis, decretos legislativos e resoluções:", "opts": ["são registrados em livros próprios, rubricados pelo Presidente, arquivados na secretaria da Câmara, e uma cópia autêntica, assinada pelo Presidente e pelo primeiro secretário, é enviada ao Prefeito.", "são registrados no Executivo, que remete cópia à Câmara.", "são registrados somente em meio eletrônico.", "são assinados pelo Presidente e pelo segundo secretário."], "ci": 0, "why": "A cópia autêntica vai ao Prefeito “para os fins legais”, assinada pelo Presidente e pelo primeiro secretário, ou seus substitutos legais.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q068", "src": "Apostila Vol. 1", "num": 68, "top": 11, "tema": "v1-12", "stem": "Qualquer interpelação de Vereadores sobre os serviços da secretaria ou a situação do respectivo pessoal deve ser:", "opts": ["feita oralmente, em plenário, ao Diretor competente.", "dirigida à Mesa, através do Presidente, e formulada obrigatoriamente por escrito.", "dirigida diretamente à Diretoria de Gestão de Pessoas.", "dirigida ao Prefeito."], "ci": 1, "why": "Depois de informada por escrito, a interpelação é encaminhada ao Vereador para conhecimento.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q069", "src": "Apostila Vol. 1", "num": 69, "top": 27, "tema": "v1-13", "stem": "A convocação do Prefeito pela Câmara para prestar informações sobre assunto de sua competência administrativa far-se-á por requerimento:", "opts": ["subscrito por qualquer Vereador, votado sem discussão.", "subscrito por no mínimo 1/3 dos Vereadores, discutido e votado sem encaminhamento nem declaração de voto, indicando explicitamente o motivo e os quesitos.", "subscrito pela maioria absoluta, despachado de plano pelo Presidente.", "subscrito por 2/3, dispensada a indicação de quesitos."], "ci": 1, "why": "Art. 283. Aprovado o requerimento, o Presidente oficia o Prefeito e pede que marque dia e hora. O Prefeito deve atender em até 15 dias, improrrogáveis, do recebimento do ofício.", "study": "Regimento Interno, Aula 03 (art. 283)"}, {"id": "v1-q070", "src": "Apostila Vol. 1", "num": 70, "top": 27, "tema": "v1-13", "stem": "Na sessão extraordinária destinada a ouvir o Prefeito convocado, o Regimento assegura:", "opts": ["1 hora para o Prefeito discorrer, prorrogável por igual período mediante deliberação do plenário, sem apartes; 2 minutos para cada Vereador solicitar esclarecimentos e 5 minutos para cada resposta do Prefeito.", "30 minutos para o Prefeito, improrrogáveis, com apartes.", "1 hora para o Prefeito, com apartes livres; 5 minutos por Vereador.", "tempo ilimitado ao Prefeito, e 10 minutos para cada Vereador."], "ci": 0, "why": "Pegadinha: três números (1 hora, 2 minutos, 5 minutos). O Prefeito e os Vereadores não podem se desviar da matéria da convocação.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q071", "src": "Apostila Vol. 1", "num": 71, "top": 27, "tema": "v1-13", "stem": "O Prefeito pode comparecer à Câmara, independentemente de convocação, para prestar esclarecimentos:", "opts": ["sobre qualquer matéria, quando julgar oportuno fazê-lo pessoalmente, em dia e hora previamente estabelecidos.", "somente sobre matéria orçamentária.", "somente com aprovação de 2/3 dos Vereadores.", "somente durante a Ordem do Dia de sessão ordinária."], "ci": 0, "why": "Art. 286. Na sessão extraordinária convocada para esse fim, o Prefeito faz exposição inicial e responde às interpelações. Aplicam-se as regras do artigo anterior.", "study": "Regimento Interno, Aula 03 (art. 286)"}, {"id": "v1-q072", "src": "Apostila Vol. 1", "num": 72, "top": 27, "tema": "v1-13", "stem": "Sobre as contas do Prefeito, o Regimento dispõe que, rejeitadas as contas, por votação ou pelo decurso de prazo:", "opts": ["serão arquivadas.", "serão devolvidas ao Tribunal de Contas.", "serão imediatamente remetidas ao Ministério Público, para os devidos fins.", "será instaurado, automaticamente, processo de cassação do Prefeito."], "ci": 2, "why": "As contas de cada exercício são julgadas pela Câmara. Não confundir com o julgamento político da responsabilidade do Prefeito, que exige 2/3.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q073", "src": "Apostila Vol. 1", "num": 73, "top": 27, "tema": "v1-13", "stem": "A responsabilidade do Prefeito, por crime de responsabilidade, só será decretada pelo voto de no mínimo:", "opts": ["2/3 dos Vereadores.", "maioria absoluta dos Vereadores.", "maioria simples dos presentes.", "3/5 dos Vereadores."], "ci": 0, "why": "Deliberando a Câmara pela responsabilidade do Prefeito, o Presidente obrigatoriamente iniciará as medidas judiciais cabíveis.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q074", "src": "Apostila Vol. 1", "num": 74, "top": 27, "tema": "v1-13", "stem": "Nas sessões extraordinárias convocadas pelo Prefeito, o Regimento prevê que:", "opts": ["se as Comissões Permanentes estiverem com os mandatos extintos, são consideradas prorrogadas até o final das sessões extraordinárias.", "as Comissões Permanentes ficam suspensas até o fim do recesso.", "o rito é o dos projetos com prazo de 15 dias úteis.", "as normas regimentais comuns ficam todas afastadas."], "ci": 0, "why": "Arts. 262 a 264. Aplica-se a tramitação dos projetos de lei com prazo de 30 dias, respeitada a fase de tramitação iniciada antes. As disposições regimentais não colidentes aplicam-se aos períodos extraordinários.", "study": "Regimento Interno, Aula 03 (arts. 262-264)"}, {"id": "v1-q075", "src": "Apostila Vol. 1", "num": 75, "top": 22, "tema": "v1-14", "stem": "A Câmara pode conceder títulos honoríficos, comendas e outras honrarias por meio de:", "opts": ["projeto de lei, aprovado por maioria absoluta, em dois turnos.", "projeto de decreto legislativo, aprovado em discussão e votação únicas, pelo voto de no mínimo 2/3 de seus membros.", "projeto de resolução, aprovado por maioria simples.", "requerimento aprovado por 1/3 dos Vereadores."], "ci": 1, "why": "Art. 266. Vale para personalidade nacional ou estrangeira radicada no País, comprovadamente digna da homenagem. A exigência de residência no País cai para estrangeiros mundialmente consagrados pelos serviços prestados à humanidade (§ 2º).", "study": "Regimento Interno, Aula 03 (art. 266)"}, {"id": "v1-q076", "src": "Apostila Vol. 1", "num": 76, "top": 22, "tema": "v1-14", "stem": "É vedada a concessão de títulos honoríficos a:", "opts": ["pessoas residentes fora do município.", "pessoas no exercício de mandato eletivo ou em cargos executivos por nomeação.", "pessoas falecidas.", "servidores efetivos da Câmara."], "ci": 1, "why": "Art. 266, § 1º. Cada Vereador pode apresentar, no máximo, 2 proposições por ano, por tipo de honraria (§ 3º), e não pode figurar como primeiro signatário em mais de duas vezes por sessão legislativa.", "study": "Regimento Interno, Aula 03 (art. 266, § 1º)"}, {"id": "v1-q077", "src": "Apostila Vol. 1", "num": 77, "top": 22, "tema": "v1-14", "stem": "Quanto à instrução do projeto de concessão de título honorífico, o Regimento exige:", "opts": ["circunstanciada biografia do homenageado e, como condição de recebimento pela Mesa, sua anuência por escrito, exceto quanto a personalidades estrangeiras.", "apenas a justificação do autor.", "parecer favorável do Tribunal de Contas.", "assinatura de todos os Vereadores."], "ci": 0, "why": "Os signatários são considerados fiadores das qualidades do homenageado e não podem retirar suas assinaturas depois de recebida a propositura pela Mesa. Discussão: 5 minutos por Vereador.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q078", "src": "Apostila Vol. 1", "num": 78, "top": 22, "tema": "v1-14", "stem": "Na sessão solene de entrega dos títulos, para falar em nome da Câmara só será permitida a palavra:", "opts": ["de qualquer Vereador inscrito.", "somente do Presidente.", "do Vereador designado pelo Presidente como orador oficial, do autor da propositura e de um Vereador indicado por cada partido ou bloco com assento na Câmara.", "do orador oficial e do homenageado."], "ci": 2, "why": "Art. 270, § 3º. No último ano do mandato, a propositura de honrarias deve ser feita até a sessão ordinária do mês de junho, para que sejam entregues dentro do mandato (§ 2º). Sessões solenes devem ser realizadas dentro do mandato do Vereador autor (§ 1º).", "study": "Regimento Interno, Aula 03 (art. 270)"}, {"id": "v1-q079", "src": "Apostila Vol. 1", "num": 79, "top": 14, "tema": "v1-15", "stem": "Em relação ao orçamento, o Regimento Interno de Rio Verde:", "opts": ["estabelece rito detalhado de cinco sessões de discussão.", "atribui à Mesa a iniciativa da proposta orçamentária.", "dispensa a votação em plenário.", "não estabelece rito próprio detalhado, remetendo sua disciplina à Lei Orgânica do Município."], "ci": 3, "why": "O orçamento é de iniciativa privativa do Prefeito (art. 185), e o rito segue a Lei Orgânica. Não se admite destaque na proposta orçamentária, nas diretrizes, no PPA nem no julgamento das contas.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q080", "src": "Apostila Vol. 1", "num": 80, "top": 14, "tema": "v1-15", "stem": "A segurança do edifício da Câmara Municipal compete:", "opts": ["ao Prefeito, por meio da Guarda Municipal.", "à Procuradoria da Câmara.", "à Mesa, sob a direção do Presidente, podendo ser feita por servidores do serviço próprio ou por entidade contratada e habilitada.", "à Polícia Militar, exclusivamente."], "ci": 2, "why": "Art. 294. No plenário, durante as sessões, só serão admitidos os Vereadores, os servidores em serviço e os convidados. Quem perturbar a ordem, desacatar a Mesa, Vereadores ou servidores, sendo ineficazes as providências da Presidência, será detido e encaminhado à autoridade competente.", "study": "Regimento Interno, Aula 03 (arts. 294-295)"}, {"id": "v1-q081", "src": "Apostila Vol. 1", "num": 81, "top": 14, "tema": "v1-15", "stem": "Qualquer cidadão poderá assistir às sessões das galerias, desde que guarde silêncio e respeito. Quando o Presidente não conseguir manter a ordem por simples advertências, deverá:", "opts": ["encerrar definitivamente a sessão.", "mandar votar a expulsão do público.", "suspender a sessão, adotando as providências cabíveis.", "convocar a Polícia Militar, sem suspender a sessão."], "ci": 2, "why": "Art. 295, parágrafo único. Quem perturbar com aplausos ou manifestações de reprovação e não atender à advertência será compelido a sair imediatamente do edifício.", "study": "Regimento Interno, Aula 03 (art. 295)"}, {"id": "v1-q082", "src": "Apostila Vol. 1", "num": 82, "top": 14, "tema": "v1-16", "stem": "Segundo o art. 298, as deliberações da Câmara realizam-se, em regra:", "opts": ["pelo processo simbólico, com sentados e levantados.", "por cédulas, sempre secretas.", "por aclamação, quando o Presidente entender conveniente.", "pelo Sistema Eletrônico de Votação (Painel de Votações); o voto assim dado não pode ser modificado depois de proclamado o resultado, e o voto é sempre público."], "ci": 3, "why": "Na impossibilidade de usar o sistema eletrônico, aplicam-se as regras do art. 84 e seguintes. Art. 299: o voto será sempre público nas deliberações da Câmara.", "study": "Regimento Interno, Aula 03 (arts. 298-299)"}, {"id": "v1-q083", "src": "Apostila Vol. 1", "num": 83, "top": 14, "tema": "v1-16", "stem": "No sistema do Painel Eletrônico, o processo nominal é a regra geral. O processo simbólico:", "opts": ["pode ser usado em qualquer matéria, a critério do Presidente.", "é vedado em qualquer hipótese.", "pode ser usado na apreciação de veto, por ser matéria de urgência.", "pode ser usado a requerimento de Vereador aprovado pelo plenário ou nos casos previstos no Regimento, e não pode ser usado para eleição da Mesa, julgamento das contas do município, perda de mandato, veto, urgência especial e matérias de maioria absoluta ou 2/3."], "ci": 3, "why": "A votação não pode ser simbólica nas hipóteses de maior relevância: Mesa, contas, perda de mandato, veto, urgência especial e quórum qualificado (maioria absoluta ou 2/3).", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q084", "src": "Apostila Vol. 1", "num": 84, "top": 14, "tema": "v1-16", "stem": "Uma vez iniciada a votação no plenário:", "opts": ["somente se interrompe se for verificada a falta de número legal, e é vedado ao Vereador abandonar o plenário no curso da votação, salvo mal súbito.", "pode ser interrompida a qualquer tempo por requerimento verbal.", "pode ser interrompida por pedido de vista do autor.", "continua mesmo sem número legal, pois já iniciada."], "ci": 0, "why": "Se faltar número, os votos já colhidos são considerados prejudicados. Se o Vereador acometido de mal súbito sair, é considerado o voto que já tenha proferido.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q085", "src": "Apostila Vol. 1", "num": 85, "top": 14, "tema": "v1-16", "stem": "Antes de iniciar a votação, é assegurado a cada bancada, por seu líder ou integrante indicado, falar apenas uma vez, para orientar os compartidários quanto ao mérito da matéria, por:", "opts": ["2 minutos.", "5 minutos.", "3 minutos.", "10 minutos."], "ci": 2, "why": "Art. 303. A votação só pode ser aberta após o término dos encaminhamentos, e a orientação de bancada não impede que qualquer Vereador encaminhe a matéria. Não confunda com o encaminhamento do art. 251, e, que é de 2 minutos.", "study": "Regimento Interno, Aula 03 (art. 303)"}, {"id": "v1-q086", "src": "Apostila Vol. 1", "num": 86, "top": 14, "tema": "v1-16", "stem": "Qualquer Vereador poderá requerer destaque para votação em separado de parte do texto de uma proposição. Não haverá destaque, porém, quando se tratar de:", "opts": ["projeto de decreto legislativo.", "emenda de comissão.", "projeto de resolução.", "proposta orçamentária, diretrizes orçamentárias, plano plurianual, julgamento das contas do município ou casos em que a providência se revele impraticável."], "ci": 3, "why": "Em regra o projeto é votado em bloco. O destaque é a exceção, que serve para isolar um trecho problemático.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q087", "src": "Apostila Vol. 1", "num": 87, "top": 14, "tema": "v1-16", "stem": "Quanto à ordem de votação das emendas, terão preferência:", "opts": ["as emendas aditivas, sempre.", "as emendas do autor do projeto, sempre.", "as emendas protocoladas por último.", "as emendas supressivas e as emendas e substitutivos oriundos das comissões; se houver duas ou mais emendas sobre o mesmo artigo ou parágrafo, terá preferência a que for protocolada primeiro."], "ci": 3, "why": "Sempre que o parecer da comissão for pela rejeição do projeto, o plenário delibera primeiro sobre o parecer, antes de entrar no projeto.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q088", "src": "Apostila Vol. 1", "num": 88, "top": 14, "tema": "v1-16", "stem": "Proclamado o resultado da votação, o Vereador poderá impugná-lo perante o plenário quando dela tenha participado Vereador impedido. Acolhida a impugnação:", "opts": ["anula-se a sessão.", "a matéria é arquivada.", "o resultado proclamado é mantido, e o Vereador impedido é punido.", "repete-se a votação, sem considerar o voto que motivou o incidente."], "ci": 3, "why": "Após a proclamação, o Painel Eletrônico exibe os detalhes da votação por no mínimo 20 segundos.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q089", "src": "Apostila Vol. 1", "num": 89, "top": 14, "tema": "v1-16", "stem": "Em relação à emenda à redação final, o Regimento admite:", "opts": ["somente a emenda que se destine a despojá-la de obscuridade, contradição ou impropriedade linguística.", "qualquer emenda de mérito.", "emendas supressivas e aditivas livremente.", "nenhuma emenda, em qualquer hipótese."], "ci": 0, "why": "Aprovada a emenda, a matéria volta à comissão para nova redação final. Rejeitada a nova redação, o projeto é mais uma vez encaminhado à comissão, e considera-se aprovada a redação se contra ela não votar a maioria absoluta dos componentes da Câmara.", "study": "Regimento Interno, Aula 03"}, {"id": "v1-q090", "src": "Apostila Vol. 1", "num": 90, "top": 14, "tema": "v1-17", "stem": "Segundo o Regimento, o Regimento Interno da Câmara somente pode ser alterado, reformado ou substituído:", "opts": ["por lei, em projeto de iniciativa do Prefeito.", "por Resolução, em projeto proposto por no mínimo 1/3 dos membros da Câmara ou pela Mesa Diretora.", "por Decreto Legislativo, em projeto de qualquer Vereador.", "por Resolução, em projeto de qualquer Vereador."], "ci": 1, "why": "Arts. 312 e 313. Tema recorrente: instrumento (Resolução) e legitimados (1/3 ou Mesa). Vigência: data de publicação (art. 314).", "study": "Regimento Interno, Aula 03 (arts. 312-314)"}, {"id": "v1-q091", "src": "Apostila Vol. 1", "num": 91, "top": 25, "tema": "v1-18", "stem": "A Lei nº 7.434/2023 estabelece:", "opts": ["o Regulamento Interno da Estrutura Organizacional da Câmara Municipal de Rio Verde, definindo atribuições e subordinação das unidades que a compõem.", "o Plano de Cargos e Remuneração dos servidores da Câmara.", "o Regimento Interno da Câmara.", "o Estatuto dos Servidores Públicos do Município."], "ci": 0, "why": "A Lei 7.434 cuida da estrutura; a Lei 7.435 cuida do plano de cargos. Trocar uma pela outra é a pegadinha mais barata e mais frequente.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q092", "src": "Apostila Vol. 1", "num": 92, "top": 25, "tema": "v1-18", "stem": "A Direção Superior do Poder Legislativo será exercida:", "opts": ["pelo Presidente da Câmara, com exclusividade.", "pela Mesa Diretora, através de seu Presidente, auxiliado pelos Vereadores, diretores, procuradores, assessores e demais servidores.", "pelo Diretor Legislativo.", "pelo plenário, por meio de comissões."], "ci": 1, "why": "Os integrantes da Mesa Diretora estão definidos no Regimento Interno, e não na Lei 7.434.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q093", "src": "Apostila Vol. 1", "num": 93, "top": 25, "tema": "v1-18", "stem": "Compõem a Estrutura Administrativa do Poder Legislativo, subordinados diretamente ao Presidente e demais membros da Mesa Diretora:", "opts": ["a Presidência, as Diretorias e os Gabinetes Parlamentares.", "a Presidência, as Gerências e as Coordenadorias Setoriais.", "as Diretorias, as Coordenadorias Setoriais e os Gabinetes Parlamentares.", "a Presidência, as Diretorias e as Coordenadorias Setoriais."], "ci": 3, "why": "Art. 6º. Gabinetes Parlamentares não compõem a estrutura administrativa: são órgãos independentes, constituídos pelos auxiliares, assistentes e assessores imediatos de um legislador.", "study": "Leis 7.434 e 7.435/2023, Aula 00 (art. 6º)"}, {"id": "v1-q094", "src": "Apostila Vol. 1", "num": 94, "top": 25, "tema": "v1-18", "stem": "Quanto ao modelo de gestão e à atuação sistêmica previstos na Lei 7.434:", "opts": ["cada unidade administrativa planeja suas competências de forma descentralizada e autônoma.", "as unidades de sistemas estruturantes subordinam-se hierarquicamente aos gabinetes parlamentares.", "as competências das unidades de gestão institucional são planejadas, coordenadas e controladas de forma centralizada, por meio de sistemas estruturantes, e as unidades que exercem funções de sistemas estruturantes subordinam-se tecnicamente à unidade central do sistema.", "a gestão é exclusivamente centralizada no Presidente, vedada a participação social."], "ci": 2, "why": "O modelo é marcado pela gestão participativa e pela atuação transparente, que permite controle social do Poder Legislativo.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q095", "src": "Apostila Vol. 1", "num": 95, "top": 25, "tema": "v1-18", "stem": "Integram a Presidência, no âmbito do Gabinete da Presidência:", "opts": ["Diretoria Legislativa, Diretoria Parlamentar e Diretoria Financeira.", "Chefia de Gabinete, Ouvidoria, Corregedoria Parlamentar, Procuradoria Geral, Controle Interno, Assessoria de Plenário e Assessoria de Imprensa da Presidência.", "Coordenadoria de Compras e Licitações e Coordenadoria de Folha de Pagamento.", "Chefia de Pessoal e Gerência de Tesouraria."], "ci": 1, "why": "Pegadinha de enumeração: Ouvidoria, Corregedoria Parlamentar, Procuradoria Geral e Controle Interno estão na Presidência, e não nas Diretorias.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q096", "src": "Apostila Vol. 1", "num": 96, "top": 25, "tema": "v1-18", "stem": "A Lei 7.434 prevê, entre as Diretorias da Câmara:", "opts": ["Legislativa, Parlamentar, Financeira, de Obras e de Saúde.", "Legislativa, Parlamentar, de Gestão de Pessoas, de Tecnologia em Informação, de Administração e Planejamento, Financeira, de Comunicação Social, de Assuntos Institucionais, de Contratos e Convênios e de Articulação Política.", "Legislativa, Jurídica, Financeira e de Almoxarifado e Patrimônio.", "Legislativa, Parlamentar, de Compras e Licitações e de Folha de Pagamento."], "ci": 1, "why": "São 10 Diretorias. Almoxarifado e Patrimônio, Compras e Licitações, Manutenção e Serviços Gerais, Relações Públicas, Folha de Pagamento e Engenharia e Projetos são Coordenadorias Setoriais (6).", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q097", "src": "Apostila Vol. 1", "num": 97, "top": 25, "tema": "v1-18", "stem": "São Coordenadorias Setoriais da Câmara, nos termos da Lei 7.434:", "opts": ["Almoxarifado e Patrimônio, Compras e Licitações, Tesouraria e Contabilidade.", "Compras e Licitações, Contratos e Convênios e Articulação Política.", "Folha de Pagamento, Gestão de Pessoas e Comunicação Social.", "Almoxarifado e Patrimônio, Compras e Licitações, Manutenção e Serviços Gerais, Relações Públicas, Folha de Pagamento, e Engenharia e Projetos."], "ci": 3, "why": "Dentro de Compras e Licitações estão o Agente de Contratação e a Gerência de Cotação de Preços. Dentro do Almoxarifado, a Chefia do Núcleo de Almoxarifado.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q098", "src": "Apostila Vol. 1", "num": 98, "top": 25, "tema": "v1-18", "stem": "Na Diretoria Financeira, a Lei 7.434 prevê as seguintes gerências:", "opts": ["Tesouraria, Contratos e Cotação de Preços.", "Contabilidade, Arquivo e Documentação, e Folha de Pagamento.", "Tesouraria, Contabilidade, e Planejamento Orçamentário e Financeiro.", "Tesouraria, Expediente e Protocolo, e Suporte de Informática."], "ci": 2, "why": "São três gerências. A Gerência de Contratos pertence à Diretoria de Contratos e Convênios; a de Arquivo e Documentação, à Diretoria de Gestão de Pessoas.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q099", "src": "Apostila Vol. 1", "num": 99, "top": 25, "tema": "v1-18", "stem": "A Coordenadoria Legislativa de Plenário, vinculada à Diretoria Legislativa, compreende as gerências de:", "opts": ["Expediente e Protocolo, Imprensa e Comunicação, e Gravação e Som.", "Apoio Legislativo, Tesouraria, e Redação de Atas.", "Processamento e Controle, Suporte de Informática, e Desenvolvimento de Sistemas.", "Apoio Legislativo, Processamento e Controle, e Redação de Atas."], "ci": 3, "why": "A Diretoria Legislativa tem ainda a Chefia do Núcleo de Apoio Legislativo e a Gerência de Expediente e Protocolo.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q100", "src": "Apostila Vol. 1", "num": 100, "top": 25, "tema": "v1-18", "stem": "Na Diretoria de Comunicação Social, a Lei 7.434 prevê:", "opts": ["a Gerência de Imprensa e Comunicação (com as assessorias de Comunicação, de Imprensa, de Mídias Digitais e de Relações Públicas) e a Gerência de Gravação e Som.", "a Gerência de Tesouraria e a Gerência de Contabilidade.", "apenas a Assessoria de Imprensa da Presidência.", "a Gerência de Suporte de Informática e a de Desenvolvimento de Sistemas."], "ci": 0, "why": "A Gerência de Suporte de Informática e a de Desenvolvimento de Sistemas são da Diretoria de Tecnologia em Informação.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q101", "src": "Apostila Vol. 1", "num": 101, "top": 25, "tema": "v1-18", "stem": "Segundo as diretrizes do art. 10 da Lei 7.434, os setores terão desdobramento operativo observando que a estrutura básica de direção superior:", "opts": ["reparte as funções de comando entre as Diretorias.", "unifica numa mesma autoridade as funções de comando, coordenação, controle, planejamento estratégico e articulação institucional.", "agrupa as funções de direção intermediária e gerência administrativa.", "corresponde às funções de apoio direto de consultoria e assessoria."], "ci": 1, "why": "Art. 10: direção superior (unificada), gerência intermediária (direção intermediária, planejamento, coordenação, controle, supervisão, orientação técnica e gerência administrativa) e assessoramento (apoio direto, atribuições técnico-especializadas de consultoria, assessoramento e assistência).", "study": "Leis 7.434 e 7.435/2023, Aula 00 (art. 10)"}, {"id": "v1-q102", "src": "Apostila Vol. 1", "num": 102, "top": 25, "tema": "v1-18", "stem": "Segundo as disposições finais da Lei 7.434, os casos omissos serão resolvidos:", "opts": ["pela Mesa Diretora; os cargos efetivos e em comissão que ocuparão as unidades e suas remunerações estão previstos no Plano de Cargos e Remuneração.", "pelo plenário, em votação de maioria absoluta.", "pelo Presidente, isoladamente.", "pela Procuradoria Geral."], "ci": 0, "why": "A ligação entre as duas leis está aqui: a estrutura (7.434) se completa com os cargos e remunerações (7.435).", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q103", "src": "Apostila Vol. 1", "num": 103, "top": 29, "tema": "v1-19", "stem": "O regime jurídico dos servidores de provimento efetivo do Poder Legislativo do Município de Rio Verde é:", "opts": ["o celetista.", "o contratual temporário.", "o Estatutário.", "o regime especial, previsto em convênio."], "ci": 2, "why": "O Plano de Cargos e Remuneração organiza os cargos de provimento efetivo em sistema de carreira, fundamentado nos princípios da qualificação profissional, valorização da função pública e aperfeiçoamento do servidor, e os cargos em comissão, de livre nomeação e exoneração.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q104", "src": "Apostila Vol. 1", "num": 104, "top": 29, "tema": "v1-19", "stem": "Segundo a Lei 7.435, considera-se cargo público:", "opts": ["aquele composto por um conjunto de atribuições e responsabilidades cometidas ao servidor, criado por lei, com denominação própria, número certo e pagamento pelo Erário Municipal.", "a posição do servidor na escala de remuneração, identificada por letra e algarismo arábico.", "o conjunto de categorias funcionais que se assemelham quanto à natureza do serviço.", "o conjunto de atribuições agrupadas pela espécie de atividade."], "ci": 0, "why": "As outras alternativas são, respectivamente, os conceitos de padrão, grupo e categoria funcional. A banca costuma trocar definições.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q105", "src": "Apostila Vol. 1", "num": 105, "top": 29, "tema": "v1-19", "stem": "Quanto aos conceitos do Plano de Cargos, o “padrão” é:", "opts": ["a posição do servidor na escala de remuneração do cargo, identificada por letra e algarismo arábico.", "o conjunto de categorias funcionais do mesmo cargo e da mesma remuneração.", "a atividade básica do quadro de pessoal, que individualiza o nível de conhecimento exigível e a remuneração do ocupante.", "o grau de instrução formal exigido para o desempenho das funções."], "ci": 0, "why": "Classe: conjunto de categorias funcionais do mesmo cargo e da mesma remuneração. Cargo: atividade básica do quadro de pessoal. Nível: graus de instrução formal.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q106", "src": "Apostila Vol. 1", "num": 106, "top": 29, "tema": "v1-19", "stem": "Os níveis de instrução formal considerados na organização dos Grupos Ocupacionais são:", "opts": ["básico (ensino fundamental), médio (ensino médio) e superior (curso superior ou técnico).", "básico (ensino médio), técnico e superior.", "fundamental, médio, técnico e superior, como quatro níveis.", "médio e superior, apenas."], "ci": 0, "why": "São três níveis. Detalhe: o nível superior abrange “formação em curso superior ou técnico”, conforme o texto da lei.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q107", "src": "Apostila Vol. 1", "num": 107, "top": 29, "tema": "v1-19", "stem": "As funções comissionadas dos grupos de Direção, Chefia e Assessoramento foram transformadas em cargos de provimento em comissão (DAS), que são graduados em:", "opts": ["3 (três) níveis.", "4 (quatro) níveis.", "5 (cinco) níveis.", "2 (dois) níveis."], "ci": 1, "why": "Os níveis e símbolos remuneratórios consideram, entre outros critérios, a complexidade das funções e o poder decisório, o grau de responsabilidade, o número de unidades e servidores subordinados e o volume de processos administrativos.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q108", "src": "Apostila Vol. 1", "num": 108, "top": 29, "tema": "v1-19", "stem": "O servidor efetivo ocupante de cargo de provimento em comissão poderá optar:", "opts": ["pela remuneração do cargo de origem acrescida de 50% do cargo em comissão.", "somente pela remuneração do cargo em comissão.", "pela remuneração do cargo de origem acrescida de 100% do cargo em comissão.", "pela remuneração integral do cargo em comissão ou pela remuneração do cargo de origem acrescida de 80% do cargo em comissão."], "ci": 3, "why": "Quem optar pela remuneração do seu cargo efetivo percebe a gratificação de representação pelo exercício do cargo comissionado. O número a lembrar é 80%.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q109", "src": "Apostila Vol. 1", "num": 109, "top": 29, "tema": "v1-19", "stem": "O ingresso nas categorias do Quadro Permanente dar-se-á:", "opts": ["no padrão inicial de cada cargo, mediante concurso público de provas e títulos, sendo o tempo de serviço prestado à Câmara computado como título nos termos do edital.", "em qualquer padrão, mediante concurso de provas.", "mediante processo seletivo simplificado e entrevista.", "no padrão intermediário, para quem tiver curso superior."], "ci": 0, "why": "Art. 13 (parte inicial). Fala-se em “provas e títulos”, e o tempo de serviço na Câmara vale como título.", "study": "Leis 7.434 e 7.435/2023, Aula 00 (art. 13)"}, {"id": "v1-q110", "src": "Apostila Vol. 1", "num": 110, "top": 29, "tema": "v1-19", "stem": "O desenvolvimento do servidor ocupante de cargo de provimento efetivo dá-se pela transferência de um padrão para o seguinte, no percentual de:", "opts": ["5%, por merecimento, a cada 2 anos.", "3%, somente por antiguidade, a cada 5 anos.", "3%, observados alternadamente os critérios de merecimento (avaliação de desempenho) e antiguidade (interstício de 3 anos).", "10%, alternadamente por merecimento e antiguidade, a cada 3 anos."], "ci": 2, "why": "Art. 13, § 1º. Duas vezes o número 3 (percentual e interstício). Alternadamente: um padrão por merecimento, outro por antiguidade.", "study": "Leis 7.434 e 7.435/2023, Aula 00 (art. 13, § 1º)"}, {"id": "v1-q111", "src": "Apostila Vol. 1", "num": 111, "top": 29, "tema": "v1-19", "stem": "Caberá à Mesa Diretora, juntamente com a Diretoria de Gestão de Pessoas:", "opts": ["aprovar a progressão funcional, por decisão sigilosa.", "julgar, em última instância, as contas dos servidores.", "definir o número de cargos de provimento efetivo, independentemente de lei.", "instituir programa permanente de treinamento e desenvolvimento, para elevar a capacitação nas tarefas executadas e preparar o servidor para funções de maior complexidade, incluídas as de direção, chefia e assessoramento."], "ci": 3, "why": "A Lei 7.435 coloca em duas autoridades (Mesa + Diretoria de Gestão de Pessoas) o dever de capacitar.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q112", "src": "Apostila Vol. 1", "num": 112, "top": 29, "tema": "v1-19", "stem": "Com a Lei 7.435, a nomenclatura do cargo efetivo de Secretária passa a ser Assistente Administrativo. Pelo mesmo comando, passam a existir:", "opts": ["Ouvidor (antes Vigia), Supervisor Administrativo (antes Telefonista) e Operador de Videomonitoramento (antes Agente Administrativo).", "Ouvidor (antes Agente Administrativo) e Supervisor Administrativo (antes Secretária).", "Operador de Videomonitoramento (antes Telefonista) e Ouvidor (antes Secretária).", "Ouvidor (antes Telefonista), Operador de Videomonitoramento (antes Vigia) e Supervisor Administrativo (antes Agente Administrativo)."], "ci": 3, "why": "Decore em pares: Secretária para Assistente Administrativo; Telefonista para Ouvidor; Vigia para Operador de Videomonitoramento; Agente Administrativo para Supervisor Administrativo. Além disso, o cargo em comissão de Procurador Adjunto passa a Assessor Jurídico da Procuradoria Geral.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q113", "src": "Apostila Vol. 1", "num": 113, "top": 29, "tema": "v1-19", "stem": "Os servidores que exercerem atribuições inerentes a outros cargos dos quais foram efetivados, por período superior a 5 anos consecutivos ou 10 anos intercalados:", "opts": ["são automaticamente reenquadrados, por ato da Mesa.", "adquirem o direito ao novo cargo, independentemente de lei.", "poderão ser reenquadrados, por lei específica, observados os requisitos e critérios nela regulamentados.", "somente podem ser reenquadrados em cargo de nível superior."], "ci": 2, "why": "Art. 17, § 3º. Cuidado com a inversão dos prazos: 5 consecutivos e 10 intercalados, não o contrário. Observação: o enunciado da Aula 00 do curso cita “LC 237/2021”, mas o dispositivo é da Lei 7.435/2023 (erro de digitação no material).", "study": "Leis 7.434 e 7.435/2023, Aula 00 (art. 17, § 3º)"}, {"id": "v1-q114", "src": "Apostila Vol. 1", "num": 114, "top": 29, "tema": "v1-19", "stem": "A carga horária dos servidores efetivos da Câmara será de:", "opts": ["6 horas diárias e 30 semanais, salvo o cargo de Ouvidor, que terá 8 horas.", "8 horas diárias e 44 semanais, para todos.", "8 horas diárias e 40 semanais, salvo o cargo de Ouvidor, que terá 6 horas diárias e 30 semanais.", "8 horas diárias e 40 semanais, sem exceções."], "ci": 2, "why": "A exceção é o Ouvidor (6 e 30). Lembre que o cargo de Ouvidor surgiu da antiga nomenclatura de Telefonista.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q115", "src": "Apostila Vol. 1", "num": 115, "top": 29, "tema": "v1-19", "stem": "Suspenderá o prazo de cumprimento do estágio probatório o servidor que ocupar cargo em comissão, bem como o gozo de licenças e afastamentos, exceto se:", "opts": ["o servidor tiver mais de 5 anos de casa.", "o servidor for cedido a outro órgão, com ônus para a Câmara.", "a função for compatível ou correlata com o cargo de origem, tiver exercido função comissionada de maior complexidade do seu cargo de origem (comprovado e justificado) ou for cedido ao Executivo, Fundação ou Autarquia, com ônus para o requisitante.", "o servidor ocupar cargo em comissão de qualquer natureza."], "ci": 2, "why": "O estágio probatório é suspenso como regra, e a lei lista três exceções. A cessão só mantém o estágio quando o ônus é do órgão requisitante.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q116", "src": "Apostila Vol. 1", "num": 116, "top": 29, "tema": "v1-19", "stem": "A Gratificação de Função, criada pela Lei 7.435, é:", "opts": ["atribuída por ato da Mesa, sem necessidade de justificativa, e integra a aposentadoria.", "destinada a quem ocupa cargo em comissão.", "atribuída por ato administrativo do Presidente da Câmara, com justificativa da real necessidade e descrição das atribuições, e não integra a remuneração para fins de aposentadoria.", "fixada em valor único, sem vínculo com o vencimento base."], "ci": 2, "why": "Os valores são equivalentes a percentuais sobre o vencimento base e compõem quadro único; destinam-se a remunerar encargos especiais de servidores efetivos com maiores responsabilidades, salvo detentores de cargo em comissão.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q117", "src": "Apostila Vol. 1", "num": 117, "top": 29, "tema": "v1-19", "stem": "Ao servidor é assegurado o direito de peticionar a revisão de seu enquadramento perante a Diretoria de Gestão de Pessoas, no prazo de:", "opts": ["15 dias, contados da nomeação.", "30 dias, contados da publicação do respectivo apostilamento.", "60 dias, contados da posse.", "5 dias úteis, contados da ciência."], "ci": 1, "why": "Da decisão da Diretoria cabe recurso à Presidência da Câmara em 30 dias, da ciência; à Mesa Diretora cabe recurso em última instância administrativa, também em 30 dias. O prazo é sempre de 30 dias, mas a autoridade muda.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v1-q118", "src": "Apostila Vol. 1", "num": 118, "top": 29, "tema": "v1-19", "stem": "As despesas decorrentes da Lei 7.435 correrão:", "opts": ["à conta do orçamento do Executivo, mediante convênio.", "à conta de receitas próprias da Câmara, vedada a utilização de créditos suplementares.", "à conta de fundo específico, instituído por decreto.", "à conta dos recursos consignados no Orçamento-Geral do Município nas rubricas destinadas à Câmara Municipal, obedecidos os preceitos da Lei Complementar nº 101/2000."], "ci": 3, "why": "Fecha a lei: a Mesa fica autorizada a baixar atos e normas complementares. Os direitos e vantagens (diárias, férias, licenças etc.) seguem a legislação pertinente.", "study": "Leis 7.434 e 7.435/2023, Aula 00"}, {"id": "v2-q001", "src": "Apostila Vol. 2", "num": 1, "top": 22, "tema": "v2-01", "stem": "A Mesa da Câmara é composta por:", "opts": ["Presidente, Vice-Presidente e Secretário, eleitos para uma sessão legislativa.", "Presidente, 1º e 2º Vice-Presidentes e Secretário, eleitos para duas sessões legislativas.", "Presidente, Vice-Presidente, 1º Secretário e 2º Secretário, eleitos para quatro sessões legislativas.", "Presidente, Vice-Presidente, 1º Secretário e 2º Secretário, eleitos para duas sessões legislativas."], "ci": 3, "why": "A Mesa é formada por quatro cargos e o mandato é de duas sessões legislativas. Para a 3ª e a 4ª sessão há nova eleição.", "study": "Regimento Interno, Aula 01 (Mesa)"}, {"id": "v2-q002", "src": "Apostila Vol. 2", "num": 2, "top": 22, "tema": "v2-01", "stem": "A eleição da Mesa é feita por:", "opts": ["maioria absoluta, em votação nominal e aberta.", "maioria simples, em votação secreta, por cédula.", "maioria de 2/3, em votação secreta.", "maioria simples, em votação aberta por aclamação."], "ci": 1, "why": "Voto secreto em cédula e maioria simples. Pegadinha: confundir com a destituição, que exige 2/3 e votação aberta.", "study": "Regimento Interno, Aula 01 (eleição da Mesa)"}, {"id": "v2-q003", "src": "Apostila Vol. 2", "num": 3, "top": 22, "tema": "v2-01", "stem": "Havendo empate na eleição da Mesa, vence a chapa:", "opts": ["cujo candidato a Presidente tenha mais mandatos.", "cujo candidato a Presidente seja o mais idoso.", "decidida por sorteio em plenário.", "indicada pelo Presidente em exercício."], "ci": 1, "why": "O critério de desempate é a idade do candidato a Presidente. Não há sorteio nem voto de qualidade.", "study": "Regimento Interno, Aula 01 (eleição da Mesa)"}, {"id": "v2-q004", "src": "Apostila Vol. 2", "num": 4, "top": 22, "tema": "v2-01", "stem": "A eleição da Mesa para a 3ª e a 4ª sessões legislativas deve ocorrer:", "opts": ["na primeira sessão ordinária de fevereiro da 3ª sessão legislativa.", "em sessão solene, em 1º de janeiro.", "em sessão extraordinária, entre 1º de outubro e 30 de dezembro.", "em sessão ordinária, a qualquer tempo da 2ª sessão legislativa."], "ci": 2, "why": "A janela é de 1º/10 a 30/12 do ano anterior ao início da 3ª sessão legislativa, em sessão extraordinária.", "study": "Regimento Interno, Aula 01 (eleição da Mesa)"}, {"id": "v2-q005", "src": "Apostila Vol. 2", "num": 5, "top": 22, "tema": "v2-02", "stem": "Cessam as funções da Mesa nas seguintes hipóteses, EXCETO:", "opts": ["morte de membro.", "renúncia apresentada por escrito.", "licença médica de qualquer de seus membros por até 30 dias.", "ordem judicial."], "ci": 2, "why": "Art. 7º: morte, posse da Mesa eleita no 3º período, renúncia escrita, destituição, perda de mandato e ordem judicial. Licença curta não está no rol.", "study": "Regimento Interno, Aula 01 (art. 7º)"}, {"id": "v2-q006", "src": "Apostila Vol. 2", "num": 6, "top": 22, "tema": "v2-02", "stem": "Surgindo vaga na Mesa, ela será preenchida em:", "opts": ["30 dias.", "15 dias.", "48 horas.", "60 dias."], "ci": 0, "why": "Prazo de 30 dias. Cuidado com o prazo de 48h, que aparece em outros procedimentos (convocação de suplente, Resolução de destituição).", "study": "Regimento Interno, Aula 01 (vagas na Mesa)"}, {"id": "v2-q007", "src": "Apostila Vol. 2", "num": 7, "top": 22, "tema": "v2-02", "stem": "Quanto à participação dos membros da Mesa nas comissões permanentes:", "opts": ["os membros da Mesa só podem integrar uma comissão permanente, e o Presidente não integra nenhuma.", "todos os membros da Mesa, inclusive o Presidente, integram uma comissão.", "a Mesa não pode integrar comissões, em nenhuma hipótese.", "os membros da Mesa integram até três comissões, como os demais Vereadores."], "ci": 0, "why": "Membros da Mesa: uma comissão permanente. Presidente: nenhuma. Os demais Vereadores têm o teto de três comissões.", "study": "Regimento Interno, Aula 01 (Mesa e comissões)"}, {"id": "v2-q008", "src": "Apostila Vol. 2", "num": 8, "top": 22, "tema": "v2-02", "stem": "Não havendo número legal para abrir a sessão, o Presidente deve:", "opts": ["abrir a sessão com qualquer número de presentes.", "aguardar 15 minutos e, persistindo a falta de quórum, não abrir a sessão.", "suspender a sessão por uma hora.", "convocar sessão extraordinária para o mesmo dia."], "ci": 1, "why": "Aguarda-se 15 minutos (segunda chamada). Persistindo a ausência de quórum, a sessão não se realiza.", "study": "Regimento Interno, Aula 01 / Regimento Interno, Aula 02 (abertura de sessões)"}, {"id": "v2-q009", "src": "Apostila Vol. 2", "num": 9, "top": 22, "tema": "v2-03", "stem": "Sobre o voto do Presidente da Câmara:", "opts": ["vota sempre, como qualquer Vereador.", "nunca vota, em hipótese alguma.", "só vota nos casos regimentais, e não tem voto em todas as deliberações.", "vota apenas para desempatar, em qualquer matéria."], "ci": 2, "why": "O Presidente só vota nos casos previstos no Regimento. Pegadinha: “voto de qualidade em qualquer empate”.", "study": "Regimento Interno, Aula 01 (competências do Presidente)"}, {"id": "v2-q010", "src": "Apostila Vol. 2", "num": 10, "top": 22, "tema": "v2-03", "stem": "Compete ao Presidente da Câmara promulgar:", "opts": ["somente leis sancionadas tacitamente.", "resoluções, decretos legislativos e leis cujo veto tenha sido rejeitado.", "apenas resoluções, ficando os decretos legislativos a cargo da Mesa.", "leis de iniciativa do Prefeito sancionadas por este."], "ci": 1, "why": "O Presidente promulga resoluções, decretos legislativos e as leis de veto rejeitado (ou mantidas as condições legais de promulgação). Lei sancionada pelo Prefeito é por ele promulgada.", "study": "Regimento Interno, Aula 01 (arts. 15 e 16)"}, {"id": "v2-q011", "src": "Apostila Vol. 2", "num": 11, "top": 22, "tema": "v2-03", "stem": "A resenha dos trabalhos do ano deve ser apresentada pelo Presidente:", "opts": ["na primeira sessão ordinária do ano seguinte.", "em sessão solene de encerramento, em dezembro.", "por escrito, no recesso de julho.", "na última sessão ordinária do ano."], "ci": 3, "why": "A resenha é feita na última sessão ordinária do ano.", "study": "Regimento Interno, Aula 01 (art. 16)"}, {"id": "v2-q012", "src": "Apostila Vol. 2", "num": 12, "top": 22, "tema": "v2-03", "stem": "Quando o Presidente pretender agir juridicamente em nome da Câmara em situação para a qual não haja autorização regimental, ele deve:", "opts": ["consultar o Plenário.", "agir de ofício, comunicando depois a Mesa.", "pedir parecer da Comissão de Ética.", "convocar sessão extraordinária da Comissão Processante."], "ci": 0, "why": "O parágrafo único do art. 16 exige a consulta ao Plenário. As certidões requeridas, por sua vez, devem ser expedidas em 15 dias.", "study": "Regimento Interno, Aula 01 (art. 16, parágrafo único)"}, {"id": "v2-q013", "src": "Apostila Vol. 2", "num": 13, "top": 22, "tema": "v2-04", "stem": "São atribuições do 1º Secretário, entre outras:", "opts": ["presidir as sessões na ausência do Vice-Presidente.", "promulgar as leis de veto rejeitado.", "convocar as sessões especiais.", "ler os papéis do expediente, receber e guardar as proposições e redigir as atas."], "ci": 3, "why": "Art. 25: ler papéis, receber e guardar proposições e redigir atas. Promulgar e convocar são do Presidente.", "study": "Regimento Interno, Aula 01 (art. 25)"}, {"id": "v2-q014", "src": "Apostila Vol. 2", "num": 14, "top": 22, "tema": "v2-04", "stem": "A renúncia de membro da Mesa:", "opts": ["é feita por ofício e só se torna efetiva com a leitura em sessão.", "é verbal e produz efeito imediato.", "precisa ser aprovada por maioria absoluta do Plenário.", "só é admitida no último ano do mandato da Mesa."], "ci": 0, "why": "Art. 27: renúncia por ofício (escrita), efetiva na leitura em sessão. Não precisa de aprovação.", "study": "Regimento Interno, Aula 01 (art. 27)"}, {"id": "v2-q015", "src": "Apostila Vol. 2", "num": 15, "top": 22, "tema": "v2-04", "stem": "A destituição de membro da Mesa exige:", "opts": ["maioria simples, sem necessidade de defesa.", "maioria absoluta, em votação secreta.", "unanimidade da Comissão Processante.", "voto de 2/3 dos Vereadores, assegurada ampla defesa."], "ci": 3, "why": "Art. 28: 2/3 e ampla defesa. Quórum de 2/3 em Câmara de 21 Vereadores: 14.", "study": "Regimento Interno, Aula 01 (art. 28)"}, {"id": "v2-q016", "src": "Apostila Vol. 2", "num": 16, "top": 22, "tema": "v2-04", "stem": "A representação contra membro da Mesa, para fins de destituição, deve ser recebida por:", "opts": ["maioria simples, com Comissão de 5 Vereadores indicados pelo Presidente.", "2/3, com Comissão de 3 Vereadores eleitos.", "maioria absoluta, com Comissão de 5 Vereadores sorteados.", "maioria absoluta, constituindo-se uma Comissão Processante de 3 Vereadores sorteados."], "ci": 3, "why": "Art. 29: recebimento por maioria absoluta e Comissão Processante de 3 sorteados. Os 2/3 só entram na decisão final.", "study": "Regimento Interno, Aula 01 (art. 29)"}, {"id": "v2-q017", "src": "Apostila Vol. 2", "num": 17, "top": 22, "tema": "v2-04", "stem": "Constituída a Comissão Processante, ela se reúne em ___, notifica o acusado em ___ e este tem ___ para defesa prévia. Assinale a alternativa que completa a frase corretamente.", "opts": ["24 horas; 5 dias; 10 dias.", "48 horas; 3 dias; 5 dias.", "72 horas; 10 dias; 15 dias.", "48 horas; 3 dias; 10 dias."], "ci": 3, "why": "Reunião em 48h, notificação em 3 dias, defesa prévia em 10 dias. O parecer vem em 20 dias improrrogáveis.", "study": "Regimento Interno, Aula 01 (art. 29)"}, {"id": "v2-q018", "src": "Apostila Vol. 2", "num": 18, "top": 22, "tema": "v2-04", "stem": "O parecer da Comissão Processante deve ser apresentado em:", "opts": ["10 dias, prorrogáveis por igual período.", "60 dias, prorrogáveis.", "20 dias, prazo improrrogável.", "5 dias, improrrogáveis."], "ci": 2, "why": "20 dias improrrogáveis. Cuidado: a Comissão de Ética tem 60 dias prorrogáveis; a de Inquérito, 5 dias para parecer em fase específica.", "study": "Regimento Interno, Aula 01 (art. 29)"}, {"id": "v2-q019", "src": "Apostila Vol. 2", "num": 19, "top": 22, "tema": "v2-04", "stem": "Sendo o parecer da Comissão Processante pela improcedência da representação:", "opts": ["ele exige 2/3 para ser aprovado.", "ele é arquivado sem votação.", "ele é aprovado por maioria simples, em votação aberta.", "ele só vale com a concordância do acusado."], "ci": 2, "why": "A improcedência é votada por maioria simples. Já a destituição exige 2/3. Votação sempre aberta nesse procedimento.", "study": "Regimento Interno, Aula 01 (arts. 30 a 35)"}, {"id": "v2-q020", "src": "Apostila Vol. 2", "num": 20, "top": 22, "tema": "v2-04", "stem": "No julgamento da destituição, cada Vereador dispõe de ___ para discutir, e o relator e o acusado, de ___ cada um. Assinale a alternativa correta.", "opts": ["10 minutos; 30 minutos.", "20 minutos; 30 minutos.", "20 minutos; 60 minutos.", "5 minutos; 60 minutos."], "ci": 2, "why": "20 min por Vereador e 60 min para relator e acusado. Aprovada a destituição, a Resolução é promulgada em 48h.", "study": "Regimento Interno, Aula 01 (arts. 30 a 35)"}, {"id": "v2-q021", "src": "Apostila Vol. 2", "num": 21, "top": 22, "tema": "v2-05", "stem": "Cada comissão permanente é composta por três membros, que ocupam as funções de:", "opts": ["Presidente, Vice-Presidente e Secretário.", "Presidente, Relator e Vogal.", "Presidente, Relator e Suplente.", "Coordenador, Relator e Vogal."], "ci": 1, "why": "Art. 38: Presidente, Relator e Vogal.", "study": "Regimento Interno, Aula 01 (art. 38)"}, {"id": "v2-q022", "src": "Apostila Vol. 2", "num": 22, "top": 22, "tema": "v2-05", "stem": "Cada Vereador pode integrar, no máximo, quantas comissões permanentes?", "opts": ["Duas.", "Quatro.", "Uma, salvo o Presidente da Câmara.", "Três."], "ci": 3, "why": "Teto de três comissões por Vereador. Os membros da Mesa ficam em apenas uma; o Presidente, em nenhuma.", "study": "Regimento Interno, Aula 01 (art. 38)"}, {"id": "v2-q023", "src": "Apostila Vol. 2", "num": 23, "top": 22, "tema": "v2-05", "stem": "As comissões permanentes são constituídas:", "opts": ["em sessão solene, em janeiro, com voto secreto.", "na primeira sessão ordinária de cada sessão legislativa, com voto secreto.", "na primeira sessão ordinária da 1ª e da 3ª sessões legislativas, com votação aberta por cédula.", "por indicação do Presidente, sem votação, a cada sessão legislativa."], "ci": 2, "why": "Constituição na 1ª e na 3ª sessões (começo de cada biênio), em votação aberta por cédula. O mandato dura até o fim da sessão legislativa.", "study": "Regimento Interno, Aula 01 (art. 38)"}, {"id": "v2-q024", "src": "Apostila Vol. 2", "num": 24, "top": 22, "tema": "v2-05", "stem": "O número de comissões permanentes varia conforme a versão do Regimento: o material do curso (Resolução 01/2026) lista 15, e o site da Câmara, consolidado até a Resolução 05/2026, indica 16. Diante disso, em prova o candidato deve:", "opts": ["seguir a versão do Regimento citada no enunciado e, na dúvida, o texto do próprio enunciado.", "decorar apenas 15, por ser o número do curso.", "decorar apenas 16, por ser a versão mais recente.", "considerar a questão nula, pois a divergência impede o gabarito."], "ci": 0, "why": "Questão de estratégia, não de decoreba: o número muda com as resoluções que alteram o Regimento. O que vale é a versão adotada pela banca.", "study": "Regimento Interno, Aula 01 (art. 38) e site da Câmara"}, {"id": "v2-q025", "src": "Apostila Vol. 2", "num": 25, "top": 22, "tema": "v2-06", "stem": "A Comissão de Ética tem como característica:", "opts": ["a denúncia pode ser feita por qualquer cidadão, sem subscrição.", "a notificação do acusado é feita em 10 dias.", "o prazo de conclusão é de 20 dias improrrogáveis.", "a denúncia deve ser subscrita por 1/3 dos Vereadores, com notificação do acusado em 72 horas."], "ci": 3, "why": "Denúncia por 1/3; notificação em 72h; defesa em 10 dias; conclusão em 60 dias prorrogáveis por igual período.", "study": "Regimento Interno, Aula 01 (arts. 47 e 48)"}, {"id": "v2-q026", "src": "Apostila Vol. 2", "num": 26, "top": 22, "tema": "v2-06", "stem": "No processo na Comissão de Ética, a cassação do mandato exige ___ e a absolvição, ___ . Assinale a alternativa correta.", "opts": ["maioria absoluta; 2/3.", "2/3; maioria simples.", "2/3; maioria absoluta.", "maioria simples; maioria simples."], "ci": 2, "why": "Cassação: 2/3 (14 votos). Absolvição: maioria absoluta (11 votos).", "study": "Regimento Interno, Aula 01 (art. 48)"}, {"id": "v2-q027", "src": "Apostila Vol. 2", "num": 27, "top": 22, "tema": "v2-06", "stem": "O prazo da Comissão de Ética para concluir o processo é de:", "opts": ["20 dias improrrogáveis.", "30 dias, prorrogáveis por 15.", "90 dias improrrogáveis.", "60 dias, prorrogáveis por igual período."], "ci": 3, "why": "60 dias, prorrogáveis por igual período, ou seja, até 120 dias.", "study": "Regimento Interno, Aula 01 (art. 48)"}, {"id": "v2-q028", "src": "Apostila Vol. 2", "num": 28, "top": 22, "tema": "v2-06", "stem": "Na Comissão de Ética, o acusado deve ser notificado em:", "opts": ["48 horas.", "24 horas.", "10 dias.", "72 horas."], "ci": 3, "why": "Notificação em 72h; depois, defesa em 10 dias. Cuidado com a Processante da Mesa (reunião em 48h, notificação em 3 dias).", "study": "Regimento Interno, Aula 01 (arts. 47 e 48)"}, {"id": "v2-q029", "src": "Apostila Vol. 2", "num": 29, "top": 22, "tema": "v2-06", "stem": "Parecer da CFJR pela inconstitucionalidade de projeto:", "opts": ["arquiva o projeto automaticamente.", "é devolvido ao autor, sem apreciação do plenário.", "vai ao plenário, em discussão e votação única.", "depende da concordância da Comissão de Ética."], "ci": 2, "why": "O parecer pela inconstitucionalidade é submetido ao plenário em discussão e votação única. Se rejeitado, o projeto segue.", "study": "Regimento Interno, Aula 01 (pareceres)"}, {"id": "v2-q030", "src": "Apostila Vol. 2", "num": 30, "top": 22, "tema": "v2-07", "stem": "O parecer de comissão é estruturado em:", "opts": ["duas partes: relatório e voto.", "quatro partes: relatório, voto, emenda e redação.", "três partes.", "uma única peça, sem divisão."], "ci": 2, "why": "Art. 66: parecer em três partes (relatório, voto do relator e decisão da comissão).", "study": "Regimento Interno, Aula 01 (art. 66)"}, {"id": "v2-q031", "src": "Apostila Vol. 2", "num": 31, "top": 22, "tema": "v2-07", "stem": "O pedido de vista de projeto na comissão suspende o processo por até:", "opts": ["48 horas, e a suspensão total não pode passar de 10 dias.", "5 dias, uma única vez.", "24 horas, e a suspensão total não pode passar de 6 dias corridos.", "3 dias úteis, sem limite de pedidos."], "ci": 2, "why": "Vista de 24h, com limite de 6 dias corridos de suspensão. O relator tem 2 dias para emitir seu parecer.", "study": "Regimento Interno, Aula 01 (prazos nas comissões)"}, {"id": "v2-q032", "src": "Apostila Vol. 2", "num": 32, "top": 22, "tema": "v2-07", "stem": "O voto em separado, no parecer, pode ser:", "opts": ["somente contrário.", "somente aditivo ou contrário.", "pelas conclusões ou pela rejeição liminar.", "pelas conclusões, aditivo ou contrário."], "ci": 3, "why": "Art. 69: voto em separado pelas conclusões, aditivo ou contrário.", "study": "Regimento Interno, Aula 01 (art. 69)"}, {"id": "v2-q033", "src": "Apostila Vol. 2", "num": 33, "top": 22, "tema": "v2-07", "stem": "O prazo do relator para emitir o parecer é de:", "opts": ["5 dias.", "2 dias.", "10 dias.", "24 horas."], "ci": 1, "why": "Dois dias. Pegadinha clássica: misturar prazos de comissão (2 dias, vista de 24h) com prazos de processos especiais (10, 20, 60 dias).", "study": "Regimento Interno, Aula 01 (prazos nas comissões)"}, {"id": "v2-q034", "src": "Apostila Vol. 2", "num": 34, "top": 22, "tema": "v2-07", "stem": "NÃO é modalidade de voto em separado:", "opts": ["pelas conclusões.", "pela rejeição liminar.", "aditivo.", "contrário."], "ci": 1, "why": "As três modalidades do art. 69 são: pelas conclusões, aditivo e contrário.", "study": "Regimento Interno, Aula 01 (art. 69)"}, {"id": "v2-q035", "src": "Apostila Vol. 2", "num": 35, "top": 22, "tema": "v2-08", "stem": "A criação de Comissão Especial depende de requerimento:", "opts": ["subscrito por 1/3 dos Vereadores e aprovado por maioria simples.", "subscrito por 2/3 e aprovado por maioria absoluta.", "subscrito por qualquer Vereador e aprovado por maioria simples.", "subscrito pela Mesa e aprovado por unanimidade."], "ci": 0, "why": "1/3 para subscrever e maioria simples para aprovar. O requerimento indica a finalidade, o número de membros e o prazo.", "study": "Regimento Interno, Aula 01 (arts. 72 a 75)"}, {"id": "v2-q036", "src": "Apostila Vol. 2", "num": 36, "top": 22, "tema": "v2-08", "stem": "A Comissão Especial NÃO pode:", "opts": ["tratar de matéria de competência de comissão permanente.", "ter prazo determinado.", "ser extinta ao fim do prazo.", "ter finalidade definida em requerimento."], "ci": 0, "why": "Matéria de comissão permanente não pode ser tratada por comissão especial. Se a especial não concluir no prazo, é extinta.", "study": "Regimento Interno, Aula 01 (arts. 72 a 75)"}, {"id": "v2-q037", "src": "Apostila Vol. 2", "num": 37, "top": 22, "tema": "v2-08", "stem": "A Comissão de Inquérito tem por finalidade:", "opts": ["apenas fiscalizar contratos do Executivo.", "julgar a prestação de contas do Prefeito.", "examinar a redação final dos projetos.", "processar o Prefeito e os Vereadores por infrações do Decreto-Lei 201/67."], "ci": 3, "why": "Art. 76: processar Prefeito e Vereadores por infrações previstas no Decreto-Lei 201/67.", "study": "Regimento Interno, Aula 01 (art. 76)"}, {"id": "v2-q038", "src": "Apostila Vol. 2", "num": 38, "top": 22, "tema": "v2-08", "stem": "A Comissão de Inquérito é composta por:", "opts": ["5 Vereadores.", "3 Vereadores sorteados.", "7 Vereadores indicados pelo Presidente.", "todos os membros da CFJR."], "ci": 0, "why": "Cinco Vereadores. A Processante da Mesa, por sua vez, tem três sorteados.", "study": "Regimento Interno, Aula 01 (art. 76)"}, {"id": "v2-q039", "src": "Apostila Vol. 2", "num": 39, "top": 22, "tema": "v2-08", "stem": "No processo da Comissão de Inquérito, o acusado tem:", "opts": ["5 dias de defesa e até 3 testemunhas.", "30 dias de defesa, sem limite de testemunhas.", "10 dias de defesa e pode arrolar até 10 testemunhas.", "10 dias de defesa, sem direito a testemunhas."], "ci": 2, "why": "Defesa em 10 dias, com até 10 testemunhas. A cassação exige 2/3, em votação nominal por infração.", "study": "Regimento Interno, Aula 01 (art. 76)"}, {"id": "v2-q040", "src": "Apostila Vol. 2", "num": 40, "top": 6, "tema": "v2-09", "stem": "Em uma Câmara de 21 Vereadores, maioria absoluta e 2/3 equivalem, respectivamente, a:", "opts": ["10 e 14 Vereadores.", "11 e 14 Vereadores.", "11 e 15 Vereadores.", "12 e 14 Vereadores."], "ci": 1, "why": "Maioria absoluta é o primeiro número inteiro acima da metade de 21 (10,5), ou seja, 11. Dois terços de 21 = 14.", "study": "Regimento Interno, Aula 02 (arts. 82 a 86)"}, {"id": "v2-q041", "src": "Apostila Vol. 2", "num": 41, "top": 6, "tema": "v2-09", "stem": "Maioria simples é a maioria:", "opts": ["dos membros da Câmara, presentes ou não.", "de 2/3 dos presentes.", "dos Vereadores presentes à sessão.", "do maior número de votos, ainda que inferior à metade."], "ci": 2, "why": "Simples = maioria dos presentes. Absoluta = maioria dos membros. Relativa = maior número de votos entre as alternativas.", "study": "Regimento Interno, Aula 02 (art. 82)"}, {"id": "v2-q042", "src": "Apostila Vol. 2", "num": 42, "top": 6, "tema": "v2-09", "stem": "Maioria relativa é a:", "opts": ["obtida por quem recebe mais votos que os demais concorrentes.", "obtida com metade dos presentes mais um.", "exigida para aprovar emenda à Lei Orgânica.", "obtida com 2/3 dos membros."], "ci": 0, "why": "É o simples “mais votado”, usada em escolhas entre várias alternativas.", "study": "Regimento Interno, Aula 02 (art. 82)"}, {"id": "v2-q043", "src": "Apostila Vol. 2", "num": 43, "top": 6, "tema": "v2-09", "stem": "O art. 86 do Regimento trata:", "opts": ["das competências da Câmara com e sem sanção do Prefeito.", "da perda de mandato de Vereador.", "das licenças de Vereador.", "do funcionamento das sessões extraordinárias."], "ci": 0, "why": "Art. 86: competências com sanção (leis) e sem sanção (resoluções e decretos legislativos).", "study": "Regimento Interno, Aula 02 (art. 86)"}, {"id": "v2-q044", "src": "Apostila Vol. 2", "num": 44, "top": 6, "tema": "v2-10", "stem": "A posse do Vereador exige:", "opts": ["certidão negativa de débitos tributários.", "declaração de bens.", "aprovação do Plenário.", "comparecimento a três sessões consecutivas."], "ci": 1, "why": "Na posse, o Vereador apresenta declaração de bens. Os deveres do Vereador estão no art. 88.", "study": "Regimento Interno, Aula 02 (posse e deveres)"}, {"id": "v2-q045", "src": "Apostila Vol. 2", "num": 45, "top": 6, "tema": "v2-10", "stem": "A licença do Vereador para tratamento de saúde, missão ou cargo (art. 92):", "opts": ["só se efetiva com a leitura em sessão, e o suplente é convocado se a licença superar 120 dias.", "é automática, sem necessidade de leitura em sessão.", "permite convocação de suplente desde o primeiro dia.", "depende de aprovação de 2/3 do Plenário."], "ci": 0, "why": "Efetiva com a leitura em sessão. Suplente só após 120 dias, e a convocação ocorre em 48h.", "study": "Regimento Interno, Aula 02 (art. 92)"}, {"id": "v2-q046", "src": "Apostila Vol. 2", "num": 46, "top": 6, "tema": "v2-10", "stem": "O suplente convocado deve tomar posse em:", "opts": ["15 dias.", "48 horas.", "5 dias.", "30 dias."], "ci": 1, "why": "Convocação do suplente em 48h. Pegadinha: confundir com os 30 dias para preenchimento de vaga na Mesa.", "study": "Regimento Interno, Aula 02 (art. 92)"}, {"id": "v2-q047", "src": "Apostila Vol. 2", "num": 47, "top": 6, "tema": "v2-10", "stem": "Para justificar faltas por óbito de parente, o Vereador tem direito a:", "opts": ["3 dias.", "8 dias.", "1 dia.", "15 dias."], "ci": 0, "why": "Três dias por óbito, mediante documento. Faltas justificadas exigem documentos.", "study": "Regimento Interno, Aula 02 (faltas)"}, {"id": "v2-q048", "src": "Apostila Vol. 2", "num": 48, "top": 6, "tema": "v2-10", "stem": "É vedado ao Vereador, entre outras proibições:", "opts": ["comparecer às sessões da Comissão de Ética.", "firmar ou manter contrato com a Câmara, ressalvado o de cláusulas uniformes.", "apresentar projetos de lei.", "falar na tribuna durante o Expediente."], "ci": 1, "why": "Vedações constam do texto constitucional, da Lei Orgânica e do Regimento. A vedação a contratos com o Poder Público é a clássica.", "study": "Regimento Interno, Aula 02 (vedações)"}, {"id": "v2-q049", "src": "Apostila Vol. 2", "num": 49, "top": 6, "tema": "v2-11", "stem": "Ocorre vaga no cargo de Vereador por:", "opts": ["licença para tratamento de saúde.", "morte, renúncia ou perda do mandato.", "falta justificada.", "afastamento para missão oficial."], "ci": 1, "why": "Art. 105: vaga por morte, renúncia ou perda de mandato. Licenças não geram vaga.", "study": "Regimento Interno, Aula 02 (art. 105)"}, {"id": "v2-q050", "src": "Apostila Vol. 2", "num": 50, "top": 6, "tema": "v2-11", "stem": "A decisão de cassação do mandato de Vereador, nos casos do art. 107, exige:", "opts": ["maioria absoluta dos presentes.", "maioria simples dos presentes.", "unanimidade.", "voto de 2/3 dos membros da Câmara."], "ci": 3, "why": "Cassação: 2/3 (14 votos) dos membros da Câmara. O art. 107 elenca sete hipóteses de perda de mandato.", "study": "Regimento Interno, Aula 02 (arts. 107 a 112)"}, {"id": "v2-q051", "src": "Apostila Vol. 2", "num": 51, "top": 6, "tema": "v2-11", "stem": "A remuneração dos Vereadores é fixada:", "opts": ["por lei de iniciativa do Prefeito.", "por decreto do Presidente da Câmara, em qualquer época.", "por resolução, até 30 dias antes das eleições.", "por resolução, até 30 dias depois das eleições."], "ci": 2, "why": "Resolução da Câmara aprovada até 30 dias antes do pleito, para vigorar na legislatura seguinte.", "study": "Regimento Interno, Aula 02 (remuneração)"}, {"id": "v2-q052", "src": "Apostila Vol. 2", "num": 52, "top": 6, "tema": "v2-11", "stem": "Os líderes de bancada são indicados:", "opts": ["no início de cada sessão ordinária.", "após 120 dias de sessão legislativa.", "no início da sessão legislativa.", "pelo Prefeito, em cada legislatura."], "ci": 2, "why": "A indicação dos líderes ocorre no início da sessão legislativa.", "study": "Regimento Interno, Aula 02 (líderes)"}, {"id": "v2-q053", "src": "Apostila Vol. 2", "num": 53, "top": 22, "tema": "v2-12", "stem": "A duração normal das sessões da Câmara é de:", "opts": ["três horas, com segunda chamada em 30 minutos.", "duas horas, com segunda chamada em 15 minutos.", "quatro horas, sem segunda chamada.", "duas horas, sem possibilidade de prorrogação."], "ci": 1, "why": "Duas horas. Segunda chamada em 15 minutos.", "study": "Regimento Interno, Aula 02 (art. 113)"}, {"id": "v2-q054", "src": "Apostila Vol. 2", "num": 54, "top": 22, "tema": "v2-12", "stem": "O requerimento de prorrogação da sessão deve ser apresentado:", "opts": ["a qualquer momento, sem limite de duração.", "antes do início da sessão, por escrito.", "até 10 minutos antes do término, e a prorrogação não pode passar de 24 horas.", "até 5 minutos antes do término, pelo prazo máximo de 2 horas."], "ci": 2, "why": "Pedido de prorrogação 10 minutos antes do fim. A prorrogação não passa de 24h.", "study": "Regimento Interno, Aula 02 (prorrogação)"}, {"id": "v2-q055", "src": "Apostila Vol. 2", "num": 55, "top": 22, "tema": "v2-12", "stem": "A suspensão da sessão para parecer dura até ___ e, para reunião de bancada, até ___ . Assinale a alternativa correta.", "opts": ["5 minutos; 15 minutos.", "15 minutos; 5 minutos.", "30 minutos; 10 minutos.", "10 minutos; 10 minutos."], "ci": 1, "why": "Suspensão para parecer: 15 min. Para reunião de bancada: 5 min.", "study": "Regimento Interno, Aula 02 (arts. 117 a 119)"}, {"id": "v2-q056", "src": "Apostila Vol. 2", "num": 56, "top": 22, "tema": "v2-12", "stem": "As sessões da Câmara são, em regra:", "opts": ["reservadas, com acesso mediante credencial.", "públicas, sem exceção.", "secretas, quando o Presidente assim decidir.", "públicas, admitindo sessão secreta por deliberação da maioria absoluta."], "ci": 3, "why": "A regra é a publicidade. O sigilo depende de deliberação da maioria absoluta.", "study": "Regimento Interno, Aula 02 (art. 113)"}, {"id": "v2-q057", "src": "Apostila Vol. 2", "num": 57, "top": 22, "tema": "v2-12", "stem": "São espécies de sessão previstas no art. 113:", "opts": ["solenes, ordinárias e administrativas.", "solenes, ordinárias e extraordinárias.", "ordinárias, extraordinárias e permanentes.", "especiais, permanentes e extraordinárias."], "ci": 1, "why": "Solenes, ordinárias e extraordinárias. Há ainda sessões especiais e secretas, tratadas em seções próprias.", "study": "Regimento Interno, Aula 02 (art. 113)"}, {"id": "v2-q058", "src": "Apostila Vol. 2", "num": 58, "top": 22, "tema": "v2-13", "stem": "As sessões ordinárias realizam-se:", "opts": ["todas as quintas-feiras, às 14h, sem recesso.", "na última semana útil do mês, às 19h, com recesso em dezembro.", "todos os dias úteis, às 19h, exceto em fevereiro.", "na primeira semana útil de cada mês, de segunda a sexta, às 19h, com recesso em janeiro e julho."], "ci": 3, "why": "Primeira semana útil do mês, seg–sex, 19h. Recesso em janeiro e julho. Exigem maioria absoluta para abrir e prosseguir.", "study": "Regimento Interno, Aula 02 (arts. 125 a 129)"}, {"id": "v2-q059", "src": "Apostila Vol. 2", "num": 59, "top": 22, "tema": "v2-13", "stem": "A sequência da sessão ordinária é:", "opts": ["Ordem do Dia, Expediente e Assuntos Parlamentares.", "Expediente, Ordem do Dia e Assuntos Parlamentares.", "Assuntos Parlamentares, Expediente e Ordem do Dia.", "Expediente, Assuntos Parlamentares e Ordem do Dia."], "ci": 1, "why": "Expediente, Ordem do Dia e, ao final, Assuntos Parlamentares.", "study": "Regimento Interno, Aula 02 (art. 125)"}, {"id": "v2-q060", "src": "Apostila Vol. 2", "num": 60, "top": 22, "tema": "v2-13", "stem": "A ordem de matérias na Ordem do Dia é:", "opts": ["vetos, redação final, 2ª discussão, 1ª discussão e moções, requerimentos e recursos.", "1ª discussão, 2ª discussão, redação final, vetos e requerimentos.", "requerimentos, vetos, redação final, 1ª discussão e 2ª discussão.", "redação final, vetos, 1ª discussão, 2ª discussão e recursos."], "ci": 0, "why": "A sequência, em regra: vetos, redação final, 2ª discussão, 1ª discussão, moções, requerimentos e recursos.", "study": "Regimento Interno, Aula 02 (arts. 133 a 138)"}, {"id": "v2-q061", "src": "Apostila Vol. 2", "num": 61, "top": 22, "tema": "v2-13", "stem": "Dentro de cada fase da Ordem do Dia, a precedência entre as espécies de proposição é:", "opts": ["Projeto de Decreto Legislativo, Projeto de Resolução e Projeto de Lei.", "Projeto de Resolução, Projeto de Lei e Projeto de Decreto Legislativo.", "Projeto de Lei, Projeto de Decreto Legislativo e Projeto de Resolução.", "Projeto de Lei, Projeto de Resolução e Projeto de Decreto Legislativo."], "ci": 3, "why": "PL → PR → PDL.", "study": "Regimento Interno, Aula 02 (arts. 133 a 138)"}, {"id": "v2-q062", "src": "Apostila Vol. 2", "num": 62, "top": 22, "tema": "v2-13", "stem": "A alteração da Ordem do Dia só é admitida nas hipóteses do art. 135, que são em número de:", "opts": ["cinco.", "três.", "sete.", "dez."], "ci": 0, "why": "O art. 135 traz cinco hipóteses taxativas.", "study": "Regimento Interno, Aula 02 (art. 135)"}, {"id": "v2-q063", "src": "Apostila Vol. 2", "num": 63, "top": 22, "tema": "v2-13", "stem": "A ordem dos itens do Expediente (art. 129) é:", "opts": ["livre, a critério do Presidente.", "definida por votação a cada sessão.", "taxativa, não podendo ser alterada pelo Presidente.", "exemplificativa, podendo ser invertida pela maioria."], "ci": 2, "why": "A ordem do Expediente é taxativa.", "study": "Regimento Interno, Aula 02 (art. 129)"}, {"id": "v2-q064", "src": "Apostila Vol. 2", "num": 64, "top": 22, "tema": "v2-14", "stem": "Para que haja Assuntos Parlamentares, exige-se a presença de, no mínimo, ___ dos Vereadores, o que equivale a ___ Vereadores. Assinale a alternativa correta.", "opts": ["1/3; 7.", "1/2; 11.", "2/3; 14.", "1/3; 8."], "ci": 0, "why": "1/3 de 21 = 7 Vereadores presentes.", "study": "Regimento Interno, Aula 02 (arts. 143 a 146)"}, {"id": "v2-q065", "src": "Apostila Vol. 2", "num": 65, "top": 22, "tema": "v2-14", "stem": "No uso da palavra em Assuntos Parlamentares:", "opts": ["cada orador tem 15 minutos e são admitidos um aparte da situação e um da oposição.", "cada orador tem 5 minutos, com apartes ilimitados.", "cada orador tem 30 minutos, sem apartes.", "o tempo pode ser prorrogado pelo Presidente."], "ci": 0, "why": "15 minutos, com um aparte da situação e um da oposição. Não há prorrogação.", "study": "Regimento Interno, Aula 02 (arts. 143 a 146)"}, {"id": "v2-q066", "src": "Apostila Vol. 2", "num": 66, "top": 22, "tema": "v2-14", "stem": "A inscrição para Assuntos Parlamentares deve ser feita:", "opts": ["até o término da Ordem do Dia.", "com 24 horas de antecedência.", "antes do fim do Expediente.", "a qualquer momento da sessão."], "ci": 2, "why": "A inscrição fecha ao término do Expediente.", "study": "Regimento Interno, Aula 02 (arts. 143 a 146)"}, {"id": "v2-q067", "src": "Apostila Vol. 2", "num": 67, "top": 22, "tema": "v2-15", "stem": "A sessão extraordinária pode ser convocada:", "opts": ["apenas pelo Presidente.", "pela Mesa, por 1/3 dos Vereadores ou pelo Prefeito.", "apenas pelo Prefeito.", "por qualquer Vereador."], "ci": 1, "why": "Mesa, 1/3 dos Vereadores ou Prefeito.", "study": "Regimento Interno, Aula 02 (arts. 147 a 155)"}, {"id": "v2-q068", "src": "Apostila Vol. 2", "num": 68, "top": 22, "tema": "v2-15", "stem": "A convocação da sessão extraordinária deve ser feita com antecedência mínima de:", "opts": ["3 dias, salvo extrema urgência.", "24 horas, sempre.", "5 dias, sem exceção.", "48 horas, salvo recesso."], "ci": 0, "why": "Três dias. Em extrema urgência admite-se prazo menor. A convocação deve indicar dia, hora e Ordem do Dia.", "study": "Regimento Interno, Aula 02 (arts. 147 a 155)"}, {"id": "v2-q069", "src": "Apostila Vol. 2", "num": 69, "top": 22, "tema": "v2-15", "stem": "Na sessão extraordinária:", "opts": ["há Expediente, Ordem do Dia e Assuntos Parlamentares.", "há Expediente e Ordem do Dia, mas não Assuntos Parlamentares.", "a pauta pode ser ampliada por requerimento aprovado.", "só há Ordem do Dia, e ela se restringe à matéria que motivou a convocação."], "ci": 3, "why": "Só Ordem do Dia, fechada. Não há Expediente nem Assuntos Parlamentares.", "study": "Regimento Interno, Aula 02 (arts. 147 a 155)"}, {"id": "v2-q070", "src": "Apostila Vol. 2", "num": 70, "top": 22, "tema": "v2-15", "stem": "A Ordem do Dia da sessão extraordinária só pode ser alterada ou interrompida para:", "opts": ["comunicação de licença, posse de Vereador ou suplente e retirada de proposição da pauta.", "inversão de pauta e destaque.", "qualquer requerimento aprovado pelo Plenário.", "apenas para posse de Vereador."], "ci": 0, "why": "Três hipóteses: comunicação de licença, posse de Vereador ou Suplente e retirada de proposição da pauta.", "study": "Regimento Interno, Aula 02 (arts. 147 a 155)"}, {"id": "v2-q071", "src": "Apostila Vol. 2", "num": 71, "top": 22, "tema": "v2-15", "stem": "A convocação de sessão extraordinária durante o recesso:", "opts": ["é livre, a critério da Mesa.", "só é admitida em caso de calamidade pública ou interesse público.", "é vedada em qualquer hipótese.", "depende de autorização do Prefeito."], "ci": 1, "why": "No recesso, só por calamidade pública ou interesse público.", "study": "Regimento Interno, Aula 02 (arts. 147 a 155)"}, {"id": "v2-q072", "src": "Apostila Vol. 2", "num": 72, "top": 22, "tema": "v2-15", "stem": "Sobre as sessões especiais, é correto afirmar:", "opts": ["duram duas horas, com segunda chamada em 15 minutos.", "são convocadas apenas pelo Prefeito.", "podem deliberar sobre projetos de lei ordinários.", "destinam-se a solenidades, exigem maioria absoluta para abrir e não têm duração fixa."], "ci": 3, "why": "Especiais: solenidades de decretos, resoluções e requerimentos aprovados; maioria absoluta; sem tempo determinado; convocação pelo Presidente de ofício ou por requerimento de 1/3, deferido de plano.", "study": "Regimento Interno, Aula 02 (arts. 156 e 157)"}, {"id": "v3-q001", "src": "Apostila Vol. 3", "num": 1, "top": 16, "tema": "v3-01", "stem": "A Lei Orgânica do Município deve ser votada em ___ turnos, com interstício mínimo de ___ dias, e aprovada por ___ dos membros da Câmara. Assinale a alternativa correta.", "opts": ["dois; cinco; maioria absoluta.", "três; dez; dois terços.", "dois; dez; maioria absoluta.", "dois; dez; dois terços."], "ci": 3, "why": "Macete DDD: Dois turnos, Dez dias, Dois terços (CF, art. 29). Quem a promulga é a própria Câmara.", "study": "LOM, Aula 01 (art. 29 da CF)"}, {"id": "v3-q002", "src": "Apostila Vol. 3", "num": 2, "top": 16, "tema": "v3-01", "stem": "Sobre a natureza da Lei Orgânica, é correto afirmar:", "opts": ["é manifestação do poder constituinte derivado decorrente, tal como as Constituições estaduais.", "desempenha, no Município, papel equivalente ao da Constituição estadual, mas sua elaboração não é manifestação de poder constituinte derivado decorrente.", "é votada pela Assembleia Legislativa e promulgada pelo Prefeito.", "pode contrariar a Constituição do Estado, desde que respeite a Constituição Federal."], "ci": 1, "why": "A LOM é a norma de auto-organização, mas a CF não atribui poder constituinte ao Município. Ela deve observar a CF e a Constituição do Estado.", "study": "LOM, Aula 01 (Posição constitucional do Município)"}, {"id": "v3-q003", "src": "Apostila Vol. 3", "num": 3, "top": 16, "tema": "v3-01", "stem": "As quatro capacidades que compõem a autonomia política do Município são:", "opts": ["soberania, autolegislação, autoadministração e autogoverno.", "auto-organização, soberania, autonomia judiciária e autogoverno.", "autolegislação, autoadministração, autogoverno e autonomia jurisdicional.", "auto-organização, autolegislação, autoadministração e autogoverno."], "ci": 3, "why": "Soberania é atributo só da República Federativa do Brasil. Não existe Poder Judiciário municipal.", "study": "LOM, Aula 01 (Posição constitucional do Município)"}, {"id": "v3-q004", "src": "Apostila Vol. 3", "num": 4, "top": 16, "tema": "v3-01", "stem": "Segundo a Lei Orgânica de Rio Verde, são poderes do Município, independentes e harmônicos entre si:", "opts": ["o Legislativo, o Executivo e o Judiciário.", "o Legislativo e o Executivo.", "o Legislativo, o Executivo e o de Controle.", "apenas o Executivo."], "ci": 1, "why": "Art. 5º: Legislativo e Executivo. Não há Judiciário municipal.", "study": "LOM, Aula 01 (arts. 1º a 6º)"}, {"id": "v3-q005", "src": "Apostila Vol. 3", "num": 5, "top": 16, "tema": "v3-02", "stem": "Quanto às eleições municipais, segundo o art. 29 da CF:", "opts": ["a eleição ocorre no último domingo de outubro, sempre em dois turnos.", "o segundo turno é possível nos Municípios com mais de 200 mil habitantes.", "a eleição de Prefeito e Vice ocorre no primeiro domingo de outubro do ano anterior ao término do mandato, com possibilidade de segundo turno nos Municípios com mais de 200 mil eleitores.", "Prefeito e Vice tomam posse em 1º de fevereiro."], "ci": 2, "why": "O critério do segundo turno é o número de eleitores (200 mil), não de habitantes. A posse é em 1º de janeiro.", "study": "LOM, Aula 01 (art. 29, I a III, da CF)"}, {"id": "v3-q006", "src": "Apostila Vol. 3", "num": 6, "top": 16, "tema": "v3-02", "stem": "O total da despesa com a remuneração dos Vereadores não pode ultrapassar:", "opts": ["5% da receita do Município.", "7% da receita do Município.", "70% da receita da Câmara.", "3,5% da receita tributária do exercício."], "ci": 0, "why": "CF, art. 29, VII: 5% da receita do Município. Não confunda com os 70% da folha da Câmara, nem com os 7% a 3,5% do art. 29-A.", "study": "LOM, Aula 01 (art. 29, VII, da CF)"}, {"id": "v3-q007", "src": "Apostila Vol. 3", "num": 7, "top": 16, "tema": "v3-02", "stem": "A despesa total do Poder Legislativo municipal (art. 29-A da CF) é limitada a percentuais que variam conforme:", "opts": ["a população do Município, calculados sobre a receita tributária e as transferências do exercício anterior.", "o número de eleitores, calculados sobre a receita prevista para o exercício corrente.", "o número de Vereadores, calculados sobre o orçamento do Executivo.", "a receita corrente líquida do exercício corrente."], "ci": 0, "why": "As faixas vão de 7% a 3,5% conforme a população. A base é a receita tributária e transferências efetivamente realizadas no exercício anterior.", "study": "LOM, Aula 01 (art. 29-A da CF)"}, {"id": "v3-q008", "src": "Apostila Vol. 3", "num": 8, "top": 16, "tema": "v3-02", "stem": "O repasse do duodécimo à Câmara deve ser entregue até o dia ___ de cada mês, e constitui crime de responsabilidade do Prefeito enviá-lo após esse prazo. Assinale a alternativa que completa a frase.", "opts": ["10.", "20.", "15.", "30."], "ci": 1, "why": "Dia vinte. O Prefeito também comete o crime se repassar além do limite ou enviar a menor que a proporção da lei orçamentária.", "study": "LOM, Aula 01 (art. 29-A, § 2º, da CF)"}, {"id": "v3-q009", "src": "Apostila Vol. 3", "num": 9, "top": 16, "tema": "v3-02", "stem": "A iniciativa popular de projetos de lei de interesse específico do Município exige a manifestação de, pelo menos:", "opts": ["1% do eleitorado.", "10% da população.", "5% do eleitorado.", "1/3 dos Vereadores."], "ci": 2, "why": "Art. 29, XIII, da CF e art. 43 da LOM: 5% do eleitorado (não da população).", "study": "LOM, Aula 01 (art. 29, XIII; art. 43 da LOM)"}, {"id": "v3-q010", "src": "Apostila Vol. 3", "num": 10, "top": 16, "tema": "v3-03", "stem": "O Município pode legislar sobre horário de funcionamento de estabelecimento comercial. Já sobre horário de funcionamento de agências bancárias, segundo o STF:", "opts": ["a competência também é municipal.", "a competência não é municipal, por extrapolar o interesse local.", "a competência é do Estado.", "a competência é concorrente entre Estado e Município."], "ci": 1, "why": "Súmula Vinculante 38 para comércio em geral. Para agências bancárias, o horário se relaciona ao sistema financeiro nacional, e não é interesse local.", "study": "LOM, Aula 01 (competências do Município)"}, {"id": "v3-q011", "src": "Apostila Vol. 3", "num": 11, "top": 16, "tema": "v3-03", "stem": "A competência para legislar sobre trânsito e transporte é:", "opts": ["privativa da União, mas todos os entes podem instituir programas de educação para a segurança no trânsito.", "do Município, por se tratar de interesse local.", "concorrente entre União, Estados e Municípios.", "privativa dos Estados."], "ci": 0, "why": "CF, art. 22, XI. A educação para o trânsito é competência comum (art. 23, XII). Lei municipal que obriga cinto de segurança é inconstitucional.", "study": "LOM, Aula 01 (competências do Município)"}, {"id": "v3-q012", "src": "Apostila Vol. 3", "num": 12, "top": 16, "tema": "v3-03", "stem": "Na Lei Orgânica de Rio Verde, o Município deve aplicar, anualmente, na manutenção e desenvolvimento do ensino:", "opts": ["no máximo 25% da receita total.", "15% da receita tributária própria.", "nunca menos de 25% da receita resultante de impostos, incluídas as transferências.", "30% da receita corrente líquida."], "ci": 2, "why": "É um mínimo de 25%, calculado sobre a receita de impostos (com transferências).", "study": "LOM, Aula 01 (art. 7º, XIII)"}, {"id": "v3-q013", "src": "Apostila Vol. 3", "num": 13, "top": 16, "tema": "v3-03", "stem": "A Lei Orgânica determina que as contas do Município fiquem, anualmente, à disposição de qualquer contribuinte durante:", "opts": ["30 dias.", "90 dias.", "15 dias.", "60 dias."], "ci": 3, "why": "60 dias (art. 7º, XXXIV, e art. 54). Pegadinha: confundir com os 30 dias dos relatórios bimestrais.", "study": "LOM, Aula 01 (art. 7º, XXXIV) e LOM, Aula 02 (art. 54)"}, {"id": "v3-q014", "src": "Apostila Vol. 3", "num": 14, "top": 16, "tema": "v3-03", "stem": "Na construção de moradias populares, a Lei Orgânica prevê, para os beneficiários, o regime de:", "opts": ["comodato, a ser regulamentado por lei municipal.", "doação com encargo.", "compra e venda a prazo.", "locação social, regulamentada por decreto."], "ci": 0, "why": "Art. 10, VIII. Comodato é empréstimo gratuito: o beneficiário não vira proprietário.", "study": "LOM, Aula 01 (art. 10, VIII)"}, {"id": "v3-q015", "src": "Apostila Vol. 3", "num": 15, "top": 13, "tema": "v3-04", "stem": "É vedado ao Município, segundo a Lei Orgânica:", "opts": ["promover publicidade de caráter educativo, informativo ou de orientação social.", "celebrar convênios com a União e o Estado.", "manter publicidade de órgãos públicos da qual constem nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades.", "colaborar com igrejas, na forma da lei, por interesse público."], "ci": 2, "why": "A publicidade institucional deve ser educativa, informativa ou de orientação social, sem promoção pessoal. A colaboração de interesse público com igrejas é a ressalva do art. 12, I.", "study": "LOM, Aula 01 (art. 12)"}, {"id": "v3-q016", "src": "Apostila Vol. 3", "num": 16, "top": 13, "tema": "v3-04", "stem": "Segundo o art. 12 da Lei Orgânica, a doação de bens imóveis do Município, a constituição de ônus real e a concessão de isenções ou remissões fora dos casos de manifesto interesse público exigem:", "opts": ["apenas decreto do Prefeito.", "expressa autorização da Câmara, sob pena de nulidade do ato.", "aprovação por 2/3 do Tribunal de Contas.", "parecer da Mesa, sem votação do Plenário."], "ci": 1, "why": "Art. 12, V. Perceba que a autorização da Câmara não torna lícito o ato sem interesse público.", "study": "LOM, Aula 01 (art. 12, V e VIII)"}, {"id": "v3-q017", "src": "Apostila Vol. 3", "num": 17, "top": 13, "tema": "v3-04", "stem": "Quanto à alienação de bens da administração direta, indireta e fundacional, a Lei Orgânica veda, em qualquer hipótese:", "opts": ["a alienação, nos seis meses anteriores à eleição.", "a alienação de bens móveis.", "a alienação nos últimos três meses do mandato do Prefeito.", "a alienação durante todo o último ano do mandato."], "ci": 2, "why": "Art. 33, XVII: vedada nos últimos três meses do mandato do Prefeito.", "study": "LOM, Aula 01 (art. 33, XVII)"}, {"id": "v3-q018", "src": "Apostila Vol. 3", "num": 18, "top": 13, "tema": "v3-04", "stem": "O Município de Rio Verde tem como símbolos e data magna:", "opts": ["Bandeira, Hino, Brasão e Lema; data magna em 31 de outubro.", "apenas Bandeira e Hino; data magna em 5 de agosto.", "Bandeira, Hino e Brasão; data magna em 1º de janeiro.", "Bandeira, Hino e Brasão; data magna em 5 de agosto."], "ci": 3, "why": "Arts. 3º e 4º: três símbolos, e a data magna é 5 de agosto.", "study": "LOM, Aula 01 (arts. 3º e 4º)"}, {"id": "v3-q019", "src": "Apostila Vol. 3", "num": 19, "top": 21, "tema": "v3-05", "stem": "Na Lei Orgânica de Rio Verde, a Câmara é composta por:", "opts": ["21 Vereadores, eleitos pelo sistema majoritário, para mandato de 2 anos.", "19 Vereadores, eleitos pelo sistema proporcional.", "23 Vereadores, eleitos pelo sistema majoritário.", "21 Vereadores, eleitos pelo sistema proporcional, para mandato de 4 anos."], "ci": 3, "why": "Art. 14. Maioria absoluta = 11; 2/3 = 14; 1/3 = 7.", "study": "LOM, Aula 01 (art. 14)"}, {"id": "v3-q020", "src": "Apostila Vol. 3", "num": 20, "top": 21, "tema": "v3-05", "stem": "A Câmara se reúne anualmente na sede do Município:", "opts": ["de 1º de janeiro a 30 de junho e de 1º de agosto a 15 de dezembro.", "de 1º de fevereiro a 30 de junho e de 15 de julho a 15 de dezembro.", "de 2 de fevereiro a 17 de julho e de 1º de agosto a 22 de dezembro.", "o ano todo, sem recesso."], "ci": 2, "why": "Art. 15. Os intervalos são o recesso parlamentar.", "study": "LOM, Aula 01 (art. 15)"}, {"id": "v3-q021", "src": "Apostila Vol. 3", "num": 21, "top": 21, "tema": "v3-05", "stem": "Pela Lei Orgânica, a convocação extraordinária da Câmara pode ser feita:", "opts": ["somente pelo Presidente.", "pelo Prefeito, pelo Presidente (posse do Prefeito e Vice, ou urgência ou interesse público relevante a requerimento da maioria dos membros) e pela Comissão Representativa.", "somente pelo Prefeito.", "por qualquer Vereador."], "ci": 1, "why": "Art. 15, § 3º. A convocação extraordinária não gera remuneração extra aos Vereadores.", "study": "LOM, Aula 01 (art. 15, § 3º)"}, {"id": "v3-q022", "src": "Apostila Vol. 3", "num": 22, "top": 21, "tema": "v3-05", "stem": "Segundo a Lei Orgânica, as sessões da Câmara são públicas, salvo deliberação em contrário por:", "opts": ["maioria simples, a critério do Presidente.", "2/3 dos Vereadores, em razão de motivo relevante.", "maioria absoluta, sem necessidade de motivo.", "1/3 dos Vereadores."], "ci": 1, "why": "Art. 19: 2/3 (14 Vereadores). Atenção: o Regimento Interno (material do curso) trata o sigilo por maioria absoluta. Em prova, siga o diploma citado no enunciado.", "study": "LOM, Aula 01 (art. 19)"}, {"id": "v3-q023", "src": "Apostila Vol. 3", "num": 23, "top": 21, "tema": "v3-05", "stem": "Pela Lei Orgânica, a regra geral de deliberação é:", "opts": ["maioria absoluta dos membros, em qualquer matéria.", "unanimidade dos presentes.", "2/3 dos presentes.", "maioria de votos, presente a maioria dos membros da Câmara."], "ci": 3, "why": "Art. 16. Presença de 11 não significa que a matéria precise de 11 votos favoráveis. Lei complementar, sim: 11 votos.", "study": "LOM, Aula 01 (art. 16)"}, {"id": "v3-q024", "src": "Apostila Vol. 3", "num": 24, "top": 22, "tema": "v3-06", "stem": "No início da legislatura, a posse dos Vereadores, do Prefeito e do Vice-Prefeito ocorre em sessão solene em 1º de janeiro, presidida pelo:", "opts": ["Vereador mais votado dentre os presentes, com qualquer número de presentes.", "Vereador mais idoso, com a maioria absoluta.", "Prefeito eleito.", "Juiz eleitoral da comarca."], "ci": 0, "why": "Art. 21. A eleição da Mesa, logo após a posse, exige maioria absoluta (11).", "study": "LOM, Aula 01 (art. 21)"}, {"id": "v3-q025", "src": "Apostila Vol. 3", "num": 25, "top": 22, "tema": "v3-06", "stem": "O Vereador que não tomar posse na sessão inaugural deve fazê-lo em:", "opts": ["5 dias, sem exceções.", "15 dias do início do funcionamento normal da Câmara, sob pena de perda de mandato, salvo motivo justo aceito pela maioria.", "30 dias, sem exceções.", "10 dias da data da diplomação."], "ci": 1, "why": "Art. 21, § 1º. Em outra regra (Prefeito e Vice, art. 57), o prazo para tomar posse é de 10 dias.", "study": "LOM, Aula 01 (art. 21, § 1º)"}, {"id": "v3-q026", "src": "Apostila Vol. 3", "num": 26, "top": 22, "tema": "v3-06", "stem": "Na Lei Orgânica, na ausência dos membros da Mesa, a Presidência será assumida pelo Vereador:", "opts": ["mais votado dentre os presentes.", "de maior número de mandatos.", "indicado pelo Prefeito.", "mais idoso dentre os presentes."], "ci": 3, "why": "Art. 22, § 2º. O mais votado preside apenas a instalação e a eleição da Mesa. Destituição de membro da Mesa: 2/3.", "study": "LOM, Aula 01 (art. 22)"}, {"id": "v3-q027", "src": "Apostila Vol. 3", "num": 27, "top": 22, "tema": "v3-06", "stem": "Quanto à duração do mandato da Mesa, a Lei Orgânica (art. 21, § 4º) dispõe que a Câmara:", "opts": ["pode optar por um ou mais anos, vedada a recondução para o mesmo cargo na eleição imediatamente subsequente.", "tem mandato obrigatório de dois anos, com recondução livre.", "tem mandato obrigatório de um ano, com recondução livre.", "tem mandato de quatro anos."], "ci": 0, "why": "O texto da LOM dá liberdade na duração. Atenção: o Regimento (material do curso) fala em duas sessões legislativas. Não misture os diplomas.", "study": "LOM, Aula 01 (art. 21, § 4º)"}, {"id": "v3-q028", "src": "Apostila Vol. 3", "num": 28, "top": 22, "tema": "v3-06", "stem": "A Comissão Representativa:", "opts": ["é eleita ao término de cada sessão legislativa, em votação secreta, funciona no recesso, tem número ímpar de Vereadores e é presidida pelo Presidente da Câmara.", "é eleita no início da legislatura, em votação aberta, e funciona o ano todo.", "é composta por todos os Vereadores.", "é presidida pelo Prefeito."], "ci": 0, "why": "Art. 27. Reúne-se uma vez por semana, autoriza o Prefeito a ausentar-se por mais de 15 dias e pode convocar extraordinariamente a Câmara.", "study": "LOM, Aula 01 (art. 27)"}, {"id": "v3-q029", "src": "Apostila Vol. 3", "num": 29, "top": 22, "tema": "v3-07", "stem": "A criação de CPI exige requerimento de:", "opts": ["maioria absoluta, fato determinado e prazo indeterminado.", "2/3 dos membros, sem fato determinado.", "1/3 dos membros da Câmara (7 Vereadores), fato determinado e prazo certo.", "qualquer Vereador, com aprovação do Prefeito."], "ci": 2, "why": "Art. 23, § 4º. As conclusões vão ao Ministério Público, se for o caso.", "study": "LOM, Aula 01 (art. 23, § 4º)"}, {"id": "v3-q030", "src": "Apostila Vol. 3", "num": 30, "top": 22, "tema": "v3-07", "stem": "A comissão permanente pode discutir e votar projeto de lei dispensado da competência do Plenário, salvo se houver recurso de:", "opts": ["1/3 dos membros da Casa.", "maioria absoluta.", "2/3 dos membros.", "qualquer Vereador."], "ci": 0, "why": "Art. 23, § 1º, I: recurso de um terço (7 Vereadores).", "study": "LOM, Aula 01 (art. 23, § 1º)"}, {"id": "v3-q031", "src": "Apostila Vol. 3", "num": 31, "top": 22, "tema": "v3-07", "stem": "Sobre a relação com os Secretários Municipais, a Lei Orgânica prevê que a Mesa pode encaminhar pedido escrito de informações, com prazo de:", "opts": ["30 dias.", "15 dias.", "48 horas.", "60 dias."], "ci": 0, "why": "Art. 30. A convocação para comparecimento pessoal (art. 28) depende de maioria dos membros. A expressão “crime de responsabilidade” deve ser lida conforme a SV 46: só a União define crimes de responsabilidade.", "study": "LOM, Aula 01 (arts. 28 a 30)"}, {"id": "v3-q032", "src": "Apostila Vol. 3", "num": 32, "top": 22, "tema": "v3-07", "stem": "A convocação de Secretário Municipal para prestar informações pessoalmente depende de deliberação de:", "opts": ["2/3 dos membros.", "maioria dos membros da Câmara, sobre assuntos previamente estabelecidos.", "1/3 dos membros.", "decisão monocrática do Presidente."], "ci": 1, "why": "Art. 28. Nada impede o comparecimento a pedido do próprio Secretário (art. 29).", "study": "LOM, Aula 01 (arts. 28 e 29)"}, {"id": "v3-q033", "src": "Apostila Vol. 3", "num": 33, "top": 22, "tema": "v3-07", "stem": "Segundo a Lei Orgânica, têm Líderes e Vice-Líderes a Maioria, a Minoria, os Blocos e as representações partidárias com número de membros:", "opts": ["superior a 1/3 da composição da Casa.", "igual ou inferior a 1/10 da composição da Casa.", "superior à metade da composição da Casa.", "superior a 1/10 da composição da Casa."], "ci": 3, "why": "Art. 24. Mais de 1/10 de 21 = pelo menos 3 Vereadores. Os líderes são indicados nas 24 horas após a instalação do 1º período legislativo anual.", "study": "LOM, Aula 01 (arts. 24 e 25)"}, {"id": "v3-q034", "src": "Apostila Vol. 3", "num": 34, "top": 21, "tema": "v3-08", "stem": "O parecer prévio do Tribunal de Contas dos Municípios sobre as contas do Prefeito só deixa de prevalecer por decisão de:", "opts": ["maioria absoluta (11 votos).", "maioria simples.", "2/3 dos membros da Câmara (14 votos).", "3/5 dos membros."], "ci": 2, "why": "Art. 34, VIII, a, e art. 52, § 2º. O prazo para a Câmara deliberar é de 60 dias do recebimento, e a falta de deliberação não aprova nem rejeita as contas.", "study": "LOM, Aula 01 (art. 34, VIII) e LOM, Aula 02 (art. 52)"}, {"id": "v3-q035", "src": "Apostila Vol. 3", "num": 35, "top": 21, "tema": "v3-08", "stem": "A Câmara procede à tomada de contas do Prefeito, por comissão especial, quando:", "opts": ["as contas forem apresentadas fora do prazo, sem outras condições.", "as contas não forem apresentadas à Câmara em 60 dias após a reabertura da sessão legislativa.", "o Tribunal de Contas rejeitar o orçamento.", "o Prefeito faltar a uma sessão."], "ci": 1, "why": "Art. 34, XIV. Rejeitadas as contas, são remetidas imediatamente ao Ministério Público.", "study": "LOM, Aula 01 (art. 34, VIII e XIV)"}, {"id": "v3-q036", "src": "Apostila Vol. 3", "num": 36, "top": 21, "tema": "v3-08", "stem": "A autorização para o Prefeito ausentar-se do Município é necessária quando a ausência for:", "opts": ["igual ou superior a 7 dias.", "superior a 15 dias.", "superior a 30 dias.", "qualquer, mesmo por um dia."], "ci": 1, "why": "Art. 34, VII, e art. 62. “Mais de 15 dias”: exatamente 15 dias não exige autorização.", "study": "LOM, Aula 01 (art. 34, VII)"}, {"id": "v3-q037", "src": "Apostila Vol. 3", "num": 37, "top": 21, "tema": "v3-08", "stem": "A concessão de título de cidadão honorário depende de proposta aprovada pelo voto de:", "opts": ["2/3 dos membros da Câmara.", "maioria simples.", "maioria absoluta.", "1/3 dos membros."], "ci": 0, "why": "Art. 34, XX. Cada competência tem seu quórum: CPI, 1/3; cidadão honorário, 2/3; contas, 2/3 para derrubar o parecer.", "study": "LOM, Aula 01 (art. 34, XX)"}, {"id": "v3-q038", "src": "Apostila Vol. 3", "num": 38, "top": 21, "tema": "v3-08", "stem": "Compete à Mesa da Câmara promulgar:", "opts": ["as resoluções e decretos legislativos.", "a Lei Orgânica e suas emendas.", "as leis de sanção tácita.", "as leis delegadas."], "ci": 1, "why": "Art. 31, IV. Resoluções e decretos legislativos são promulgados pelo Presidente (art. 32, IV).", "study": "LOM, Aula 01 (arts. 31 e 32)"}, {"id": "v3-q039", "src": "Apostila Vol. 3", "num": 39, "top": 13, "tema": "v3-09", "stem": "A Câmara fixa a remuneração do Prefeito, Vice-Prefeito, Presidente da Câmara e Vereadores até:", "opts": ["30 dias depois da eleição municipal.", "60 dias antes da posse.", "o fim do primeiro ano da legislatura.", "30 dias antes da eleição municipal, para vigorar na legislatura subsequente."], "ci": 3, "why": "Art. 35. Se não for fixada no devido tempo, ficam prorrogadas as fixações existentes.", "study": "LOM, Aula 01 (art. 35)"}, {"id": "v3-q040", "src": "Apostila Vol. 3", "num": 40, "top": 13, "tema": "v3-09", "stem": "O Prefeito, o Vice-Prefeito e os Vereadores fazem jus ao 13º salário, que pode ser pago em parcela única em dezembro ou em duas parcelas:", "opts": ["40% na data de aniversário do agente político e 60% em dezembro.", "50% em junho e 50% em dezembro.", "30% em março e 70% em dezembro.", "60% na data de aniversário e 40% em dezembro."], "ci": 0, "why": "Art. 35, § 5º. O STF (Tema 484) reconheceu que o subsídio não é incompatível com décimo terceiro e terço de férias.", "study": "LOM, Aula 01 (art. 35, § 5º)"}, {"id": "v3-q041", "src": "Apostila Vol. 3", "num": 41, "top": 13, "tema": "v3-09", "stem": "O limite de 70% da receita da Câmara com folha de pagamento:", "opts": ["inclui os subsídios dos Vereadores, e seu desrespeito é crime de responsabilidade do Presidente da Câmara.", "exclui os subsídios dos Vereadores.", "é crime de responsabilidade do Prefeito.", "não existe na CF."], "ci": 0, "why": "Art. 29-A, § 1º e § 3º. Os limites do art. 29-A são diferentes do teto de 5% do art. 29, VII.", "study": "LOM, Aula 01 (art. 29-A)"}, {"id": "v3-q042", "src": "Apostila Vol. 3", "num": 42, "top": 13, "tema": "v3-09", "stem": "Em relação ao subsídio do Presidente da Câmara, a Lei Orgânica admite verba de representação, fixada em até:", "opts": ["100% de sua remuneração.", "20% de sua remuneração.", "50% de sua remuneração, limitada ao que perceber o Prefeito.", "50% do que perceber o Prefeito, sem outro limite."], "ci": 2, "why": "Art. 35, § 2º. A literalidade não afasta o art. 39, § 4º, da CF, que veda parcelas adicionais ao subsídio: o comentário do curso alerta para isso.", "study": "LOM, Aula 01 (art. 35, § 2º)"}, {"id": "v3-q043", "src": "Apostila Vol. 3", "num": 43, "top": 13, "tema": "v3-10", "stem": "A inviolabilidade dos Vereadores por suas opiniões, palavras e votos:", "opts": ["vale em qualquer lugar do país, sem relação com o mandato.", "vale no exercício do mandato e na circunscrição do Município.", "depende de autorização da Mesa.", "vale apenas dentro do plenário."], "ci": 1, "why": "Imunidade material, não formal (os Vereadores não têm imunidade processual). O STF exige pertinência com a função (Tema 469).", "study": "LOM, Aula 01 (art. 36)"}, {"id": "v3-q044", "src": "Apostila Vol. 3", "num": 44, "top": 13, "tema": "v3-10", "stem": "Desde a expedição do diploma, os Vereadores não podem:", "opts": ["ser proprietários de qualquer empresa privada.", "patrocinar causa em que seja interessada entidade municipal.", "firmar ou manter contrato com o Município e entidades indicadas, salvo cláusulas uniformes.", "ser titulares de mais de um cargo eletivo."], "ci": 2, "why": "Art. 37, I (diploma). As alíneas II (patrocinar causa, mais de um cargo eletivo, etc.) valem a partir da posse.", "study": "LOM, Aula 01 (art. 37)"}, {"id": "v3-q045", "src": "Apostila Vol. 3", "num": 45, "top": 13, "tema": "v3-10", "stem": "Entre as hipóteses de perda do mandato do Vereador está a ausência, em cada sessão legislativa, a:", "opts": ["metade das sessões ordinárias.", "2/3 das sessões ordinárias.", "1/3 das sessões ordinárias ou a 5 sessões extraordinárias regularmente convocadas, salvo licença ou missão autorizada.", "3 sessões extraordinárias consecutivas."], "ci": 2, "why": "Art. 38, III. A cassação no DL 201/67 exige 2/3 e votação nominal, mesmo com a previsão local de maioria absoluta e voto secreto.", "study": "LOM, Aula 01 (art. 38)"}, {"id": "v3-q046", "src": "Apostila Vol. 3", "num": 46, "top": 13, "tema": "v3-10", "stem": "A licença do Vereador para tratar de interesse particular:", "opts": ["é remunerada e de até 120 dias.", "não tem limite de dias.", "é de, no mínimo, 15 dias.", "é sem remuneração, não pode ultrapassar 120 dias por sessão legislativa e não pode ser inferior a 30 dias."], "ci": 3, "why": "Art. 39, II e § 4º. O Vereador não pode reassumir antes do término da licença.", "study": "LOM, Aula 01 (art. 39)"}, {"id": "v3-q047", "src": "Apostila Vol. 3", "num": 47, "top": 13, "tema": "v3-10", "stem": "Dar-se-á convocação de suplente de Vereador nos casos de vaga, de investidura em certas funções do art. 39, § 1º, ou de licença:", "opts": ["igual ou superior a 60 dias.", "superior a 30 dias.", "superior a 120 dias.", "por qualquer prazo."], "ci": 2, "why": "Art. 40. O suplente convocado toma posse em 5 dias. Atenção: o Regimento (curso) fala em convocação em 48 horas; são regras de normas diferentes.", "study": "LOM, Aula 01 (art. 40)"}, {"id": "v3-q048", "src": "Apostila Vol. 3", "num": 48, "top": 13, "tema": "v3-10", "stem": "Ocorrendo vaga e não havendo suplente, haverá eleição para preenchê-la se faltarem:", "opts": ["mais de 15 meses para o término do mandato.", "15 meses ou mais.", "mais de 12 meses.", "mais de 6 meses."], "ci": 0, "why": "Art. 40, § 3º. “Mais de 15 meses”: exatamente 15 não gera eleição.", "study": "LOM, Aula 01 (art. 40, § 3º)"}, {"id": "v3-q049", "src": "Apostila Vol. 3", "num": 49, "top": 10, "tema": "v3-11", "stem": "São espécies do processo legislativo municipal, segundo a Lei Orgânica:", "opts": ["emenda à LOM, leis complementares, leis ordinárias e medidas provisórias.", "emenda à LOM, leis complementares, leis ordinárias, leis delegadas, decretos legislativos e resoluções.", "leis complementares, leis ordinárias, decretos e portarias.", "emenda à LOM, leis ordinárias, medidas provisórias e resoluções."], "ci": 1, "why": "Art. 41. Não há medida provisória no rol.", "study": "LOM, Aula 01 (art. 41)"}, {"id": "v3-q050", "src": "Apostila Vol. 3", "num": 50, "top": 10, "tema": "v3-11", "stem": "A proposta de emenda à Lei Orgânica pode ser apresentada por:", "opts": ["qualquer Vereador.", "maioria absoluta dos Vereadores, apenas.", "5% do eleitorado.", "1/3, no mínimo, dos membros da Câmara ou pelo Prefeito."], "ci": 3, "why": "Art. 42. Aprovação: dois turnos, 10 dias, 2/3 (14 votos). A promulgação é da Mesa, sem sanção ou veto.", "study": "LOM, Aula 01 (art. 42)"}, {"id": "v3-q051", "src": "Apostila Vol. 3", "num": 51, "top": 10, "tema": "v3-11", "stem": "A matéria de proposta de emenda à LOM rejeitada ou prejudicada:", "opts": ["pode ser reapresentada na mesma sessão legislativa pela maioria absoluta.", "pode ser reapresentada a qualquer tempo.", "só pode ser reapresentada na próxima legislatura.", "não pode ser objeto de nova proposta na mesma sessão legislativa."], "ci": 3, "why": "Art. 42, § 4º. Irrepetibilidade absoluta. Diferente do projeto de lei rejeitado, que pode voltar com maioria absoluta (art. 51). A LOM também não pode ser emendada em estado de sítio ou intervenção.", "study": "LOM, Aula 01 (arts. 42 e 51)"}, {"id": "v3-q052", "src": "Apostila Vol. 3", "num": 52, "top": 10, "tema": "v3-11", "stem": "As leis complementares somente são aprovadas se obtiverem:", "opts": ["maioria absoluta dos votos dos membros da Câmara (11).", "2/3 dos membros.", "maioria simples.", "maioria absoluta dos presentes."], "ci": 0, "why": "Art. 44. Entre as leis complementares: Código Tributário, Código de Obras, Plano de Desenvolvimento Urbano, Código de Posturas, regime jurídico único e lei da Guarda Municipal.", "study": "LOM, Aula 01 (art. 44)"}, {"id": "v3-q053", "src": "Apostila Vol. 3", "num": 53, "top": 10, "tema": "v3-11", "stem": "É de iniciativa exclusiva do Prefeito o projeto de lei que disponha sobre:", "opts": ["a organização dos serviços administrativos da Câmara.", "a denominação de logradouros públicos, sempre.", "a concessão de título de cidadão honorário.", "criação, transformação ou extinção de cargos na administração direta e autárquica, ou aumento de sua remuneração."], "ci": 3, "why": "Art. 45, I. A organização dos serviços da Câmara é de iniciativa exclusiva da Mesa (art. 46).", "study": "LOM, Aula 01 (arts. 45 e 46)"}, {"id": "v3-q054", "src": "Apostila Vol. 3", "num": 54, "top": 10, "tema": "v3-11", "stem": "A iniciativa das leis cabe a qualquer Vereador, ao Prefeito e ao eleitorado, que a exerce por proposta subscrita por, no mínimo:", "opts": ["5% da população do Município.", "10% dos eleitores que votaram na última eleição.", "5% do total de eleitores do Município.", "1% do eleitorado."], "ci": 2, "why": "Art. 43. A base de cálculo é o número total de eleitores.", "study": "LOM, Aula 01 (art. 43)"}, {"id": "v3-q055", "src": "Apostila Vol. 3", "num": 55, "top": 11, "tema": "v3-12", "stem": "Solicitada a urgência pelo Prefeito, a Câmara deve se manifestar em até:", "opts": ["30 dias.", "45 dias, contados da data da solicitação.", "15 dias úteis.", "60 dias."], "ci": 1, "why": "Art. 47, § 1º. Conferi os arts. 47 a 51 em transcrição obtida no site da Prefeitura (versão de 2019), porque o PDF do curso corta nesse ponto.", "study": "LOM, Aula 01 (art. 47) e site da Prefeitura"}, {"id": "v3-q056", "src": "Apostila Vol. 3", "num": 56, "top": 11, "tema": "v3-12", "stem": "O Prefeito pode vetar projeto, total ou parcialmente, no prazo de:", "opts": ["30 dias corridos; o silêncio equivale a veto.", "10 dias corridos; o silêncio equivale a sanção.", "15 dias úteis, contados do recebimento; o silêncio equivale a sanção.", "15 dias corridos; o silêncio equivale a veto."], "ci": 2, "why": "Art. 48, §§ 1º e 3º (texto do site da Prefeitura). O veto parcial só pode alcançar texto integral de artigo, parágrafo, inciso ou alínea.", "study": "LOM, Aula 01 (art. 48) e site da Prefeitura"}, {"id": "v3-q057", "src": "Apostila Vol. 3", "num": 57, "top": 11, "tema": "v3-12", "stem": "A Câmara aprecia o veto em ___ , e ele só é rejeitado por ___ , em votação secreta. Assinale a alternativa que completa a frase (texto do site da Prefeitura).", "opts": ["30 dias; maioria absoluta dos Vereadores.", "15 dias; maioria simples.", "45 dias; 2/3 dos Vereadores.", "60 dias; maioria absoluta, em votação aberta."], "ci": 0, "why": "Art. 48, §§ 1º e 4º. Rejeitado o veto, o projeto volta ao Prefeito para promulgação. Se ele não promulgar (ou em sanção tácita), o Presidente da Câmara promulga em 48 horas e, em seguida, o Vice-Presidente.", "study": "LOM, Aula 01 (art. 48) e site da Prefeitura"}, {"id": "v3-q058", "src": "Apostila Vol. 3", "num": 58, "top": 11, "tema": "v3-12", "stem": "As leis delegadas são elaboradas:", "opts": ["pela Câmara, mediante delegação do Prefeito.", "pelo Prefeito, mediante delegação da Câmara por decreto legislativo, que define o conteúdo e as condições.", "pela Mesa, por resolução.", "pelo Presidente da Câmara, sem delegação."], "ci": 1, "why": "Art. 49. Não podem ser delegados atos privativos da Câmara, matérias de lei complementar, plano plurianual e orçamento.", "study": "LOM, Aula 01 (art. 49) e site da Prefeitura"}, {"id": "v3-q059", "src": "Apostila Vol. 3", "num": 59, "top": 11, "tema": "v3-12", "stem": "A matéria de projeto de lei rejeitado só pode constituir objeto de novo projeto na mesma sessão legislativa mediante proposta de:", "opts": ["maioria absoluta dos Vereadores.", "2/3 dos Vereadores.", "1/3 dos Vereadores.", "qualquer Vereador."], "ci": 0, "why": "Art. 51. A emenda à LOM rejeitada não tem essa exceção.", "study": "LOM, Aula 01 (art. 51) e site da Prefeitura"}, {"id": "v3-q060", "src": "Apostila Vol. 3", "num": 60, "top": 27, "tema": "v3-13", "stem": "O controle externo da Câmara é exercido com o auxílio do Tribunal de Contas dos Municípios, que:", "opts": ["é órgão do Município, subordinado à Câmara.", "julga as contas do Prefeito em última instância.", "é órgão estadual e não integra a estrutura administrativa do Município.", "é composto por Vereadores."], "ci": 2, "why": "Art. 52, § 1º. O TCM emite parecer prévio nas contas de governo do Prefeito, e a Câmara julga.", "study": "LOM, Aula 02 (art. 52)"}, {"id": "v3-q061", "src": "Apostila Vol. 3", "num": 61, "top": 27, "tema": "v3-13", "stem": "As contas de gestão dos administradores e responsáveis por bens e valores públicos são julgadas:", "opts": ["pela Câmara, por maioria simples.", "pelo Prefeito.", "pelo Tribunal de Contas.", "pelo Ministério Público."], "ci": 2, "why": "Distinção da ADPF 982: contas de governo (Prefeito), parecer do TC e julgamento pela Câmara; contas de gestão, julgamento pelo TC. O TC pode imputar débito ao Prefeito ordenador de despesas, preservada a competência eleitoral da Câmara.", "study": "LOM, Aula 02 (art. 52)"}, {"id": "v3-q062", "src": "Apostila Vol. 3", "num": 62, "top": 27, "tema": "v3-13", "stem": "O sistema de controle interno do Executivo tem a finalidade de, entre outras:", "opts": ["julgar as contas do Prefeito.", "emitir parecer prévio sobre as contas do Município.", "substituir o controle externo.", "criar condições para assegurar a eficácia do controle externo e verificar a execução dos contratos."], "ci": 3, "why": "Art. 53: eficácia do controle externo, acompanhamento de programas e orçamento, avaliação de resultados dos administradores e verificação da execução dos contratos.", "study": "LOM, Aula 02 (art. 53)"}, {"id": "v3-q063", "src": "Apostila Vol. 3", "num": 63, "top": 27, "tema": "v3-13", "stem": "As contas dos recursos transferidos pela União e pelo Estado:", "opts": ["dispensam inclusão na prestação anual do Município.", "são prestadas apenas à Câmara.", "são prestadas na forma da legislação federal e estadual, sem prejuízo de sua inclusão na prestação anual de contas do Município.", "não precisam ser prestadas."], "ci": 2, "why": "Art. 52, § 3º.", "study": "LOM, Aula 02 (art. 52, § 3º)"}, {"id": "v3-q064", "src": "Apostila Vol. 3", "num": 64, "top": 13, "tema": "v3-14", "stem": "As condições de elegibilidade para Prefeito e Vice-Prefeito incluem idade mínima de:", "opts": ["18 anos.", "21 anos.", "30 anos.", "25 anos."], "ci": 1, "why": "Art. 55, parágrafo único. Para Vereador e Secretário, 18 anos.", "study": "LOM, Aula 02 (art. 55)"}, {"id": "v3-q065", "src": "Apostila Vol. 3", "num": 65, "top": 13, "tema": "v3-14", "stem": "Se o Prefeito ou o Vice-Prefeito, salvo motivo de força maior, não assumir o cargo em 10 dias da data fixada para a posse, o cargo será:", "opts": ["prorrogado por mais 10 dias.", "assumido pelo Presidente da Câmara, com mandato próprio.", "mantido vago por 90 dias.", "declarado vago."], "ci": 3, "why": "Art. 57, parágrafo único, e art. 71, II.", "study": "LOM, Aula 02 (arts. 57 e 71)"}, {"id": "v3-q066", "src": "Apostila Vol. 3", "num": 66, "top": 13, "tema": "v3-14", "stem": "Vagando o cargo de Prefeito sem Vice, nos três primeiros anos do mandato, a Lei Orgânica determina eleição:", "opts": ["em 30 dias, com mandato de 4 anos.", "em 60 dias, apenas pela Câmara.", "no último domingo de outubro.", "90 dias após a abertura da vaga, e os eleitos completam o período dos antecessores."], "ci": 3, "why": "Art. 60. No último ano, assume o Presidente da Câmara, que completa o período. Nova eleição por decisão da Justiça Eleitoral segue o Código Eleitoral (art. 224).", "study": "LOM, Aula 02 (art. 60)"}, {"id": "v3-q067", "src": "Apostila Vol. 3", "num": 67, "top": 13, "tema": "v3-14", "stem": "No caso de impedimento do Prefeito e do Vice-Prefeito, serão chamados ao exercício do Poder Executivo, sucessivamente:", "opts": ["o Presidente da Câmara e o 1º Secretário.", "o Vereador mais votado e o mais idoso.", "o Secretário de Governo.", "o Presidente e o Vice-Presidente da Câmara."], "ci": 3, "why": "Art. 59. A recusa dos dirigentes do Legislativo importa renúncia a suas funções de direção.", "study": "LOM, Aula 02 (art. 59)"}, {"id": "v3-q068", "src": "Apostila Vol. 3", "num": 68, "top": 13, "tema": "v3-14", "stem": "Segundo a Lei Orgânica, o Prefeito e o Vice-Prefeito não poderão ausentar-se do Município, sem licença da Câmara, por período superior a:", "opts": ["15 dias.", "10 dias.", "30 dias.", "7 dias."], "ci": 0, "why": "Art. 62. O Prefeito licenciado mantém a remuneração em caso de doença comprovada ou serviço/missão de representação do Município. A declaração de bens é feita na posse e ao término do mandato.", "study": "LOM, Aula 02 (arts. 62 e 63)"}, {"id": "v3-q069", "src": "Apostila Vol. 3", "num": 69, "top": 13, "tema": "v3-15", "stem": "O Prefeito deve encaminhar à Câmara a prestação de contas e os balanços do exercício findo até:", "opts": ["15 de março.", "30 de junho.", "31 de dezembro.", "15 de abril."], "ci": 3, "why": "Art. 65, XI. As informações solicitadas pela Câmara são prestadas em 15 dias, prorrogáveis a pedido e por prazo determinado.", "study": "LOM, Aula 02 (art. 65)"}, {"id": "v3-q070", "src": "Apostila Vol. 3", "num": 70, "top": 13, "tema": "v3-15", "stem": "O relatório resumido da execução orçamentária deve ser publicado até:", "opts": ["30 dias após o encerramento de cada trimestre.", "60 dias após cada bimestre.", "15 dias após cada mês.", "30 dias após o encerramento de cada bimestre."], "ci": 3, "why": "Art. 65, XXXV, e art. 130, § 1º. Já a divulgação dos tributos arrecadados é até o último dia do mês subsequente ao da arrecadação.", "study": "LOM, Aula 02 (arts. 65 e 130)"}, {"id": "v3-q071", "src": "Apostila Vol. 3", "num": 71, "top": 13, "tema": "v3-15", "stem": "O Prefeito pode delegar, por decreto, a seus auxiliares:", "opts": ["as funções de prover cargos e atos funcionais, serviços e obras, e organização dos serviços internos das repartições.", "todas as suas atribuições.", "a sanção e o veto.", "a iniciativa de leis."], "ci": 0, "why": "Art. 66: incisos IX, XV e XXIV do art. 65.", "study": "LOM, Aula 02 (art. 66)"}, {"id": "v3-q072", "src": "Apostila Vol. 3", "num": 72, "top": 13, "tema": "v3-15", "stem": "Os crimes de responsabilidade do Prefeito e as infrações político-administrativas são, respectivamente, julgados:", "opts": ["pela Câmara e pelo Tribunal de Justiça.", "ambos pela Câmara.", "pelo Tribunal de Justiça e pela Câmara.", "ambos pelo Tribunal de Justiça."], "ci": 2, "why": "Arts. 69 e 70. Pelo DL 201/67 a cassação exige 2/3 e o processo deve ser concluído em 90 dias da notificação. A definição desses crimes e infrações é da União (SV 46).", "study": "LOM, Aula 02 (arts. 69 e 70)"}, {"id": "v3-q073", "src": "Apostila Vol. 3", "num": 73, "top": 13, "tema": "v3-15", "stem": "São condições para investidura no cargo de Secretário Municipal:", "opts": ["ser brasileiro, estar no exercício dos direitos políticos e ser maior de dezoito anos.", "ter 21 anos e ser eleitor.", "ser Vereador licenciado.", "ter curso superior."], "ci": 0, "why": "Art. 74. Os Secretários apresentam relatório semestral ao Prefeito e respondem solidariamente pelos atos que assinarem, ordenarem ou praticarem.", "study": "LOM, Aula 02 (arts. 72 a 76)"}, {"id": "v3-q074", "src": "Apostila Vol. 3", "num": 74, "top": 13, "tema": "v3-15", "stem": "O Subprefeito é nomeado “ad nutum” em até:", "opts": ["30 dias da posse, com competência em todo o Município.", "90 dias da posse, por concurso.", "60 dias da posse do Prefeito, com competência limitada ao distrito para o qual foi indicado.", "15 dias da posse, por lei."], "ci": 2, "why": "Art. 77. Prestação de contas mensal ao Prefeito, quando solicitada.", "study": "LOM, Aula 02 (art. 77)"}, {"id": "v3-q075", "src": "Apostila Vol. 3", "num": 75, "top": 18, "tema": "v3-16", "stem": "A validade do concurso público é de:", "opts": ["um ano, prorrogável por dois.", "até quatro anos, sem prorrogação.", "dois anos, improrrogável.", "até dois anos, prorrogável uma vez por igual período."], "ci": 3, "why": "Art. 80, III. A contratação temporária (art. 80, IX, na LOM) não pode ultrapassar 180 dias, vedada a recontratação.", "study": "LOM, Aula 02 (art. 80)"}, {"id": "v3-q076", "src": "Apostila Vol. 3", "num": 76, "top": 18, "tema": "v3-16", "stem": "São entidades da Administração indireta do Município, segundo a Lei Orgânica:", "opts": ["autarquia, empresa pública, sociedade de economia mista e fundação pública.", "secretarias, autarquias e conselhos.", "somente autarquias e empresas públicas.", "fundações e sindicatos."], "ci": 0, "why": "Art. 86, § 2º. Secretaria é órgão; autarquia é entidade, com personalidade jurídica própria.", "study": "LOM, Aula 02 (art. 86)"}, {"id": "v3-q077", "src": "Apostila Vol. 3", "num": 77, "top": 18, "tema": "v3-16", "stem": "Segundo a Lei Orgânica, a Guarda Municipal tem as seguintes características:", "opts": ["força militar, com poder de polícia judiciária.", "corporação do Estado, com atuação no Município.", "força auxiliar, uniformizada, armada se a lei dispuser, com função preventiva de proteção dos bens, serviços e instalações municipais, nos termos de lei complementar.", "órgão do Executivo estadual."], "ci": 2, "why": "Art. 85 e art. 7º, XLI. O ingresso é por concurso público. O STF (Tema 656) admite atuação em segurança urbana, sem polícia judiciária.", "study": "LOM, Aula 02 (art. 85)"}, {"id": "v3-q078", "src": "Apostila Vol. 3", "num": 78, "top": 18, "tema": "v3-16", "stem": "Ao servidor público investido no mandato de Vereador, havendo compatibilidade de horários:", "opts": ["afasta-se do cargo, podendo optar pela remuneração.", "deve exonerar-se.", "percebe apenas a remuneração do mandato.", "percebe as vantagens do cargo, emprego ou função e a remuneração do cargo eletivo."], "ci": 3, "why": "Art. 81, III. Para o mandato de Prefeito, afasta-se sempre, podendo optar pela remuneração.", "study": "LOM, Aula 02 (art. 81)"}, {"id": "v3-q079", "src": "Apostila Vol. 3", "num": 79, "top": 18, "tema": "v3-16", "stem": "O servidor nomeado para cargo efetivo adquire estabilidade após:", "opts": ["dois anos de efetivo exercício.", "três anos de efetivo exercício, com avaliação especial de desempenho.", "cinco anos de efetivo exercício.", "a posse, com aprovação em concurso."], "ci": 1, "why": "CF, art. 41, § 4º. Extinto o cargo, o servidor estável fica em disponibilidade remunerada até seu aproveitamento.", "study": "LOM, Aula 02 (art. 84)"}, {"id": "v3-q080", "src": "Apostila Vol. 3", "num": 80, "top": 13, "tema": "v3-17", "stem": "São impostos de competência do Município:", "opts": ["IPTU, ITBI e ISS.", "IPTU, ITCMD e ISS.", "IPTU, IPVA e ISS.", "ITBI, ICMS e ISS."], "ci": 0, "why": "Art. 116. ITCMD é estadual; IPVA é estadual. O ITBI incide sobre transmissão onerosa inter vivos.", "study": "LOM, Aula 02 (arts. 115 e 116)"}, {"id": "v3-q081", "src": "Apostila Vol. 3", "num": 81, "top": 13, "tema": "v3-17", "stem": "O IBS, instituído pela reforma tributária, é imposto:", "opts": ["exclusivo da União.", "de competência compartilhada entre Estados, Distrito Federal e Municípios.", "exclusivo dos Municípios.", "exclusivo dos Estados."], "ci": 1, "why": "Art. 156-A da CF. A substituição de ICMS e ISS é gradual: redução a partir de 2029 e extinção em 2033.", "study": "LOM, Aula 02 (reforma tributária)"}, {"id": "v3-q082", "src": "Apostila Vol. 3", "num": 82, "top": 13, "tema": "v3-17", "stem": "As taxas só podem ser instituídas por lei, em razão:", "opts": ["da prestação de qualquer serviço público, ainda que geral.", "do aumento do patrimônio do contribuinte.", "da valorização de imóvel por obra pública.", "do exercício do poder de polícia ou da utilização efetiva ou potencial de serviços públicos específicos e divisíveis."], "ci": 3, "why": "Art. 117. A valorização imobiliária por obra é fato gerador da contribuição de melhoria (art. 118). As taxas não podem ter base de cálculo própria de impostos.", "study": "LOM, Aula 02 (arts. 117 a 119)"}, {"id": "v3-q083", "src": "Apostila Vol. 3", "num": 83, "top": 13, "tema": "v3-17", "stem": "É vedado ao Município cobrar tributos:", "opts": ["após o prazo de 90 dias da publicação da lei.", "sobre livros, jornais e periódicos, sempre que houver lucro.", "no mesmo exercício financeiro em que haja sido publicada a lei que os instituiu ou aumentou, e em relação a fatos geradores anteriores à vigência da lei.", "sobre templos de qualquer culto, apenas se houver fim lucrativo."], "ci": 2, "why": "Art. 121, IV. Além das anterioridades, há a imunidade recíproca, a religiosa, a de partidos, sindicatos, entidades de educação e assistência, e a de livros, jornais, periódicos e papel.", "study": "LOM, Aula 02 (art. 121)"}, {"id": "v3-q084", "src": "Apostila Vol. 3", "num": 84, "top": 13, "tema": "v3-17", "stem": "A contribuição de melhoria tem como limite individual:", "opts": ["o acréscimo de valor que da obra resultar para cada imóvel beneficiado.", "o custo total da obra, por imóvel.", "20% do valor do imóvel.", "o valor venal do imóvel."], "ci": 0, "why": "Art. 118. O limite total é a despesa realizada com a obra (CTN).", "study": "LOM, Aula 02 (art. 118)"}, {"id": "v3-q085", "src": "Apostila Vol. 3", "num": 85, "top": 3, "tema": "v3-18", "stem": "As três leis orçamentárias, de iniciativa do Poder Executivo, são:", "opts": ["PPA, LRF e LOA.", "PPA, LDO e LOA.", "LDO, LOA e LC.", "LRF, LDO e LC."], "ci": 1, "why": "Art. 130. O PPA fixa diretrizes, objetivos e metas; a LDO orienta a LOA; a LOA estima receitas e fixa despesas.", "study": "LOM, Aula 02 (art. 130)"}, {"id": "v3-q086", "src": "Apostila Vol. 3", "num": 86, "top": 3, "tema": "v3-18", "stem": "Os projetos de lei do PPA, do orçamento anual e de créditos adicionais são apreciados, na Câmara, pela:", "opts": ["Comissão de Ética.", "Comissão Permanente de Orçamento e Finanças.", "Mesa Diretora.", "Comissão Representativa."], "ci": 1, "why": "Art. 131. Emendas só são aprovadas se compatíveis com o PPA e indicarem recursos de anulação de despesa (excluídas pessoal, encargos e serviço da dívida) ou corrigirem erros ou omissões.", "study": "LOM, Aula 02 (art. 131)"}, {"id": "v3-q087", "src": "Apostila Vol. 3", "num": 87, "top": 3, "tema": "v3-18", "stem": "Nos anos subsequentes ao primeiro, as emendas individuais ao orçamento são aprovadas no limite de:", "opts": ["0,8% da receita corrente líquida, sendo metade para a educação.", "1,2% da receita corrente líquida prevista no projeto, sendo metade para ações e serviços públicos de saúde.", "2% da receita total, sendo 1/3 para a saúde.", "1,2% da receita tributária."], "ci": 1, "why": "Art. 131, § 4º. No primeiro ano, 0,8%. A execução obrigatória usa a RCL realizada no exercício anterior (§ 6º).", "study": "LOM, Aula 02 (art. 131, §§ 4º e 6º)"}, {"id": "v3-q088", "src": "Apostila Vol. 3", "num": 88, "top": 3, "tema": "v3-18", "stem": "Em caso de impedimento técnico de emenda impositiva, o Executivo envia as justificativas ao Legislativo em até:", "opts": ["30 dias após a LOA.", "120 dias após a publicação da lei orçamentária.", "60 dias após a LOA.", "90 dias após a LDO."], "ci": 1, "why": "Art. 131, § 9º, I. Depois, o Legislativo indica o remanejamento em até 30 dias, e o Executivo envia projeto até 30 de setembro, ou em até 30 dias após o prazo anterior. A Câmara delibera até 20 de novembro, ou em até 30 dias após o prazo anterior.", "study": "LOM, Aula 02 (art. 131, § 9º)"}, {"id": "v3-q089", "src": "Apostila Vol. 3", "num": 89, "top": 3, "tema": "v3-18", "stem": "A lei orçamentária anual compreende:", "opts": ["apenas o orçamento fiscal.", "o orçamento fiscal e o previdenciário.", "o orçamento fiscal, o de investimento das empresas e o da seguridade social.", "o orçamento de investimentos e o de custeio."], "ci": 2, "why": "Art. 132. São partes de uma única lei.", "study": "LOM, Aula 02 (art. 132)"}, {"id": "v3-q090", "src": "Apostila Vol. 3", "num": 90, "top": 3, "tema": "v3-18", "stem": "Se o Prefeito não enviar a proposta orçamentária no prazo, a Câmara:", "opts": ["elabora a lei de meios, tomando por base a lei orçamentária em vigor.", "fica impedida de votar o orçamento.", "arquiva o assunto.", "convoca o Prefeito para depor."], "ci": 0, "why": "Art. 133, § 1º. Se a Câmara não enviar o projeto à sanção no prazo, será promulgado o projeto originário do Executivo (art. 134).", "study": "LOM, Aula 02 (arts. 133 e 134)"}]};
